window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s18-26","number":26,"surah":18,"verses":[12],"references":[{"surah":18,"verses":[12]}],"verseLabel":"الكهف: 12","question":"ما سرّ التعبير بـ﴿ثُمَّ بَعَثْنَاهُمْ﴾؟","answer":"استُعمل البعث في إيقاظهم بعد سكون النوم الطويل؛ فهو تحريك وإقامة من حال الرقاد، وأسند إلى ضمير العظمة لعجيب القدرة الظاهرة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص507، تحت «جمال الاستعارة في التعبير عن الإيقاظ بالبعث»","url":""}]},{"id":"s18-27","number":27,"surah":18,"verses":[12],"references":[{"surah":18,"verses":[12]}],"verseLabel":"الكهف: 12","question":"ما سرّ التعبير بـ﴿أَيُّ الْحِزْبَيْنِ أَحْصَى﴾؟","answer":"المعنى ظهور ما يعلمه الله في الواقع، لا حدوث علم بعد جهل. و«أحصى» تحتمل فعلًا ماضيًا بمعنى ضبط العدد، واسم تفضيل بمعنى أشد ضبطًا؛ فالسياق يميز إصابة التقدير من القول المبني على التخمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص509، تحت «بلاغة الكناية في لفظ العلم»","url":""}]},{"id":"s18-28","number":28,"surah":18,"verses":[13],"references":[{"surah":18,"verses":[13]}],"verseLabel":"الكهف: 13","question":"ما سرّ التعبير بـ﴿نَحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُمْ بِالْحَقِّ﴾؟","answer":"لقصر القصص الحق على خبر الله ونفي التخمينات؛ فالمقصود بيان الصدق ومواضع العبرة من القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص518، تحت «سر تقييد القص بقوله بالحق»","url":""}]},{"id":"s18-29","number":29,"surah":18,"verses":[13],"references":[{"surah":18,"verses":[13]}],"verseLabel":"الكهف: 13","question":"ما سرّ التعبير بـ﴿إِنَّهُمْ فِتْيَةٌ آمَنُوا﴾؟","answer":"افتتحت الجملة بـ﴿إن﴾ للاهتمام بخبرهم، ووصفوا بالفتية تعريفًا بحالهم، ثم ذُكرت زيادة هداهم بما وهبهم الله من التوفيق والثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص518، تحت «نكتة تصدير الجملة بأداة التوكيد»","url":""}]},{"id":"s18-30","number":30,"surah":18,"verses":[14],"references":[{"surah":18,"verses":[14]}],"verseLabel":"الكهف: 14","question":"ما سرّ التعبير بـ﴿وَرَبَطْنَا عَلَى قُلُوبِهِمْ﴾؟","answer":"الربط استعارة لتثبيت إيمانهم وإزالة التردد والاضطراب عن قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص525، تحت «جمال الاستعارة وربطنا»","url":""}]},{"id":"s18-31","number":31,"surah":18,"verses":[14],"references":[{"surah":18,"verses":[14]}],"verseLabel":"الكهف: 14","question":"ما دلالة قولهم ﴿رَبُّنَا رَبُّ السَّمَاوَاتِ وَالْأَرْضِ﴾؟","answer":"أثبتوا أن ربهم هو رب السماوات والأرض، فجاء الوصف كاشفًا لعموم ربوبيته، وبُني عليه امتناعهم من دعاء غيره إلهًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص527، تحت «فائدة الإخبار عن المسند إليه برب السماوات والأرض»","url":""}]},{"id":"s18-32","number":32,"surah":18,"verses":[15],"references":[{"surah":18,"verses":[15]}],"verseLabel":"الكهف: 15","question":"ما سرّ وصف الشرك بأنه ﴿شَطَطًا﴾؟","answer":"الشطط الإفراط في مخالفة الحق والصواب، واستعير من البعد؛ فدعاء غير الله قول بالغ البعد عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص531، تحت «دلالة لفظ شططًا وبلاغته»","url":""}]},{"id":"s18-33","number":33,"surah":18,"verses":[15],"references":[{"surah":18,"verses":[15]}],"verseLabel":"الكهف: 15","question":"ما دلالة مطالبة قومهم بـ﴿سُلْطَانٍ بَيِّنٍ﴾ على اتخاذ الآلهة؟","answer":"للتبكيت وإظهار أن اتخاذ الآلهة قام بلا حجة؛ فالسلطان هو البرهان، والبين واضح الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص538، تحت «نكتة تنكير سلطان ووصفه ببين»","url":""}]},{"id":"s18-34","number":34,"surah":18,"verses":[16],"references":[{"surah":18,"verses":[16]}],"verseLabel":"الكهف: 16","question":"ما دلالة قول الفتية بعضهم لبعض: ﴿فَأْوُوا إِلَى الْكَهْفِ﴾ بعد اعتزال القوم؟","answer":"كان ذلك نصحًا ومشورة بعد اليأس من رجوع قومهم، فانتقلوا من إعلان المفاصلة إلى اتخاذ الكهف مأوى يحفظ دينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص550، تحت «دلالة الأمر في فعل الإيواء»","url":""}]},{"id":"s18-35","number":35,"surah":18,"verses":[16],"references":[{"surah":18,"verses":[16]}],"verseLabel":"الكهف: 16","question":"ما سرّ التعبير بـ﴿يَنْشُرْ لَكُمْ رَبُّكُمْ مِنْ رَحْمَتِهِ﴾؟","answer":"صوّر سعة الرحمة وبسطها بصورة نشر الثوب المطوي؛ فالكهف وإن ضاق فقد يتسع لهم بلطف الله. وفي صيغة الجزم ثقة بوعده وحسن ظن برعايته لمن لجأ إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص553، تحت «براعة الاستعارة في ينشر لكم»","url":""}]},{"id":"s18-36","number":36,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما مناسبة تفصيل حركة الشمس لما سبق من إيواء الفتية إلى الكهف؟","answer":"جاء التفصيل ليكشف صورة العناية الإلهية بهم بعد دخولهم الكهف؛ فقد وصلهم من الضوء والهواء ما ينفعهم، وصُرف عنهم من حر الشمس ما يؤذي أجسادهم في نومهم الطويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص560، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s18-217","number":217,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما دلالة التعبير بالمضارع في قوله: ﴿وَتَرَى الشَّمْسَ﴾؟","answer":"يستحضر المضارع صورة الشمس وهي تتحرك حول الكهف عند الطلوع والغروب، حتى يبدو المشهد متجددًا حاضرًا يراه السامع بعينه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص566، تحت «نكتة التعبير بالمضارع في قوله تعالى: ﴿وَتَرَى﴾»","url":""}]},{"id":"s18-218","number":218,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما سر التعبير بالفعل ﴿تَزَاوَرُ﴾ عن حركة الشمس عند الكهف؟","answer":"يصوّر الفعل الشمس كأنها تميل وتنحرف عن موضع الفتية، فيجسّد حركة الضوء حول الكهف ويبرز حفظهم من حرها مع انتفاعهم بنورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص567، تحت «وجه التعبير بالفعل ﴿تَزَاوَرُ﴾ دون غيره»","url":""}]},{"id":"s18-37","number":37,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما سرّ الإشارة بالبعيد في قوله ﴿ذَلِكَ مِنْ آيَاتِ اللَّهِ﴾؟","answer":"اسم الإشارة البعيد يعظم ما سبق من عجيب حال الشمس وحفظ الفتية.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص574، تحت «سر التعبير باسم الإشارة ذلك»","url":""}]},{"id":"s18-219","number":219,"surah":18,"verses":[17],"references":[{"surah":18,"verses":[17]}],"verseLabel":"الكهف: 17","question":"ما دلالة ﴿مِنْ﴾ في قوله ﴿ذَلِكَ مِنْ آيَاتِ اللَّهِ﴾؟","answer":"تفيد أن هذا المشهد بعض آيات الله، فلا تنحصر دلائل قدرته فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص575، تحت «دلالة من في قوله ذلك من آيات الله»","url":""}]},{"id":"s18-38","number":38,"surah":18,"verses":[18],"references":[{"surah":18,"verses":[18]}],"verseLabel":"الكهف: 18","question":"ما سرّ التعبير بـ﴿وَتَحْسَبُهُمْ أَيْقَاظًا وَهُمْ رُقُودٌ﴾؟","answer":"لأن هيئتهم كانت تشبه حال اليقظة مع ثبوت رقادهم، فجاء التعبير تعجيبًا من حالهم وبيانًا لعظيم قدرة الله في شأنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص596، تحت «وجه حسبانهم أيقاظًا مع أنهم رقود»","url":""}]},{"id":"s18-39","number":39,"surah":18,"verses":[18],"references":[{"surah":18,"verses":[18]}],"verseLabel":"الكهف: 18","question":"ما سر التعبير بـ﴿وَنُقَلِّبُهُمْ﴾ في وصف حال الفتية أثناء نومهم؟","answer":"التقليب تغيير الجسد من جانب إلى جانب، وهو أخص من مطلق الحركة وأنسب بحال النائم. وصيغة التفعيل والمضارع تستحضر تكرره خلال نومهم، مع إسناده إلى الله لإظهار عنايته بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص598، تحت «علة التعبير بالتقليب دون الحركة»","url":""}]},{"id":"s18-40","number":40,"surah":18,"verses":[18],"references":[{"surah":18,"verses":[18]}],"verseLabel":"الكهف: 18","question":"ما دلالة كون كلبهم ﴿بَاسِطًا ذِرَاعَيْهِ بِالْوَصِيدِ﴾؟","answer":"يرسم التعبير الكلب في هيئة الحارس عند مدخل الكهف، وتثبت الجملة الاسمية بقاء تلك الهيئة. ومن توجيه «الوصيد» أنه مدخل الكهف المشبه بالباب أو فناؤه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص601، تحت «دلالة وصف الكلب ببسط ذراعيه»","url":""}]},{"id":"s18-41","number":41,"surah":18,"verses":[18],"references":[{"surah":18,"verses":[18]}],"verseLabel":"الكهف: 18","question":"ما دلالة تصوير الخوف من أصحاب الكهف بقوله: ﴿وَلَمُلِئْتَ مِنْهُمْ رُعْبًا﴾؟","answer":"صُورت النفس كوعاء يملؤه الرعب، فدل التعبير على استيلاء الخوف عليها. وذكر الملء بعد الفرار يصور استمرار الرعب حتى بعد الابتعاد عنهم، مع تكرار «منهم» لتأكيد هول المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص606، تحت «بلاغة الاستعارة في ولملئت منهم رعبًا»","url":""}]},{"id":"s18-42","number":42,"surah":18,"verses":[19],"references":[{"surah":18,"verses":[19]}],"verseLabel":"الكهف: 19","question":"ما سرّ التعبير بـ﴿وَكَذَلِكَ بَعَثْنَاهُمْ﴾؟","answer":"أي كما أنمناهم تلك القرون بعثناهم؛ فالإفاقة آية على عظيم قدرة الله مثل آية إنامتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص617، تحت «علة التعبير بالبعث دون غيره»","url":""}]},{"id":"s18-43","number":43,"surah":18,"verses":[19],"references":[{"surah":18,"verses":[19]}],"verseLabel":"الكهف: 19","question":"ما سرّ تسمية محاورة الفتية عن مدة لبثهم ﴿تَسَاؤُلًا﴾؟","answer":"لأن كل واحد منهم طلب من غيره تقدير المدة، فتبادلوا السؤال والرأي.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص619، تحت «سر تسمية المحاورة تساؤلًا»","url":""}]},{"id":"s18-220","number":220,"surah":18,"verses":[19],"references":[{"surah":18,"verses":[19]}],"verseLabel":"الكهف: 19","question":"ما دلالة تفويض الفتية علم مدة لبثهم إلى الله؟","answer":"لما لم يبلغوا اليقين تركوا الظن وفوضوا العلم إلى الله، وذلك من كمال إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص624، تحت «نكتة تفويض العلم بمدة لبثهم إلى الله تعالى»","url":""}]},{"id":"s18-44","number":44,"surah":18,"verses":[19],"references":[{"surah":18,"verses":[19]}],"verseLabel":"الكهف: 19","question":"ما سرّ قولهم ﴿رَبُّكُمْ أَعْلَمُ بِمَا لَبِثْتُمْ﴾؟","answer":"لما اختلفوا عدلوا عن القول بالظن إلى تفويض العلم لله، وذلك من كمال إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص623، تحت «دلالة التعبير بقوله ربكم أعلم بما لبثتم»","url":""}]},{"id":"s18-45","number":45,"surah":18,"verses":[19],"references":[{"surah":18,"verses":[19]}],"verseLabel":"الكهف: 19","question":"ما سرّ التعبير بـ﴿أَيُّهَا أَزْكَى طَعَامًا﴾؟","answer":"«أزكى» تجمع وجوهًا من طيب الطعام وجودته وطهارته وحلّه؛ فطلبوا ما هو أكثر خيرًا وأنفع وأبعد عن الحرام. وصيغة التفضيل تدل على عنايتهم بالاختيار، لا الاكتفاء بأي طعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص631، تحت «سر التعبير بأزكى دون أفضل»","url":""}]},{"id":"s18-46","number":46,"surah":18,"verses":[20],"references":[{"surah":18,"verses":[20]}],"verseLabel":"الكهف: 20","question":"ما سرّ تخصيص الرجم في قول الفتية ﴿يَرْجُمُوكُمْ﴾؟","answer":"لأنه من أشد العقوبات وأشنعها، فصور ما يخشونه على أجسادهم إن ظهر القوم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص642، تحت «سر ذكر الرجم دون غيره من العقوبات»","url":""}]},{"id":"s18-221","number":221,"surah":18,"verses":[20],"references":[{"surah":18,"verses":[20]}],"verseLabel":"الكهف: 20","question":"ما دلالة ترتيب نفي الفلاح على الرجوع إلى ملة القوم؟","answer":"يبين أن الرجوع الحقيقي إلى الكفر والاستمرار عليه يفضي إلى خسران لا فلاح معه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص645، تحت «دلالة ترتيب نفي الفلاح على الإكراه على الرجوع إلى الكفر»","url":""}]},{"id":"s18-47","number":47,"surah":18,"verses":[21],"references":[{"surah":18,"verses":[21]}],"verseLabel":"الكهف: 21","question":"ما سرّ التعبير بـ﴿وَكَذَلِكَ أَعْثَرْنَا عَلَيْهِمْ﴾؟","answer":"يشبه إطلاع الناس عليهم بإنامتهم وإيقاظهم في كونه آية على القدرة. ولفظ «أعثرنا» يصور الوصول إلى خبرهم بعد خفائه، لتقوم به العبرة ويظهر صدق البعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص651، تحت «بلاغة الاستعارة التصريحية»","url":""}]},{"id":"s18-48","number":48,"surah":18,"verses":[21],"references":[{"surah":18,"verses":[21]}],"verseLabel":"الكهف: 21","question":"ما دلالة قوله ﴿لِيَعْلَمُوا أَنَّ وَعْدَ اللَّهِ حَقٌّ﴾؟","answer":"جعل العثور عليهم برهانًا مشاهدًا على إحياء الموتى والبعث، فازداد علم القوم بكيفية ما كانوا يؤمنون به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص653، تحت «نكتة ذكر الحق دون الصدق»","url":""}]},{"id":"s18-49","number":49,"surah":18,"verses":[22],"references":[{"surah":18,"verses":[22]}],"verseLabel":"الكهف: 22","question":"ما سرّ التعبير بـ﴿رَجْمًا بِالْغَيْبِ﴾؟","answer":"استعير الرجم لرمي الكلام من غير روية ولا تثبت، كما يُرمى الحجر نحو ما لا يُعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص671، تحت «بلاغة الاستعارة التصريحية في لفظ رجمًا»","url":""}]},{"id":"s18-50","number":50,"surah":18,"verses":[22],"references":[{"surah":18,"verses":[22]}],"verseLabel":"الكهف: 22","question":"ما دلالة العدول إلى قوله: ﴿مَا يَعْلَمُهُمْ إِلَّا قَلِيلٌ﴾ بعد اختلاف الأقوال في عدد الفتية؟","answer":"وجّه التعبير العناية إلى معرفة الفتية وصفاتهم ومواضع العبرة من قصتهم، بدل الاستغراق في تعدادهم. وأثبت أن العلم بهم لقليل ممن أطلعهم الله، فيعلم القارئ الوقوف عند الدليل وترك التخمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص675، تحت «نكتة العدول عن ذكر العدد إلى ذكر الذات»","url":""}]},{"id":"s18-51","number":51,"surah":18,"verses":[22],"references":[{"surah":18,"verses":[22]}],"verseLabel":"الكهف: 22","question":"ما سرّ التعبير بـ﴿فَلَا تُمَارِ فِيهِمْ إِلَّا مِرَاءً ظَاهِرًا﴾؟","answer":"المراء الظاهر هو ما كانت حجته واضحة ولا يطول الخوض فيه؛ وما وراء ذلك قليل الجدوى محتاج إلى دليل فلا ينبغي الاشتغال به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص677، تحت «نكتة تقييد المراء بقوله ظاهرًا»","url":""}]},{"id":"s18-52","number":52,"surah":18,"verses":[23,24],"references":[{"surah":18,"verses":[23,24]}],"verseLabel":"الكهف: 23-24","question":"ما دلالة تعليق العزم على الفعل المستقبل بمشيئة الله؟","answer":"لئلا يُجزم بفعل مستقبل دون تقييده بمشيئة الله وإذنه؛ فجاء النهي تعليمًا لأدب الوعد والإخبار عن العزم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص684، تحت «غرض النهي في ولا تقولن»","url":""}]},{"id":"s18-53","number":53,"surah":18,"verses":[24],"references":[{"surah":18,"verses":[24]}],"verseLabel":"الكهف: 24","question":"ما دلالة قوله ﴿وَاذْكُرْ رَبَّكَ إِذَا نَسِيتَ﴾؟","answer":"من توجيهاته أن من نسي ذكر المشيئة يستدركه عندما يتذكر، مع تذكر عظمة الله وامتثال أمره. وحذف مفعول «نسيت» يناسب ظهوره من السياق ويعنى ببيان ما يصنعه الناسي عند التذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص687، تحت «بلاغة الكناية في الأمر بالذكر»","url":""}]},{"id":"s18-54","number":54,"surah":18,"verses":[24],"references":[{"surah":18,"verses":[24]}],"verseLabel":"الكهف: 24","question":"ما دلالة قوله ﴿عَسَى أَنْ يَهْدِيَنِ رَبِّي لِأَقْرَبَ مِنْ هَذَا رَشَدًا﴾؟","answer":"يعلم التعبير رجاء الهداية من الله وطلب الأقرب إلى الرشد. ومن توجيهاته رجاء الانتقال إلى ما هو أهم في الهداية من مجاراة السائلين في القصة، ومن توجيهاته التدارك بما هو أحسن وأكمل مما عزم عليه الإنسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص689، تحت «نكتة استعمال عسى»","url":""}]},{"id":"s18-55","number":55,"surah":18,"verses":[25],"references":[{"surah":18,"verses":[25]}],"verseLabel":"الكهف: 25","question":"ما سرّ التعبير بـ﴿ثَلَاثَ مِائَةٍ سِنِينَ وَازْدَادُوا تِسْعًا﴾؟","answer":"من توجيهات فصل الزيادة بتسع سنوات الإشارة إلى اختلاف الحسابين: ثلاثمائة سنة شمسية تقابل نحو ثلاثمائة وتسع سنين قمرية. فيجمع التعبير أصل المدة والزيادة الناشئة عن اختلاف طريقة الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص692، تحت «المعنى الإجمالي»","url":""}]},{"id":"s18-56","number":56,"surah":18,"verses":[26],"references":[{"surah":18,"verses":[26]}],"verseLabel":"الكهف: 26","question":"ما دلالة قوله ﴿قُلِ اللَّهُ أَعْلَمُ بِمَا لَبِثُوا﴾ بعد ذكر المدة؟","answer":"لقطع المماراة في مدة لبثهم ورد علمها إلى الله؛ وعلى وجه حكاية قول أهل الكتاب يكون تفويضًا للعلم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص694، تحت «علة فصل قوله تعالى قل الله أعلم بما لبثوا»","url":""}]},{"id":"s18-57","number":57,"surah":18,"verses":[26],"references":[{"surah":18,"verses":[26]}],"verseLabel":"الكهف: 26","question":"ما سرّ التعبير بـ﴿أَبْصِرْ بِهِ وَأَسْمِعْ﴾؟","answer":"جاء التعبير بصيغة التعجب ليقرر كمال سمع الله وبصره وإحاطته بالدقيق والجليل، والظاهر والباطن؛ فلا تدرك الخلائق مدى هذا الكمال ولا تحيط به.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص697، تحت «غرض التعجب وبلاغته»","url":""}]},{"id":"s18-58","number":58,"surah":18,"verses":[27],"references":[{"surah":18,"verses":[27]}],"verseLabel":"الكهف: 27","question":"ما دلالة قوله ﴿لَا مُبَدِّلَ لِكَلِمَاتِهِ﴾ عقب الأمر بتلاوة الوحي؟","answer":"تقرير وجوب تلاوة الوحي كله كما أُنزل؛ فلا يملك أحد تبديل كلماته، ولا يسوغ إخفاء شيء منه بحذف أو زيادة استجابة لضغط المشركين.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص706، تحت «سر التعبير باسم الفاعل مبدل»","url":""}]},{"id":"s18-59","number":59,"surah":18,"verses":[28],"references":[{"surah":18,"verses":[28]}],"verseLabel":"الكهف: 28","question":"ما سرّ التعبير بـ﴿وَاصْبِرْ نَفْسَكَ﴾؟","answer":"أي احبس نفسك وثبّتها مع الذين يدعون ربهم، ولا تفارقهم استجابة لرغبة أهل الكبر؛ فعدّي الصبر إلى النفس لإفادة حبسها على هذه الملازمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص714، تحت «بلاغة الإطناب بذكر قيد نفسك»","url":""}]},{"id":"s18-60","number":60,"surah":18,"verses":[28],"references":[{"surah":18,"verses":[28]}],"verseLabel":"الكهف: 28","question":"ما سرّ التعبير بـ﴿يُرِيدُونَ وَجْهَهُ﴾؟","answer":"يبين القيد إخلاصهم لله؛ فهم يدعونه ويعبدونه ابتغاء رضاه، لا طلبًا لعرض الدنيا. والمضارع يستحضر تجدد هذه الإرادة واستمرارها مع عبادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص720، تحت «نكتة التقييد بقوله يريدون وجهه»","url":""}]},{"id":"s18-61","number":61,"surah":18,"verses":[28],"references":[{"surah":18,"verses":[28]}],"verseLabel":"الكهف: 28","question":"ما سرّ التعبير بـ﴿وَلَا تَعْدُ عَيْنَاكَ عَنْهُمْ﴾؟","answer":"نُسب التجاوز إلى العينين كناية عن ترك مجالستهم؛ أي لا تصرف نظرك عنهم إلى أهل الدنيا طلبًا لزينتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص722، تحت «نكتة المجاز المرسل»","url":""}]},{"id":"s18-62","number":62,"surah":18,"verses":[28],"references":[{"surah":18,"verses":[28]}],"verseLabel":"الكهف: 28","question":"ما سرّ وصف أمر الغافل بأنه ﴿فُرُطًا﴾؟","answer":"من معاني «فرطًا» الإفراط وتجاوز الحد في الظلم، ومن معانيها التفريط والتضييع فيما يلزم من أمر الدين. و«كان» تدل على تمكن هذا الخلل من حاله، بعد وصفه بالغفلة واتباع الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص730، تحت «بلاغة الاستعارة في قوله أمره فرطًا»","url":""}]},{"id":"s18-63","number":63,"surah":18,"verses":[29],"references":[{"surah":18,"verses":[29]}],"verseLabel":"الكهف: 29","question":"ما دلالة قوله ﴿فَمَنْ شَاءَ فَلْيُؤْمِنْ وَمَنْ شَاءَ فَلْيَكْفُرْ﴾؟","answer":"ليس إذنًا بالكفر، بل الأمر للتسوية المكنى بها عن الوعد والوعيد، وقد كشف ما بعدها وخامة عاقبة من يستمر على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص738، تحت «بلاغة الكناية في فليؤمن وفليكفر»","url":""}]},{"id":"s18-64","number":64,"surah":18,"verses":[29],"references":[{"surah":18,"verses":[29]}],"verseLabel":"الكهف: 29","question":"ما دلالة إحاطة سرادق النار بالظالمين؟","answer":"صُورت النار دارًا يحيط بها سرادق، مبالغة في إحاطة دار العذاب بهم؛ وفي استعارة شعار بيوت المترفين للنار تهكم بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص743، تحت «بلاغة التشبيه والاستعارة في لفظ سرادقها»","url":""}]},{"id":"s18-65","number":65,"surah":18,"verses":[29],"references":[{"surah":18,"verses":[29]}],"verseLabel":"الكهف: 29","question":"ما سرّ تشبيه ماء أهل النار بـ﴿الْمُهْلِ﴾؟","answer":"للمهْل تفسيرات منها دُردي الزيت ومنها ما أذيب من المعادن، ويصور التشبيه سواد الماء وشدة حرارته. فبدل أن يبرد المستغيثين يزيدهم عذابًا، حتى يشوي وجوههم عند اقترابه منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص746، تحت «براعة تشبيه الماء بالمهل»","url":""}]},{"id":"s18-66","number":66,"surah":18,"verses":[30],"references":[{"surah":18,"verses":[30]}],"verseLabel":"الكهف: 30","question":"ما دلالة قوله ﴿إِنَّا لَا نُضِيعُ أَجْرَ مَنْ أَحْسَنَ عَمَلًا﴾؟","answer":"طمأنة للمؤمنين بأن عملهم مرعي عند ربهم، وصيغ الحكم عامًا ليشملهم وكل من يماثلهم في إحسان العمل، مع مزيد توكيد لتحقيق الجزاء لأربابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص757، تحت «فائدة التعبير بالموصول من»","url":""}]},{"id":"s18-68","number":68,"surah":18,"verses":[32],"references":[{"surah":18,"verses":[32]}],"verseLabel":"الكهف: 32","question":"ما دلالة ضرب مثل الرجلين بعد بيان حال المؤمنين والكافرين؟","answer":"لتمثيل حال الفريقين بقصة تظهر عاقبة غرور الكافر وخسارته، وعاقبة المؤمن المتواضع العارف بسنن الله؛ فتجعل المعنى العقدي في صورة محسوسة أوقع في العبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص775، تحت «بلاغة التمثيل بحال الرجلين»","url":""}]},{"id":"s18-69","number":69,"surah":18,"verses":[32],"references":[{"surah":18,"verses":[32]}],"verseLabel":"الكهف: 32","question":"ما دلالة إحاطة الجنتين بالنخل في قوله ﴿وَحَفَفْنَاهُمَا بِنَخْلٍ﴾؟","answer":"يصوّر النخل محيطًا بالجنتين إحاطة تحفظهما وتزيدهما جمالًا ونفعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص776، تحت «بلاغة استعمال وحففناهما التصويرية»","url":""}]},{"id":"s18-222","number":222,"surah":18,"verses":[32],"references":[{"surah":18,"verses":[32]}],"verseLabel":"الكهف: 32","question":"ما سرّ تقديم ﴿بَيْنَهُمَا﴾ في قوله ﴿وَجَعَلْنَا بَيْنَهُمَا زَرْعًا﴾؟","answer":"للاهتمام بموقع الزرع بين الجنتين وتصوير إحكام ترتيب الضيعة وتكاملها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص778، تحت «غرض تقديم بينهما على زرعًا»","url":""}]},{"id":"s18-70","number":70,"surah":18,"verses":[33],"references":[{"surah":18,"verses":[33]}],"verseLabel":"الكهف: 33","question":"ما سرّ التعبير بـ﴿وَلَمْ تَظْلِمْ مِنْهُ شَيْئًا﴾ في وصف الجنتين؟","answer":"استعير الظلم للنقص: فقد أوفت كل جنة بما يُترقب من مقدار الثمر في حال الخصب، فكأن نقصان الغلة حرمان لصاحب حق.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص780، تحت «فائدة الاستعارة في قوله ولم تظلم»","url":""}]},{"id":"s18-71","number":71,"surah":18,"verses":[34],"references":[{"surah":18,"verses":[34]}],"verseLabel":"الكهف: 34","question":"ما سرّ التعبير بـ﴿وَكَانَ لَهُ ثَمَرٌ﴾ بعد ذكر الجنتين؟","answer":"تحتمل «الثمر» حمل الشجر، وتأتي في بعض توجيهات اللفظ والقراءات بمعنى المال الكثير المتنوع. وعلى معنى المال، يتسع وصف غناه لما وراء محصول الجنتين؛ فلا يصح حصر اللفظ في معنى واحد مع تعدد توجيهاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص784، تحت «بديع اختيار الألفاظ وأثرها في الإيجاز»","url":""}]},{"id":"s18-72","number":72,"surah":18,"verses":[34],"references":[{"surah":18,"verses":[34]}],"verseLabel":"الكهف: 34","question":"ما دلالة قوله تعالى: ﴿وَهُوَ يُحَاوِرُهُ﴾؟","answer":"جاءت الجملة حالًا تستحضر تفاخر صاحب الجنتين أثناء الحوار نفسه، وتصور تبادل الكلام بينه وبين صاحبه المؤمن؛ أحدهما يعتد بماله ونفره والآخر يراجعه بالنصح والحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص786، تحت «بلاغة جملة ﴿وَهُوَ يُحَاوِرُهُ﴾»","url":""}]},{"id":"s18-223","number":223,"surah":18,"verses":[34],"references":[{"surah":18,"verses":[34]}],"verseLabel":"الكهف: 34","question":"ما دلالة إضافة الصاحب إلى ضمير صاحب الجنتين في قوله: ﴿قَالَ لَهُ صَاحِبُهُ﴾؟","answer":"تكشف الإضافة صلة الصحبة والتواصل بين الرجلين، وتبرز أن قرب المؤمن منه لم يمنعه من نصحه. وفيها كذلك تنبيه للمؤمن إلى أثر الصحبة وضرورة الحذر من الاغترار بزينة الدنيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص785، تحت «معنى إضافة الصاحب إلى الضمير»","url":""}]},{"id":"s18-73","number":73,"surah":18,"verses":[35],"references":[{"surah":18,"verses":[35]}],"verseLabel":"الكهف: 35","question":"ما دلالة قوله ﴿وَهُوَ ظَالِمٌ لِنَفْسِهِ﴾ عند دخوله جنته؟","answer":"يكشف الوصف حقيقة حاله وهو داخل في زهو نعمته: كان مشركًا مكذبًا بالبعث بطرًا بنعمة الله عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص793، تحت «الغرض من ورود الخبر ظالم اسم فاعل»","url":""}]},{"id":"s18-74","number":74,"surah":18,"verses":[35],"references":[{"surah":18,"verses":[35]}],"verseLabel":"الكهف: 35","question":"ما سرّ التعبير بـ﴿مَا أَظُنُّ أَنْ تَبِيدَ هَذِهِ أَبَدًا﴾؟","answer":"أشار بـ﴿هذه﴾ إلى الجنة الحاضرة التي دخلاها، ونفى اعتقاده زوالها؛ والمراد بالأبد طول المدة وبقاؤها بقاء أمثالها، اغترارًا بقوة أسباب نمائها ودوامها.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص794، تحت «نكتة التعبير باسم الإشارة هذه»","url":""}]},{"id":"s18-75","number":75,"surah":18,"verses":[36],"references":[{"surah":18,"verses":[36]}],"verseLabel":"الكهف: 36","question":"ما دلالة قوله ﴿وَلَئِنْ رُدِدْتُ إِلَى رَبِّي﴾؟","answer":"قاله تهكمًا بصاحبه المؤمن بعد أن نفى قيام الساعة؛ ثم بالغ في التهكم بلام القسم ونون التوكيد مدعيًا أنه ـ على فرض الرد ـ سيجد خيرًا من جنتيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج29، ص799، تحت «غرض الإخبار في ولئن رددت»","url":""}]},{"id":"s18-76","number":76,"surah":18,"verses":[37],"references":[{"surah":18,"verses":[37]}],"verseLabel":"الكهف: 37","question":"ما دلالة تذكير صاحب الجنتين بخلقه من تراب ثم من نطفة؟","answer":"يذكّره بأصل خلقه ومراحله، من التراب إلى النطفة، ليقيم عليه الحجة في إنكار البعث؛ فمن أوجده أول مرة قادر على إعادته. وفي تذكيره بهذه البداية الضعيفة تقريع على جحوده واغتراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص15، تحت «معنى من ودلالتها في من تراب»","url":""}]},{"id":"s18-77","number":77,"surah":18,"verses":[37],"references":[{"surah":18,"verses":[37]}],"verseLabel":"الكهف: 37","question":"ما سرّ التعبير بـ﴿ثُمَّ سَوَّاكَ رَجُلًا﴾؟","answer":"تُبرز «ثم» التدرج بين أطوار الخلق، و«سواك» تحقق العناية بإيجاده إنسانًا سويًّا. و«رجلًا» حال تشير إلى بلوغ مرحلة الرجولة والقوة؛ فتزيد تقريعه على جحود نعمة من خلقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص17، تحت «دلالة التعبير بالفعل الماضي سواك»","url":""}]},{"id":"s18-78","number":78,"surah":18,"verses":[38],"references":[{"surah":18,"verses":[38]}],"verseLabel":"الكهف: 38","question":"ما دلالة قول المؤمن: ﴿لَكِنَّا هُوَ اللَّهُ رَبِّي﴾؟","answer":"بعد إنكار اعتقاد صاحبه، يعلن المؤمن اعتقاده هو. والاستدراك يبرز المقابلة بين كفر صاحبه وتوحيده؛ فليست مواجهته بالفخر بالمال، بل بالتصريح بأن الله ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص18، تحت «معنى لكنا ودلالتها في السياق»","url":""}]},{"id":"s18-79","number":79,"surah":18,"verses":[38],"references":[{"surah":18,"verses":[38]}],"verseLabel":"الكهف: 38","question":"ما سرّ التعبير بـ﴿وَلَا أُشْرِكُ بِرَبِّي أَحَدًا﴾ لا «واحدًا»؟","answer":"«أحدًا» في سياق النفي أعم؛ تنفي أي شريك على أي صورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص20، تحت «نكتة إيثار التعبير بأحدًا دون واحدًا»","url":""}]},{"id":"s18-80","number":80,"surah":18,"verses":[39],"references":[{"surah":18,"verses":[39]}],"verseLabel":"الكهف: 39","question":"ما دلالة قول صاحب المؤمن لصاحبه: ﴿مَا شَاءَ اللَّهُ﴾؟","answer":"هو إقرار بأن ما في الجنة من خير حاصل بمشيئة الله، لا باستحقاق الإنسان واستقلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص26، تحت «معنى ما ودلالتها»","url":""}]},{"id":"s18-224","number":224,"surah":18,"verses":[39],"references":[{"surah":18,"verses":[39]}],"verseLabel":"الكهف: 39","question":"ما دلالة القصر في قوله ﴿لَا قُوَّةَ إِلَّا بِاللَّهِ﴾؟","answer":"ينفي استقلال العبد بالقوة، ويثبت أن قدرته على العمل والحفظ لا تكون إلا بمعونة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص27، تحت «دلالة القصر في لا قوة إلا بالله»","url":""}]},{"id":"s18-81","number":81,"surah":18,"verses":[39],"references":[{"surah":18,"verses":[39]}],"verseLabel":"الكهف: 39","question":"ما سرّ التعبير بـ﴿إِنْ تَرَنِ أَنَا أَقَلَّ مِنْكَ﴾؟","answer":"يرد على تفاخر صاحبه بكثرة المال والولد، ويربط القلة الحالية برجاء فضل الله؛ فقد يؤتيه خيرًا من جنته. فلا تجعل قلة المال المؤمن حقيرًا، ولا تجعل كثرته عند الآخر ضمانًا لدوام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص28، تحت «دلالة التعبير بأقل في السياق»","url":""}]},{"id":"s18-82","number":82,"surah":18,"verses":[40],"references":[{"surah":18,"verses":[40]}],"verseLabel":"الكهف: 40","question":"ما سرّ التعبير بـ﴿حُسْبَانًا مِنَ السَّمَاءِ﴾؟","answer":"الحسبان عذاب من السماء، ومن تفسيره الصواعق أو النار. وتقييده بـ«من السماء» يشدد التهديد؛ فهو عذاب نازل من فوق لا يملك دفعه، وفي ذلك بيان لعجزه أمام قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص33، تحت «الغرض من القيد بالجار والمجرور من السماء»","url":""}]},{"id":"s18-83","number":83,"surah":18,"verses":[40],"references":[{"surah":18,"verses":[40]}],"verseLabel":"الكهف: 40","question":"ما دلالة وصف مآل الجنة بأنها ﴿صَعِيدًا زَلَقًا﴾؟","answer":"تتحول الجنة إلى أرض جرداء ملساء تزِل عليها القدم، بعد كثرة الشجر والنبات. ووصفها بـ«زلقًا» يزيد تصوير الخراب والخلو من أسباب النماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص35، تحت «سر وصف الصعيد بزلقًا ودلالتها»","url":""}]},{"id":"s18-84","number":84,"surah":18,"verses":[41],"references":[{"surah":18,"verses":[41]}],"verseLabel":"الكهف: 41","question":"ما سرّ وصف الماء بالمصدر في قوله ﴿أَوْ يُصْبِحَ مَاؤُهَا غَوْرًا﴾؟","answer":"جاء المصدر وصفًا للمبالغة، فكأن الماء نفسه صار غؤورًا لشدة ذهابه في الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص36، تحت «الغرض من التعبير بالمصدر غورًا»","url":""}]},{"id":"s18-225","number":225,"surah":18,"verses":[41],"references":[{"surah":18,"verses":[41]}],"verseLabel":"الكهف: 41","question":"ما دلالة قوله عن الماء الغائر ﴿فَلَنْ تَسْتَطِيعَ لَهُ طَلَبًا﴾؟","answer":"يبلغ في إظهار العجز؛ فلا يستطيع الوصول إلى الماء ولا تحصيله وردّه إلى جنته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص37، تحت «دلالة التعبير بلفظ الطلب»","url":""}]},{"id":"s18-85","number":85,"surah":18,"verses":[42],"references":[{"surah":18,"verses":[42]}],"verseLabel":"الكهف: 42","question":"ما دلالة التعبير بـ﴿وَأُحِيطَ بِثَمَرِهِ﴾؟","answer":"الإحاطة كناية عن الهلاك والفساد؛ تشبه استيلاء العدو على الشيء من جميع جوانبه. وهي تصور شمول الهلاك لما كان يعتز به صاحب الجنتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص42، تحت «الغرض من التعبير بالكناية في الآية»","url":""}]},{"id":"s18-86","number":86,"surah":18,"verses":[42],"references":[{"surah":18,"verses":[42]}],"verseLabel":"الكهف: 42","question":"ما سرّ التعبير بـ﴿بِثَمَرِهِ﴾ لا «بزرعه» أو «جنتيه»؟","answer":"الثمر هو الغاية التي يرجوها صاحب الزرع، فذكر هلاكه يزيد تصوير الفجيعة بعد الإنفاق وانتظار الانتفاع. وتعدد توجيهات «الثمر» وقراءاته يتسع للمحصول والمال، مع دلالة السياق على خراب الأصل أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص43، تحت «سر التعبير بالقيد بثمره»","url":""}]},{"id":"s18-87","number":87,"surah":18,"verses":[42],"references":[{"surah":18,"verses":[42]}],"verseLabel":"الكهف: 42","question":"ما سرّ التعبير بـ﴿يُقَلِّبُ كَفَّيْهِ﴾؟","answer":"تقليب الكفين كناية عن الندم والحسرة، تُرى في حركة اليدين شدة ما أصابه. وصيغة المضارع تستحضر تكرر هذه الحركة واستمرار تحسره على ما أنفق في جنته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص45، تحت «الغرض من التعبير بالكناية في سياق الآية»","url":""}]},{"id":"s18-88","number":88,"surah":18,"verses":[42],"references":[{"surah":18,"verses":[42]},{"surah":22,"verses":[45]}],"verseLabel":"الكهف: 42؛ الحج: 45","question":"ما دلالة وصف جنة صاحب الجنتين بأنها ﴿خَاوِيَةٌ عَلَى عُرُوشِهَا﴾؟","answer":"يصور خراب الجنة وسقوطها على ما رفعت عليه كرومها، فجمع هلاك الثمر وأصله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص48، تحت «سر التقييد بعروشها دون غيرها»","url":""}]},{"id":"s18-226","number":226,"surah":18,"verses":[42],"references":[{"surah":18,"verses":[42]},{"surah":22,"verses":[45]}],"verseLabel":"الكهف: 42؛ الحج: 45","question":"ما دلالة وصف القرية في سورة الحج بأنها ﴿خَاوِيَةٌ عَلَى عُرُوشِهَا﴾؟","answer":"كناية عن غاية خرابها؛ تهدمت سقوفها ثم سقطت الجدران فوقها، وقيل خلت من أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج34، ص726، تحت «بلاغة الكناية في خاوية على عروشها»","url":""}]},{"id":"s18-89","number":89,"surah":18,"verses":[43],"references":[{"surah":18,"verses":[43]}],"verseLabel":"الكهف: 43","question":"ما سرّ التعبير بـ﴿وَلَمْ تَكُنْ لَهُ فِئَةٌ يَنْصُرُونَهُ﴾؟","answer":"ينفي وجود فئة تستطيع دفع العذاب عنه، لا مجرد أنها امتنعت عن نصرته؛ فالمقام مقام عجز أمام قدرة الله. ويضم إليه ﴿وَمَا كَانَ مُنْتَصِرًا﴾ لينفي قدرته على إنقاذ نفسه أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص54، تحت «سر التعبير بفعل الكون»","url":""}]},{"id":"s18-90","number":90,"surah":18,"verses":[44],"references":[{"surah":18,"verses":[44]}],"verseLabel":"الكهف: 44","question":"ما سرّ تقديم ﴿هُنَالِكَ﴾ في ﴿هُنَالِكَ الْوَلَايَةُ لِلَّهِ الْحَقِّ﴾؟","answer":"يشير إلى لحظة سقوط الأسباب خاصة؛ عندها يظهر بلا غطاء أن السلطان والنصرة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص60، تحت «الغرض من تقديم هنالك على الولاية»","url":""}]},{"id":"s18-91","number":91,"surah":18,"verses":[45],"references":[{"surah":18,"verses":[45]}],"verseLabel":"الكهف: 45","question":"ما دلالة تمثيل الحياة الدنيا بالماء والنبات الذي يصير هشيمًا؟","answer":"يضرب المثل لسرعة نضارة الدنيا ثم زوالها؛ فالنبات ينتعش بالماء ويشتبك، ثم يصير هشيمًا تفرقه الرياح. والمقصود تشبيه دورة الازدهار والفناء، لا تشبيه الدنيا بالماء وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص68، تحت «دلالة أسلوب التمثيل في السياق»","url":""}]},{"id":"s18-92","number":92,"surah":18,"verses":[45],"references":[{"surah":18,"verses":[45]}],"verseLabel":"الكهف: 45","question":"ما سرّ التعبير بـ﴿فَأَصْبَحَ هَشِيمًا تَذْرُوهُ الرِّيَاحُ﴾؟","answer":"الفاء تسرع الانتقال من الاخضرار إلى التفتت، والرياح تفرق ما ظن ثابتًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص72، تحت «دلالة التعبير بصيغة فعيل في هشيم»","url":""}]},{"id":"s18-93","number":93,"surah":18,"verses":[46],"references":[{"surah":18,"verses":[46]}],"verseLabel":"الكهف: 46","question":"ما دلالة وصف المال والبنين بأنهما ﴿زِينَةُ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"وصفهما بالزينة يقر بما فيهما من جمال وقوة في الدنيا، لكنه يبين محدودية ذلك وزواله. وإضافة الزينة إلى الحياة الدنيا تمهد للمقابلة بالأعمال الصالحة التي يبقى نفعها في الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص79، تحت «سر إضافة الزينة إلى الحياة»","url":""}]},{"id":"s18-94","number":94,"surah":18,"verses":[46],"references":[{"surah":18,"verses":[46]}],"verseLabel":"الكهف: 46","question":"ما دلالة وصف الباقيات الصالحات بأنها ﴿خَيْرٌ أَمَلًا﴾؟","answer":"لأن أثرها يبقى عند الله، فهي خير في الثواب وخير فيما يصح أن يعلّق به الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص83، تحت «سر التقييد بالتمييز أملًا»","url":""}]},{"id":"s18-95","number":95,"surah":18,"verses":[47],"references":[{"surah":18,"verses":[47]}],"verseLabel":"الكهف: 47","question":"ما سرّ التعبير بـ﴿وَيَوْمَ نُسَيِّرُ الْجِبَالَ﴾؟","answer":"المضارع يستحضر تسيير الجبال كأنه مشهد يُرى، فيعظم وقعه في النفس. وافتتاح الكلام بذكر اليوم يجمع أهوال ذلك الموقف ويهيئ السامع لما بعده من بروز الأرض والحشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص87، تحت «دلالة التعبير بالفعل المضارع»","url":""}]},{"id":"s18-96","number":96,"surah":18,"verses":[47],"references":[{"surah":18,"verses":[47]}],"verseLabel":"الكهف: 47","question":"ما سرّ التعبير بـ﴿وَتَرَى الْأَرْضَ بَارِزَةً﴾؟","answer":"بعد زوال الجبال والستر تبدو الأرض مكشوفة لا مخبأ فيها ولا معلم يحجب أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص89، تحت «الغرض من تنكير بارزة»","url":""}]},{"id":"s18-97","number":97,"surah":18,"verses":[47],"references":[{"surah":18,"verses":[47]}],"verseLabel":"الكهف: 47","question":"ما سرّ التعبير بـ﴿فَلَمْ نُغَادِرْ مِنْهُمْ أَحَدًا﴾؟","answer":"تنكير «أحدًا» في سياق النفي يفيد الاستغراق؛ فلا يتخلف عن الحشر فرد من الأولين أو الآخرين. وجاء نفي المغادرة بعد ﴿وَحَشَرْنَاهُمْ﴾ توكيدًا لشمول الجمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص92، تحت «دلالة التعبير بالمفعول به لفظ أحدًا منكرًا»","url":""}]},{"id":"s18-98","number":98,"surah":18,"verses":[48],"references":[{"surah":18,"verses":[48]}],"verseLabel":"الكهف: 48","question":"ما دلالة عرض الناس على ربهم ﴿صَفًّا﴾؟","answer":"يصورهم مجتمعين منتظمين لا يحجب بعضهم بعضًا، كالجند المعروضين على السلطان. فتبرز هيئة العرض شمول الحضور وهيبة الموقف، وأن أحدًا لا يفلت من الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص98، تحت «سر التقييد بالحال صفًّا»","url":""}]},{"id":"s18-99","number":99,"surah":18,"verses":[48],"references":[{"surah":18,"verses":[48]}],"verseLabel":"الكهف: 48","question":"ما بلاغة التعبير بقوله يوم القيامة ﴿لَقَدْ جِئْتُمُونَا﴾؟","answer":"يصوّر حضور الخلق للحساب مجيئًا لا مهرب منه، وفيه تبكيت لمن أنكر هذا الموقف.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص99، تحت «بلاغة الاستعارة في لفظ لقد جئتمونا»","url":""}]},{"id":"s18-227","number":227,"surah":18,"verses":[48],"references":[{"surah":18,"verses":[48]}],"verseLabel":"الكهف: 48","question":"ما دلالة قوله ﴿كَمَا خَلَقْنَاكُمْ أَوَّلَ مَرَّةٍ﴾؟","answer":"يشبه إعادتهم ببدء خلقهم تقريرًا لقدرة الله على البعث، ويذكر أنهم يأتون مجردين مما تفاخروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص100، تحت «الغرض من التشبيه في كما خلقناكم أول مرة»","url":""}]},{"id":"s18-100","number":100,"surah":18,"verses":[49],"references":[{"surah":18,"verses":[49]}],"verseLabel":"الكهف: 49","question":"ما سرّ التعبير بـ﴿وَوُضِعَ الْكِتَابُ﴾ لا «ووضعنا الكتاب»؟","answer":"البناء للمجهول يوجه الأنظار إلى رهبة السجل الموضوع نفسه وما يكشفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص106، تحت «دلالة بناء الفعل للمفعول»","url":""}]},{"id":"s18-101","number":101,"surah":18,"verses":[49],"references":[{"surah":18,"verses":[49]}],"verseLabel":"الكهف: 49","question":"ما سرّ التعبير بقوله تعالى: ﴿يَا وَيْلَتَنَا﴾ بصيغة التأنيث؟","answer":"صيغة «الويلة» تبالغ في وصف الهلاك وشدته، وليست تأنيثًا لشخص. ونداؤها يصور غاية الندم والفزع حتى كأنهم يدعون الهلاك ليحضر حين رأوا أعمالهم محصاة في الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص110، تحت «سر التعبير عن الويل بصيغة التأنيث»","url":""}]},{"id":"s18-102","number":102,"surah":18,"verses":[49],"references":[{"surah":18,"verses":[49]}],"verseLabel":"الكهف: 49","question":"ما دلالة قولهم: ﴿لَا يُغَادِرُ صَغِيرَةً وَلَا كَبِيرَةً﴾؟","answer":"تنكير الصغيرة والكبيرة مع النفي يفيد شمول الإحصاء لكل عمل. وتقديم الصغيرة يبرز دقة الكتاب؛ فإذا لم تفته الصغائر فالكبائر أولى، ثم ذُكرت صراحة لتأكيد الشمول وزيادة التهويل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص112، تحت «نكتة تقديم الصغيرة على الكبيرة»","url":""}]},{"id":"s18-103","number":103,"surah":18,"verses":[50],"references":[{"surah":18,"verses":[50]}],"verseLabel":"الكهف: 50","question":"ما دلالة إيراد قصة سجود الملائكة وإباء إبليس في هذا الموضع من سورة الكهف؟","answer":"تذكر القصة بأصل عداوة الشيطان واستكباره، بعد مشاهد الحشر والحساب، فتدعو إلى الحذر من اتباعه. وتناسب أيضًا ذم الافتخار بالمال واحتقار المؤمنين؛ إذ تعرض نموذج الاستكبار الذي أورث العصيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص118، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s18-104","number":104,"surah":18,"verses":[50],"references":[{"surah":18,"verses":[50]}],"verseLabel":"الكهف: 50","question":"ما دلالة ﴿عَنْ﴾ في قوله عن إبليس ﴿فَفَسَقَ عَنْ أَمْرِ رَبِّهِ﴾؟","answer":"تصور خروجه ومجاوزته دائرة أمر الله بالطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص123، تحت «دلالة حرف المجاوزة عن»","url":""}]},{"id":"s18-228","number":228,"surah":18,"verses":[50],"references":[{"surah":18,"verses":[50]}],"verseLabel":"الكهف: 50","question":"ما سرّ إضافة الأمر إلى الرب في قوله ﴿عَنْ أَمْرِ رَبِّهِ﴾؟","answer":"تشنّع عصيان إبليس؛ إذ خرج عن أمر من رباه وأنعم عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص124، تحت «سر الإضافة أمر ربه»","url":""}]},{"id":"s18-105","number":105,"surah":18,"verses":[50],"references":[{"surah":18,"verses":[50]}],"verseLabel":"الكهف: 50","question":"ما سرّ التعبير بـ﴿أَفَتَتَّخِذُونَهُ وَذُرِّيَّتَهُ أَوْلِيَاءَ﴾؟","answer":"الاستفهام يعجب من موالاة عدو أعلن عداوته منذ خلق أبيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص125، تحت «الغرض من أسلوب الاستفهام في أفتتخذونه»","url":""}]},{"id":"s18-106","number":106,"surah":18,"verses":[50],"references":[{"surah":18,"verses":[50]}],"verseLabel":"الكهف: 50","question":"ما سر إظهار وصف ﴿لِلظَّالِمِينَ﴾ في قوله: ﴿بِئْسَ لِلظَّالِمِينَ بَدَلًا﴾؟","answer":"ليحكم عليهم بالظلم ويبين أن استبدال ولاية الشيطان بولاية الله هو عين وضع الشيء في غير موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص128، تحت «الغرض من التعبير بالإظهار دون الإضمار»","url":""}]},{"id":"s18-107","number":107,"surah":18,"verses":[51],"references":[{"surah":18,"verses":[51]}],"verseLabel":"الكهف: 51","question":"ما الغرض من نفي إشهاد إبليس وذريته خلق السماوات والأرض؟","answer":"ينفي ذلك أن يكونوا قد شاركوا في الخلق أو عاونوا عليه أو أُحضروا للمشورة فيه؛ فيسقط كل وجه لاتخاذهم أولياء من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص132، تحت «الغرض من نفي الإشهاد في خلق السماوات»","url":""}]},{"id":"s18-229","number":229,"surah":18,"verses":[51],"references":[{"surah":18,"verses":[51]}],"verseLabel":"الكهف: 51","question":"ما دلالة التعبير بـ﴿خَلْقَ السَّمَاوَاتِ وَالْأَرْضِ﴾ في نفي استحقاق الشركاء للولاية؟","answer":"يستدل بخلق السماوات والأرض على أن الله هو الخالق المستقل لكل شيء، ومنه خلق الشركاء أنفسهم؛ فمن انفرد بالخلق هو المستحق للعبادة والولاية دونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص132، تحت «دلالة التعبير بـ﴿خَلْقَ السَّمَاوَاتِ وَالْأَرْضِ﴾»","url":""}]},{"id":"s18-108","number":108,"surah":18,"verses":[51],"references":[{"surah":18,"verses":[51]}],"verseLabel":"الكهف: 51","question":"ما سرّ التعبير بـ﴿وَمَا كُنْتُ مُتَّخِذَ الْمُضِلِّينَ عَضُدًا﴾؟","answer":"استعير العضد للمعين، لأنه مما يقوم به الإسناد والقوة، فنفى الله اتخاذ المضلين أعوانًا. وإظهار وصف «المضلين» يذمهم وينبه إلى فساد اتخاذهم أولياء، مع غنى الله عن المعين أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص135، تحت «بلاغة الاستعارة بالتعبير بالعضد»","url":""}]},{"id":"s18-109","number":109,"surah":18,"verses":[52],"references":[{"surah":18,"verses":[52]}],"verseLabel":"الكهف: 52","question":"ما دلالة الأمر في قوله للمشركين ﴿نَادُوا شُرَكَائِيَ﴾؟","answer":"أمر تعجيز وتوبيخ؛ ليظهر عمليًا أن من عبدوهم لا يستجيبون لهم ولا ينصرونهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص138، تحت «دلالة التعبير بفعل الأمر نادوا»","url":""}]},{"id":"s18-230","number":230,"surah":18,"verses":[52],"references":[{"surah":18,"verses":[52]}],"verseLabel":"الكهف: 52","question":"ما سرّ إضافة الشركاء إلى ضمير الجلالة في قوله ﴿شُرَكَائِيَ﴾؟","answer":"الإضافة تهكم بدعواهم؛ فليس لله شريك، وإنما هم شركاء زعموهم من عند أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص139، تحت «سر إضافة الشركاء إلى ضمير الجلالة»","url":""}]},{"id":"s18-110","number":110,"surah":18,"verses":[52],"references":[{"surah":18,"verses":[52]}],"verseLabel":"الكهف: 52","question":"ما دلالة قوله: ﴿وَجَعَلْنَا بَيْنَهُمْ مَوْبِقًا﴾؟","answer":"الموبق موضع الهلاك، ومن توجيهاته جهنم التي تفصل بينهم وبين من دعوهم. فبدل أن تنفعهم الصلة المزعومة بالشركاء، يواجهون الهلاك وتنقطع الاستجابة التي رجَوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص142، تحت «دلالة التعبير بصيغة موبقًا»","url":""}]},{"id":"s18-111","number":111,"surah":18,"verses":[53],"references":[{"surah":18,"verses":[53]}],"verseLabel":"الكهف: 53","question":"لماذا قال عن المجرمين عند رؤية النار: ﴿فظنوا أنهم مواقعوها﴾؟","answer":"عبّر بالظن لأنهم لم يباشروا دخولها بعد، مع أن أمارات الوقوع جعلت توقعهم قريبًا من اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص146، تحت «سر إيثار لفظ الظن دون العلم أو اليقين»","url":""}]},{"id":"s18-231","number":231,"surah":18,"verses":[53],"references":[{"surah":18,"verses":[53]}],"verseLabel":"الكهف: 53","question":"ما دلالة وصف المجرمين بأنهم ﴿مواقعوها﴾؟","answer":"يصوّر اللفظ تلاقيهم بالنار ووقوع بعضهم على بعض فيها، فيوحي بالمباشرة التي لا مهرب منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص146، تحت «إيثار لفظ المواقعة»","url":""}]},{"id":"s18-112","number":112,"surah":18,"verses":[53],"references":[{"surah":18,"verses":[53]}],"verseLabel":"الكهف: 53","question":"ما سرّ التعبير بـ﴿وَلَمْ يَجِدُوا عَنْهَا مَصْرِفًا﴾؟","answer":"«مصرفًا» اسم مكان في هذا التوجيه؛ أي لم يجدوا موضعًا ينصرفون إليه عن النار. ونفي وجدانه يصور انقطاع طريق النجاة وعجزهم عن الهرب منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص147، تحت «سر التعبير بالمفعول به بصيغة مفعل»","url":""}]},{"id":"s18-113","number":113,"surah":18,"verses":[54],"references":[{"surah":18,"verses":[54]}],"verseLabel":"الكهف: 54","question":"ما دلالة وصف الإنسان بأنه ﴿أَكْثَرَ شَيْءٍ جَدَلًا﴾؟","answer":"بالغ في رسوخ الجدل فيه؛ فهو يحول تنوع الأمثال إلى خصومة بدل الهداية إن فسد قصده.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص165، تحت «دلالة الجدل في الآية الكريمة»","url":""}]},{"id":"s18-114","number":114,"surah":18,"verses":[55],"references":[{"surah":18,"verses":[55]}],"verseLabel":"الكهف: 55","question":"ما سرّ التعبير بـ﴿وَمَا مَنَعَ النَّاسَ أَنْ يُؤْمِنُوا﴾؟","answer":"«ما» هنا نافية، وليست استفهامية. والنفي مع الاستثناء يصور عنادهم بعد قيام الهدى؛ فكأنهم لا ينتظرون إلا حلول عذاب الأولين أو مواجهة العذاب، وفي هذا تعجيب من حالهم وتهديد لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص170، تحت «إيثار لفظ منع دون غيره من مرادفاته»","url":""}]},{"id":"s18-115","number":115,"surah":18,"verses":[55],"references":[{"surah":18,"verses":[55]}],"verseLabel":"الكهف: 55","question":"ما سرّ التعبير بـ﴿إِلَّا أَنْ تَأْتِيَهُمْ سُنَّةُ الْأَوَّلِينَ﴾؟","answer":"جعل إصرارهم كأنهم لا ينتظرون إلا نموذج الهلاك القديم أو العذاب عيانًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص182، تحت «بلاغة الكناية في سنة الأولين»","url":""}]},{"id":"s18-116","number":116,"surah":18,"verses":[56],"references":[{"surah":18,"verses":[56]}],"verseLabel":"الكهف: 56","question":"ما مناسبة قصر وظيفة المرسلين على التبشير والإنذار قبل ذكر جدال الكافرين بالباطل في سورة الكهف؟","answer":"جاء القصر ليحدد وظيفة الرسل في البلاغ الجامع بين الرجاء والخوف، ثم يكشف أن مجادلة الكافرين بالباطل خروج عن مقتضى الرسالة وطلب متعنت لما ليس من وظيفة الرسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص191، تحت «براعة القصر في سياق الآية الكريمة»","url":""}]},{"id":"s18-117","number":117,"surah":18,"verses":[56],"references":[{"surah":18,"verses":[56]}],"verseLabel":"الكهف: 56","question":"ما سرّ التعبير بـ﴿وَيُجَادِلُ الَّذِينَ كَفَرُوا بِالْبَاطِلِ﴾؟","answer":"المضارع يصور خصومة تتجدد كلما جاءهم بيان، والباطل آلة لمحاولة إسقاط الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص198، تحت «فائدة التقييد بقوله بالباطل»","url":""}]},{"id":"s18-118","number":118,"surah":18,"verses":[56],"references":[{"surah":18,"verses":[56]}],"verseLabel":"الكهف: 56","question":"ما سرّ التعبير بـ﴿لِيُدْحِضُوا بِهِ الْحَقَّ﴾؟","answer":"الإدحاض إزلاق القدم؛ استعارة لمحاولة إزالة ثبات الحق بحجة زائفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص199، تحت «بلاغة الاستعارة في قوله ليدحضوا»","url":""}]},{"id":"s18-119","number":119,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"ما سرّ التعبير بـ﴿ذُكِّرَ بِآيَاتِ رَبِّهِ﴾ بالبناء للمجهول؟","answer":"لأن المعتبر وصول التذكير إليه أيًا كان مبلغه، فلا عذر بعد قيام الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص214، تحت «سبب مجيء ذكر مبنيًّا للمفعول»","url":""}]},{"id":"s18-120","number":120,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"ما سرّ التعبير بـ﴿بِآيَاتِ رَبِّهِ﴾ لا «بالقرآن»؟","answer":"المراد في هذا التوجيه القرآن، وتسميته «آيات» تستحضر وضوح دلائله وتعددها، فيكون الإعراض عنها أشد قبحًا. وإضافتها إلى الرب تذكّر بإحسانه وتزيد التعجيب ممن يعرض عما بلغه من ربه المنعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص214، تحت «دلالة التعبير بآيات ربه دون بالقرآن»","url":""}]},{"id":"s18-121","number":121,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"ما دلالة قوله عن المعرض: ﴿ونسي﴾؟","answer":"كُنّي بالنسيان عن الإهمال والإعراض، ثم صُوّر تركه لذنوبه كأنها شيء غاب عن ذاكرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص218، تحت «بلاغة النسيان هنا في الكناية ثم الاستعارة»","url":""}]},{"id":"s18-232","number":232,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"لماذا نُسب ما عمله الإنسان إلى يديه في قوله: ﴿ما قدمت يداه﴾؟","answer":"نُسب العمل إلى اليدين لأن أكثر الأفعال تباشر بهما، فدل الجزء على عمل الإنسان كله ومسؤوليته عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص218، تحت «بلاغة المجاز المرسل في قدمت يداه»","url":""}]},{"id":"s18-123","number":123,"surah":18,"verses":[57],"references":[{"surah":18,"verses":[57]}],"verseLabel":"الكهف: 57","question":"ما سرّ التعبير بـ﴿وَإِنْ تَدْعُهُمْ إِلَى الْهُدَى فَلَنْ يَهْتَدُوا﴾؟","answer":"يصور الشرط دعوة من استحكم إعراضهم، ويؤكد نفي الاهتداء حالَ طبع قلوبهم وتوليهم. وفيه تسلية للنبي عن هؤلاء المعاندين، مع بقاء الدعوة إلى الهدى؛ فلا يحمل على منع دعوة الناس أو نفي إمكان هداية كل عاصٍ.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص228، تحت «نكتة مجيء الجزاء بصيغة فلن يهتدوا»","url":""}]},{"id":"s18-124","number":124,"surah":18,"verses":[58],"references":[{"surah":18,"verses":[58]}],"verseLabel":"الكهف: 58","question":"ما سرّ التعبير بـ﴿وَرَبُّكَ الْغَفُورُ ذُو الرَّحْمَةِ﴾ لا «الرحيم»؟","answer":"يمهد وصفه بأنه «ذو الرحمة» لبيان إمهالهم وترك تعجيل العذاب. ومن توجيهات العدول عن صيغة المبالغة أن المقام يذكر الرحمة بهذا الإمهال خاصة، بينما أبرز «الغفور» سعة المغفرة لمن آمن وتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص235، تحت «سر العدول عن الرحيم إلى ذو الرحمة»","url":""}]},{"id":"s18-125","number":125,"surah":18,"verses":[58],"references":[{"surah":18,"verses":[58]}],"verseLabel":"الكهف: 58","question":"ما سرّ التعبير بـ﴿بِمَا كَسَبُوا﴾؟","answer":"الباء تربط المؤاخذة بما اقترفوه، و«ما» تشمل ما كسبوا من الذنوب. وفي تصوير المعاصي كسبًا تهكم بهم؛ فقد حسبوا أنهم يجلبون لأنفسهم نفعًا، فإذا عاقبة فعلهم شر وضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص238، تحت «بلاغة الاستعارة في قوله كسبوا»","url":""}]},{"id":"s18-126","number":126,"surah":18,"verses":[58],"references":[{"surah":18,"verses":[58]}],"verseLabel":"الكهف: 58","question":"ما سرّ تقديم ﴿لَهُمْ﴾ في ﴿بَلْ لَهُمْ مَوْعِدٌ﴾؟","answer":"لتخصيصهم وتهديدهم بأن موعدًا معينًا يترصدهم لا يفلتون منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص241، تحت «سر التقديم في قوله لهم موعد»","url":""}]},{"id":"s18-127","number":127,"surah":18,"verses":[59],"references":[{"surah":18,"verses":[59]}],"verseLabel":"الكهف: 59","question":"ما سرّ التعبير بـ﴿وَتِلْكَ الْقُرَى أَهْلَكْنَاهُمْ﴾ فجمع القرى وأعاد الضمير إلى أهلها؟","answer":"أشار إلى آثار قرى متعددة، ثم راعى سكانها في ضمير العقلاء لأنهم محل الظلم والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص251، تحت «نكتة عود الضمير مجموعًا في أهلكناهم»","url":""}]},{"id":"s18-128","number":128,"surah":18,"verses":[59],"references":[{"surah":18,"verses":[59]}],"verseLabel":"الكهف: 59","question":"ما سرّ التعبير بـ﴿وَجَعَلْنَا لِمَهْلِكِهِمْ مَوْعِدًا﴾؟","answer":"يبين أن لإهلاكهم وقتًا مقدرًا لا يتقدمون عليه ولا يتأخرون عنه؛ فالإمهال ليس إلغاءً للجزاء. وتقديم «لمهلكهم» يوجه الاهتمام إلى هذا المصير ويزيد التخويف منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص253، تحت «دلالة صيغة مهلك»","url":""}]},{"id":"s18-129","number":129,"surah":18,"verses":[60],"references":[{"surah":18,"verses":[60]}],"verseLabel":"الكهف: 60","question":"ما دلالة قول موسى: ﴿لَا أَبْرَحُ حَتَّى أَبْلُغَ﴾؟","answer":"عبّر عن استمرار السير بلا فتور حتى الغاية، فصار طلب العلم عزمًا مفتوح المدى.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص262، تحت «دلالة النفي بلا في السياق الحكيم»","url":""}]},{"id":"s18-130","number":130,"surah":18,"verses":[60],"references":[{"surah":18,"verses":[60]}],"verseLabel":"الكهف: 60","question":"ما سرّ التعبير بـ﴿مَجْمَعَ الْبَحْرَيْنِ﴾ لا «ملتقى البحرين»؟","answer":"يفيد «المجمع» الاجتماع وما يصاحبه من كثرة وتجانس، بينما أصل اللقاء مقابلة الشيء، وقد يقع مصادفة. فالتعبير يحدد الموضع المقصود ويصور اجتماع البحرين، ويهيئ في السياق للقاء موسى بمن يطلب علمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص263، تحت «سبب إيثار لفظ مجمع دون ملتقى»","url":""}]},{"id":"s18-131","number":131,"surah":18,"verses":[60],"references":[{"surah":18,"verses":[60]}],"verseLabel":"الكهف: 60","question":"ما سرّ التعبير بـ﴿أَوْ أَمْضِيَ حُقُبًا﴾؟","answer":"يبالغ في طول الاستعداد للسفر؛ فالحقب زمن طويل، والعلم يستحق الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص265، تحت «بلاغة الكناية في أو أمضي حقبًا»","url":""}]},{"id":"s18-132","number":132,"surah":18,"verses":[61],"references":[{"surah":18,"verses":[61]}],"verseLabel":"الكهف: 61","question":"ما سرّ التعبير بـ﴿فَلَمَّا بَلَغَا مَجْمَعَ بَيْنِهِمَا﴾؟","answer":"تربط «لما» بلوغهما مجمع البحرين بما وقع عنده من نسيان الحوت، بعد سيرهما نحو الموعد. وإظهار ﴿مَجْمَعَ بَيْنِهِمَا﴾ يعيد إبراز أهمية المكان الذي قصداه للقاء العبد الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص270، تحت «بلاغة مجيء الكلام على خلاف الظاهر في الآية»","url":""}]},{"id":"s18-133","number":133,"surah":18,"verses":[61],"references":[{"surah":18,"verses":[61]}],"verseLabel":"الكهف: 61","question":"ما دلالة وصف مسلك الحوت بقوله: ﴿فَاتَّخَذَ سَبِيلَهُ فِي الْبَحْرِ سَرَبًا﴾؟","answer":"شُبّه الطريق الذي اتخذه الحوت في الماء بالسرب، وهو النفق، فصار مسلكه ظاهرًا على هيئة عجيبة. وهذا المشهد الخارق للعادة كان علامة لموسى على موضع اللقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص274، تحت «بلاغة التشبيه في قوله سربًا»","url":""}]},{"id":"s18-134","number":134,"surah":18,"verses":[62],"references":[{"surah":18,"verses":[62]}],"verseLabel":"الكهف: 62","question":"ما دلالة ظهور النصب في رحلة موسى بعد مجاوزة موضع اللقاء؟","answer":"صرف الله عنه التعب حتى تجاوز المكان، ثم جعله سببًا للرجوع إلى العلامة التي نسيها فتاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص284، تحت «دلالة جملة التعبير عن النصب وما فيها من بيان عجب»","url":""}]},{"id":"s18-135","number":135,"surah":18,"verses":[62],"references":[{"surah":18,"verses":[62]}],"verseLabel":"الكهف: 62","question":"ما سرّ التعبير بـ﴿آتِنَا غَدَاءَنَا﴾ بالإيتاء لا الإعطاء؟","answer":"الإيتاء هنا أنسب بطلب إحضار الغداء ومناولته، لا بإنشاء ملك له؛ فهو طعامهما أصلًا. ويذكر المصدر أن الإيتاء أقوى في معنى الإحضار، وأن الأمر به مناسب لمقام موسى مع فتاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص282، تحت «سر التعبير بلفظ آتنا عوضًا عن لفظ أعطنا»","url":""}]},{"id":"s18-136","number":136,"surah":18,"verses":[63],"references":[{"surah":18,"verses":[63]}],"verseLabel":"الكهف: 63","question":"ما دلالة افتتاح الفتى كلامه بـ﴿أَرَأَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ﴾؟","answer":"يستدعي الفتى انتباه موسى إلى ما حدث عند الصخرة، وفي الاستفهام تعجيب من النسيان مع عظم الأمر المشاهد. ويحتمل معنى «أخبرني» أو «انتبه» تمهيدًا لذكر خبر الحوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص287، تحت «دلالة الاستفهام في قوله تعالى أرأيت»","url":""}]},{"id":"s18-137","number":137,"surah":18,"verses":[63],"references":[{"surah":18,"verses":[63]}],"verseLabel":"الكهف: 63","question":"ما سر إضافة الإيواء إلى الصخرة في كلام الفتى؟","answer":"الصخرة معروفة لهما، وإضافة الإيواء إليها تعيّن موضع الحادثة بدقة وتستحضر وقت الاستراحة. وفي ذلك تأكيد لاعتذار الفتى؛ فهذا هو المكان الذي وقع فيه الأمر العجيب ثم نسي إخبار موسى به.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص290، تحت «علة إضافة الإيواء إلى الصخرة دون مجمع البحرين»","url":""}]},{"id":"s18-138","number":138,"surah":18,"verses":[63],"references":[{"surah":18,"verses":[63]}],"verseLabel":"الكهف: 63","question":"ما دلالة إسناد النسيان إلى الحوت في قول الفتى: ﴿فَإِنِّي نَسِيتُ الْحُوتَ﴾؟","answer":"من توجيهات العبارة أنه نسي ذكر خبر الحوت لموسى، فحُذف المضاف وأقيم الحوت مقامه. ويذكر المصدر أيضًا نسيان حفظه وتفقده؛ فلا يلزم حصر النسيان في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص291، تحت «دلالة النسيان في قوله فإني نسيت»","url":""}]},{"id":"s18-139","number":139,"surah":18,"verses":[63],"references":[{"surah":18,"verses":[63]}],"verseLabel":"الكهف: 63","question":"ما سرّ التعبير بـ﴿وَمَا أَنْسَانِيهُ إِلَّا الشَّيْطَانُ﴾؟","answer":"قصر سبب النسيان العارض على وسوسة الشيطان، مع بقاء الحدث داخل تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص293، تحت «سر نسبة فعل النسيان إلى الشيطان لا إلى الإنسان»","url":""}]},{"id":"s18-140","number":140,"surah":18,"verses":[63],"references":[{"surah":18,"verses":[63]}],"verseLabel":"الكهف: 63","question":"لماذا عطف ﴿وَاتَّخَذَ سَبِيلَهُ﴾ بالواو، وفي الآية 61 بالفاء؟","answer":"الفاء في الآية 61 تصل اتخاذ الحوت سبيله بما سبق في سرد الحدث وتفيد التعقيب. أما الواو في كلام الفتى فتعرض حال الحوت التي نسي ذكرها؛ فالسياق يستحضر ما وقع عجبًا، ولا يرتب ذهابه على نسيان إخباره موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص295، تحت «علة التعبير بالواو العاطفة في جملة واتخذ»","url":""}]},{"id":"s18-141","number":141,"surah":18,"verses":[64],"references":[{"surah":18,"verses":[64]}],"verseLabel":"الكهف: 64","question":"ما دلالة قول موسى: ﴿ذَلِكَ مَا كُنَّا نَبْغِ﴾؟","answer":"أدرك أن فقد الحوت هو العلامة المطلوبة؛ فاسم الإشارة يحسم أن هذا عين المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص302، تحت «سر الإشارة بما يدل على البعد بلفظ ذلك»","url":""}]},{"id":"s18-142","number":142,"surah":18,"verses":[64],"references":[{"surah":18,"verses":[64]}],"verseLabel":"الكهف: 64","question":"ما سرّ التعبير بـ﴿فَارْتَدَّا عَلَى آثَارِهِمَا قَصَصًا﴾ لا «فرجعا»؟","answer":"الارتداد رجوع على الطريق نفسه، و«قصصًا» يصور تتبع الأثر بدقة حتى لا يضيعا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص306، تحت «سر التعبير بلفظ قصصًا في ثنايا السياق»","url":""}]},{"id":"s18-143","number":143,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما سر تقديم الخضر بوصفه ﴿عَبْدًا﴾؟","answer":"العبودية لله أرفع أوصاف التكريم؛ فافتتاح التعريف بالخضر بها يرفع قدره ويهيئ لبيان ما خصه الله به من الرحمة والعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص313، تحت «سر التعبير بلفظ ﴿عَبْدًا﴾ دون مرادفاته»","url":""}]},{"id":"s18-233","number":233,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما دلالة تنكير لفظ ﴿عَبْدًا﴾ في التعريف بالخضر؟","answer":"جاء التنكير للتفخيم والتعظيم، فيدل على عبد رفيع المنزلة اصطفاه الله، وإن لم يُذكر اسمه في الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص313، تحت «سر التنكير في لفظ ﴿عَبْدًا﴾ في السياق»","url":""}]},{"id":"s18-234","number":234,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما سر إضافة العبد إلى ضمير العظمة في قوله: ﴿عَبْدًا مِنْ عِبَادِنَا﴾؟","answer":"الإضافة إلى الله إضافة تشريف وتكريم، وتدل على خصوصية هذا العبد بالقرب والاصطفاء، مع بقائه واحدًا من عباد الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص314، تحت «سر الإضافة في المركب الإضافي ﴿عِبَادِنَا﴾»","url":""}]},{"id":"s18-144","number":144,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما سر قوله: ﴿رحمة من عندنا﴾ و﴿من لدنا علمًا﴾؟","answer":"خص العلم بـ﴿لدنا﴾ للدلالة على مزيد اختصاصه بالله ومباشرة تعليمه، وجاءت الرحمة بـ﴿عندنا﴾ الدالة على الفضل الممنوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص318، تحت «سر عند مع الرحمة ولدن مع العلم في الآية»","url":""}]},{"id":"s18-235","number":235,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما دلالة تنكير ﴿علمًا﴾ في وصف الخضر؟","answer":"يفيد تفخيم علم خاص وهبه الله له، متعلق بحِكَم خفية لم يطلع عليها موسى في بداية الصحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص319، تحت «المراد بالعلم وغرض تنكيره»","url":""}]},{"id":"s18-236","number":236,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"لماذا قُدمت الرحمة على العلم في وصف الخضر؟","answer":"لأن الرحمة أصل في حسن استعمال العلم؛ فالعلم الذي لا تحكمه الرحمة قد يتحول إلى أذى أو غرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص320، تحت «سر تقديم الرحمة على العلم»","url":""}]},{"id":"s18-145","number":145,"surah":18,"verses":[65],"references":[{"surah":18,"verses":[65]}],"verseLabel":"الكهف: 65","question":"ما سرّ تقديم ﴿مِنْ لَدُنَّا﴾ على ﴿عِلْمًا﴾؟","answer":"لقصر مصدر هذا العلم الخاص على تعليم الله، لا على كسب معتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص318، 319، تحت «سر تقديم الجار والمجرور من لدنا على المفعول به علمًا»","url":""}]},{"id":"s18-146","number":146,"surah":18,"verses":[66],"references":[{"surah":18,"verses":[66]}],"verseLabel":"الكهف: 66","question":"ما دلالة استئذان موسى بقوله: ﴿هَلْ أَتَّبِعُكَ﴾ وهو نبي؟","answer":"تواضع المتعلم لمن عنده علم لا يعلمه، واستأذن في الصحبة بدل أن يطالب بالتعليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص325، تحت «نكتة تقديم إثبات الاتباع على طلب التعليم»","url":""}]},{"id":"s18-147","number":147,"surah":18,"verses":[66],"references":[{"surah":18,"verses":[66]}],"verseLabel":"الكهف: 66","question":"ما سرّ التعبير بـ﴿مِمَّا عُلِّمْتَ رُشْدًا﴾ لا «علمًا»؟","answer":"طلب من العلم ما يقود إلى الصواب والعمل، لا معلومات مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص328، تحت «سر التعبير والتنكير للفظ رشدًا»","url":""}]},{"id":"s18-148","number":148,"surah":18,"verses":[67],"references":[{"surah":18,"verses":[67]}],"verseLabel":"الكهف: 67","question":"ما دلالة قول الخضر لموسى: ﴿لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا﴾؟","answer":"لم يطعن في موسى، بل أخبر أن ظاهر الأفعال سيصادم علم الشريعة الذي يحمله قبل كشف بواطنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص337، تحت «المراد بالصبر وسر التعبير به»","url":""}]},{"id":"s18-149","number":149,"surah":18,"verses":[68],"references":[{"surah":18,"verses":[68]}],"verseLabel":"الكهف: 68","question":"ما سرّ التعبير بـ﴿وَكَيْفَ تَصْبِرُ عَلَى مَا لَمْ تُحِطْ بِهِ خُبْرًا﴾؟","answer":"الاستفهام للتعجيب أو الإنكار، وفيه بيان سبب تعذر صبر موسى على أفعال تبدو منكرة قبل أن يعلم حكمتها. و«تحط» تصور العلم المستوعب لبواطنها وعواقبها، وهي أمور لم يُطلع عليها بعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص340، تحت «بلاغة استعمال لفظ الإحاطة»","url":""}]},{"id":"s18-150","number":150,"surah":18,"verses":[68],"references":[{"surah":18,"verses":[68]}],"verseLabel":"الكهف: 68","question":"ما سرّ التعبير بـ﴿خُبْرًا﴾ لا «علمًا»؟","answer":"الخبر معرفة باطن الشيء وتجربته، وهو المطلوب لفهم الأفعال الغريبة لا مجرد علم إجمالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص342، تحت «معنى لفظ خبرًا وسر تنكيره»","url":""}]},{"id":"s18-151","number":151,"surah":18,"verses":[69],"references":[{"surah":18,"verses":[69]}],"verseLabel":"الكهف: 69","question":"ما دلالة قول موسى: ﴿سَتَجِدُنِي إِنْ شَاءَ اللَّهُ صَابِرًا﴾؟","answer":"ربط وعده بالمشيئة تأدبًا، واختار اسم الفاعل ليدل على ثبات الصبر المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص349، تحت «دلالة الاستثناء في قوله إن شاء الله»","url":""}]},{"id":"s18-152","number":152,"surah":18,"verses":[69],"references":[{"surah":18,"verses":[69]}],"verseLabel":"الكهف: 69","question":"ما سرّ التعبير بـ﴿وَلَا أَعْصِي لَكَ أَمْرًا﴾ ولم يقل «لن أعصي»؟","answer":"من توجيهات اختيار «لا» أنها لا تحمل تأكيد النفي الذي تفيده «لن» في هذا السياق، فيناسب ذلك وعد موسى المعلق بمشيئة الله. ومع تنكير «أمرًا» يعلن استعداده لاتباع أوامر الخضر في هذه الصحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص352، تحت «سر النفي بلا دون لن»","url":""}]},{"id":"s18-153","number":153,"surah":18,"verses":[70],"references":[{"surah":18,"verses":[70]}],"verseLabel":"الكهف: 70","question":"ما دلالة تقييد النهي عن السؤال بـ﴿حَتَّى أُحْدِثَ لَكَ مِنْهُ ذِكْرًا﴾؟","answer":"اشترط تأخير السؤال والاعتراض حتى يبدأ هو ببيان وجه ما يفعله وحكمته. و«حتى» تجعل للسكوت غاية؛ فالمراد الصبر إلى وقت البيان في هذه الرحلة، مع وعده بأن يكشف لموسى ما خفي عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص359، تحت «غرض النهي في قوله فلا تسألني»","url":""}]},{"id":"s18-154","number":154,"surah":18,"verses":[71],"references":[{"surah":18,"verses":[71]}],"verseLabel":"الكهف: 71","question":"ما سرّ التعبير بـ﴿خَرَقَهَا﴾ فور ركوب السفينة؟","answer":"بادر الخضر إلى الخرق عند الركوب؛ وتقديم ظرف الركوب يدل على أن الخرق وقع بمجرده، وأن الفعل كان مقصودًا مدبرًا من قبل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص369، تحت «حقيقة الخرق وسر التعبير بالفعل خرقها»","url":""}]},{"id":"s18-155","number":155,"surah":18,"verses":[71],"references":[{"surah":18,"verses":[71]}],"verseLabel":"الكهف: 71","question":"ما دلالة إنكار موسى بقوله: ﴿لَقَدْ جِئْتَ شَيْئًا إِمْرًا﴾؟","answer":"الإِمر هو الأمر العظيم المنكر؛ فأكد موسى إنكاره لما ظهر له من كون الخرق ذريعة إلى إغراق أهل السفينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص374، تحت «معنى إمرًا وسر التعبير بها»","url":""}]},{"id":"s18-156","number":156,"surah":18,"verses":[72],"references":[{"surah":18,"verses":[72]}],"verseLabel":"الكهف: 72","question":"ما دلالة تذكير الخضر موسى بقوله: ﴿أَلَمْ أَقُلْ إِنَّكَ لَنْ تَسْتَطِيعَ مَعِيَ صَبْرًا﴾؟","answer":"ليعيده إلى الشرط الذي قبله وهو يرى تحقق الخبر عمليًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص379، تحت «دلالة الاستفهام في قوله ألم أقل»","url":""}]},{"id":"s18-157","number":157,"surah":18,"verses":[73],"references":[{"surah":18,"verses":[73]}],"verseLabel":"الكهف: 73","question":"ما دلالة اعتذار موسى بقوله: ﴿لَا تُؤَاخِذْنِي بِمَا نَسِيتُ﴾؟","answer":"اعتذر موسى بأن اعتراضه الأول صدر عن نسيان شرط الصحبة، وسأل الصفح عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص385، تحت «نكتة إيثار التعبير بالمؤاخذة»","url":""}]},{"id":"s18-158","number":158,"surah":18,"verses":[73],"references":[{"surah":18,"verses":[73]}],"verseLabel":"الكهف: 73","question":"ما سرّ التعبير بـ﴿وَلَا تُرْهِقْنِي مِنْ أَمْرِي عُسْرًا﴾؟","answer":"طلب ألا يعامله الخضر بالشدة بسبب نسيانه، وأن يغضي ويصفح ليستمر أمر الصحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص387، تحت «بلاغة استعمال الفعل ترهقني مادة وصيغة»","url":""}]},{"id":"s18-159","number":159,"surah":18,"verses":[74],"references":[{"surah":18,"verses":[74]}],"verseLabel":"الكهف: 74","question":"ما دلالة شدة المبادرة والإنكار في مشهد قتل الغلام مقارنة بخرق السفينة؟","answer":"زادت الفاء في «فقتله» تصوير المبادرة بالقتل عقب اللقاء، على نحو أشد من مشهد خرق السفينة. واشتد إنكار موسى لأن قتل النفس وقع بالفعل، بينما خرق السفينة بدا له وسيلة إلى إغراق قد يقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص404، تحت «سر التعبير بقوله نكرًا»","url":""}]},{"id":"s18-160","number":160,"surah":18,"verses":[74],"references":[{"surah":18,"verses":[74]}],"verseLabel":"الكهف: 74","question":"ما دلالة قول موسى: ﴿نَفْسًا زَكِيَّةً بِغَيْرِ نَفْسٍ﴾؟","answer":"وصفها بالزكية يبرز ما ظهر لموسى من طهارتها وعدم استحقاقها القتل، و«بغير نفس» ينفي القصاص فيزيد الإنكار. ويذكر المصدر خلافًا في بلوغ الغلام؛ فلا يُجزم بصغر سنه على أنه التفسير الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص402، تحت «فائدة ذكر القيد بغير نفس»","url":""}]},{"id":"s18-161","number":161,"surah":18,"verses":[74],"references":[{"surah":18,"verses":[74]}],"verseLabel":"الكهف: 74","question":"ما سر وصف قتل الغلام بأنه ﴿شَيْئًا نُكْرًا﴾ ووصف خرق السفينة بأنه ﴿إِمْرًا﴾؟","answer":"النُّكر أشد من الإمر؛ لأن قتل الغلام فساد حاصل، أما خرق السفينة فكان في الظاهر ذريعة إلى فساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص376، تحت «الإمر والنكر والصعب»","url":""}]},{"id":"s18-162","number":162,"surah":18,"verses":[75],"references":[{"surah":18,"verses":[75]}],"verseLabel":"الكهف: 75","question":"ما دلالة زيادة ﴿لَكَ﴾ في التذكير الثاني: ﴿أَلَمْ أَقُلْ لَكَ﴾؟","answer":"زيادة ﴿لك﴾ تحقق وقوع القول وتثبته وتقويه؛ لأن موسى أهمل العمل بالتنبيه السابق، فصار التقرير والإنكار أشد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص410، تحت «دلالة اللام وسر زيادة شبه الجملة لك»","url":""}]},{"id":"s18-163","number":163,"surah":18,"verses":[76],"references":[{"surah":18,"verses":[76]}],"verseLabel":"الكهف: 76","question":"ما دلالة جعل موسى السؤال التالي سببًا لإنهاء الصحبة؟","answer":"أنصف موسى صاحبه، فجعل له العذر في قطع الصحبة إن عاد إلى السؤال ثالثة، تجنبًا لإحراجه بعد تكرر الاعتراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص415، تحت «بلاغة التعبير بالفعل بلغت»","url":""}]},{"id":"s18-164","number":164,"surah":18,"verses":[77],"references":[{"surah":18,"verses":[77]}],"verseLabel":"الكهف: 77","question":"ما دلالة ﴿اسْتَطْعَمَا أَهْلَهَا﴾ وما تبعها من رفض الضيافة؟","answer":"السين والتاء للطلب، أي طلبا الطعام من أهل القرية لما أصابهما من الجوع. ثم أبرز رفضهم الضيافة شدة لؤمهم، وإعادة «أهلها» تعيّن الجماعة التي وُجه إليها الطلب فامتنعت.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص426، تحت «دلالة السين في الفعل استطعما»","url":""}]},{"id":"s18-165","number":165,"surah":18,"verses":[77],"references":[{"surah":18,"verses":[77]}],"verseLabel":"الكهف: 77","question":"ما سرّ التعبير بـ﴿جِدَارًا يُرِيدُ أَنْ يَنْقَضَّ﴾؟","answer":"استعيرت الإرادة لقرب سقوط الجدار: فقد مال وأشرف على الانقضاض، فشُبّه قرب وقوعه بإرادة العاقل للفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص430، تحت «بلاغة السياق بين الاستعارة والمجاز العقلي»","url":""}]},{"id":"s18-166","number":166,"surah":18,"verses":[77],"references":[{"surah":18,"verses":[77]}],"verseLabel":"الكهف: 77","question":"ما دلالة إقامة الجدار بلا أجر في قرية امتنعت عن الضيافة؟","answer":"كانت إقامة الجدار لحفظ كنز اليتيمين حتى يبلغا ويقدرا على استخراجه وصيانته، رحمة بهما وإكرامًا لأبيهما الصالح. فسبب العمل يتجاوز ما ظهر من لؤم أهل القرية وحاجتهما إلى الطعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص466، تحت «سر الوصف باليتم هنا»","url":""}]},{"id":"s18-167","number":167,"surah":18,"verses":[78],"references":[{"surah":18,"verses":[78]}],"verseLabel":"الكهف: 78","question":"ما سرّ التعبير بـ﴿هَذَا فِرَاقُ بَيْنِي وَبَيْنِكَ﴾؟","answer":"يشير ﴿هذا﴾ إلى ما حصل الآن من تحقق الشرط الذي ألزمه موسى نفسه؛ فصار الاعتراض الثالث هو لحظة انقطاع الصحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص435، تحت «دلالة الفراق في هذا السياق»","url":""}]},{"id":"s18-168","number":168,"surah":18,"verses":[78],"references":[{"surah":18,"verses":[78]}],"verseLabel":"الكهف: 78","question":"ما سرّ التعبير بـ﴿سَأُنَبِّئُكَ بِتَأْوِيلِ مَا لَمْ تَسْتَطِعْ عَلَيْهِ صَبْرًا﴾؟","answer":"أوفى الخضر بوعده السابق، فأنبأ موسى عند الفراق بأسباب الأفعال التي أنكرها وبعواقبها الخفية.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص438، تحت «بلاغة استعمال لفظ تأويل»","url":""}]},{"id":"s18-169","number":169,"surah":18,"verses":[79],"references":[{"surah":18,"verses":[79]}],"verseLabel":"الكهف: 79","question":"لماذا نسب الخضر عيب السفينة إلى نفسه: ﴿فَأَرَدْتُ أَنْ أَعِيبَهَا﴾؟","answer":"نسب العيب إلى نفسه مراعاةً لحسن الأدب مع الله، مع إقراره أن الفعل كان بأمره. والتعبير بـ«أردت» يوضح أنه خرق مقصود لحفظ السفينة، لا إفساد عبثي لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص448، تحت «سر إسناد العبد الصالح العيب إلى نفسه»","url":""}]},{"id":"s18-170","number":170,"surah":18,"verses":[79],"references":[{"surah":18,"verses":[79]}],"verseLabel":"الكهف: 79","question":"لماذا وصف أصحاب السفينة بأنهم ﴿مساكين﴾ مع امتلاكهم سفينة؟","answer":"لأن ملكهم للسفينة لم يرفع حاجتهم؛ كانت أداة كسبهم الوحيدة ومعاشهم معرضًا للسلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص445، تحت «سر الوصف بقوله لمساكين»","url":""}]},{"id":"s18-237","number":237,"surah":18,"verses":[79],"references":[{"surah":18,"verses":[79]}],"verseLabel":"الكهف: 79","question":"لماذا ذُكر عيب السفينة قبل ذكر الملك الذي يغتصب السفن؟","answer":"قُدّم الفعل المستنكر أولًا ليبقى السامع متشوقًا إلى حكمته، ثم كشف السبب فتحول ظاهر الضرر إلى رحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص447، تحت «سر تقديم المسبب على السبب»","url":""}]},{"id":"s18-238","number":238,"surah":18,"verses":[79],"references":[{"surah":18,"verses":[79]}],"verseLabel":"الكهف: 79","question":"لماذا حُذفت صفة السفينة في قوله: ﴿يأخذ كل سفينة غصبًا﴾؟","answer":"دل السياق على أن المراد كل سفينة صالحة؛ لأن السفينة المعيبة لا يطمع الملك في اغتصابها، فحذفت الصفة اعتمادًا على القرينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص450، تحت «دلالة حذف صفة لفظ سفينة»","url":""}]},{"id":"s18-171","number":171,"surah":18,"verses":[80],"references":[{"surah":18,"verses":[80]}],"verseLabel":"الكهف: 80","question":"ما دلالة قول الخضر عن الغلام: ﴿فَخَشِينَا أَنْ يُرْهِقَهُمَا﴾؟","answer":"من توجيهات الكلام أن الخضر يتحدث عما علمه بإعلام الله من حال الغلام لو بقي، وأن ضمير الجمع يشير إلى أن فعله لم يستقل به عن الأمر الإلهي. ويذكر المصدر للضمير والخشية توجيهات أخرى؛ والمقصود كشف ما خفي من عاقبة الغلام على أبويه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص454، تحت «التعبير بالفعل المضارع يرهقهما»","url":""}]},{"id":"s18-172","number":172,"surah":18,"verses":[80],"references":[{"surah":18,"verses":[80]}],"verseLabel":"الكهف: 80","question":"لماذا جمع بين ﴿طُغْيَانًا وَكُفْرًا﴾؟","answer":"يجمع التعبير مجاوزة الحد والكفر، فيعظم الخطر على الأبوين المؤمنين. ومن توجيهاته أنه يرهقهما بطغيانه وكفره، أو يحملهما حبهما له على موافقته؛ وليس المقصود أذى دنيويًّا مجردًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص454، تحت «سر عطف قوله كفرًا على طغيانًا»","url":""}]},{"id":"s18-173","number":173,"surah":18,"verses":[81],"references":[{"surah":18,"verses":[81]}],"verseLabel":"الكهف: 81","question":"ما سرّ التعبير بـ﴿فَأَرَدْنَا أَنْ يُبْدِلَهُمَا رَبُّهُمَا﴾ بضمير الجمع؟","answer":"من توجيهات ضمير الجمع أنه للمتكلم مع إظهار المشاركة والتواضع، لأن الخضر يبين ما أطلعه الله عليه وأمره به. ويذكر المصدر توجيهات أخرى للمغايرة بين الإفراد والجمع، ثم يسند التبديل إلى الرب لأنه وحده الذي يهب العوض.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص455، تحت «سر التعبير بالجمع في فأردنا دون أردت»","url":""}]},{"id":"s18-174","number":174,"surah":18,"verses":[81],"references":[{"surah":18,"verses":[81]}],"verseLabel":"الكهف: 81","question":"ما دلالة وصف البديل بأنه ﴿خيرًا منه زكاة﴾؟","answer":"أي أطهر نفسًا وأصلح دينًا وخلقًا، فلا يرهق أبويه بطغيان أو كفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص457، تحت «سر الوصف بالزكاة في قوله خيرًا منه زكاة»","url":""}]},{"id":"s18-239","number":239,"surah":18,"verses":[81],"references":[{"surah":18,"verses":[81]}],"verseLabel":"الكهف: 81","question":"ما دلالة وصف البديل بأنه ﴿أقرب رحمًا﴾؟","answer":"يبشر بولد أبر بوالديه وأشد رحمة وصلة بهما، فيجمع صلاح نفسه وحسن أثره في أسرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص458، تحت «سر عطف قوله وأقرب رحمًا على سابقه»","url":""}]},{"id":"s18-175","number":175,"surah":18,"verses":[82],"references":[{"surah":18,"verses":[82]}],"verseLabel":"الكهف: 82","question":"ما سرّ التعبير في قصة الجدار بـ﴿فَأَرَادَ رَبُّكَ﴾؟","answer":"أُسندت الإرادة إلى الله لأن حفظ الكنز كرامة محضة لأبي الغلامين بسبب صلاحه، بخلاف القصتين السابقتين ففيهما دفع فساد يدركه من وقف على سره.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص469، تحت «نكتة نسبة الإرادة إلى الرب هنا دون ما سبق»","url":""}]},{"id":"s18-176","number":176,"surah":18,"verses":[82],"references":[{"surah":18,"verses":[82]}],"verseLabel":"الكهف: 82","question":"ما دلالة ذكر صلاح الأب في بيان سبب حفظ كنز الغلامين؟","answer":"كان حفظ الكنز لطفًا بالغلامين وجزاءً لأبيهما على صلاحه واهتمامه بمعيشتهما بعده، لئلا ينكشف المال قبل بلوغهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص468، تحت «فائدة الوصف بالصلاح للأب»","url":""}]},{"id":"s18-177","number":177,"surah":18,"verses":[82],"references":[{"surah":18,"verses":[82]}],"verseLabel":"الكهف: 82","question":"ما دلالة ختام بيان الخضر بقوله: ﴿وَمَا فَعَلْتُهُ عَنْ أَمْرِي﴾؟","answer":"ليزيل إنكار موسى ويبين أن التصرفات رحمة ومصلحة، وأنها لم تصدر عن اجتهاد الخضر أو هوى نفسه بل عن وحي وأمر من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص473، تحت «فائدة التقييد بشبه الجملة عن أمري»","url":""}]},{"id":"s18-178","number":178,"surah":18,"verses":[83],"references":[{"surah":18,"verses":[83]}],"verseLabel":"الكهف: 83","question":"لماذا عُبّر بـ﴿سَأَتْلُو﴾ في خبر ذي القرنين دون سأخبر؟","answer":"التلاوة تفيد اتباع أجزاء الخبر بعضها بعضًا في ترتيب واتصال، وهو أنسب بعرض أحداث القصة متتابعة على السامعين من مجرد الإخبار المجمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص484، تحت «التعبير بالتلاوة في ﴿سَأَتْلُو﴾ دون الإخبار وغيره»","url":""}]},{"id":"s18-240","number":240,"surah":18,"verses":[83],"references":[{"surah":18,"verses":[83]}],"verseLabel":"الكهف: 83","question":"ما دلالة ﴿مِنْهُ﴾ في قوله: ﴿سَأَتْلُو عَلَيْكُمْ مِنْهُ ذِكْرًا﴾؟","answer":"تفيد (من) التبعيض؛ أي سيتلو عليهم بعض خبر ذي القرنين مما تتحقق به العبرة، لا جميع أخباره وأحواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص484، تحت «معنى (مِنْ) في شبه الجملة ﴿مِنْهُ﴾»","url":""}]},{"id":"s18-241","number":241,"surah":18,"verses":[83],"references":[{"surah":18,"verses":[83]}],"verseLabel":"الكهف: 83","question":"ما معنى ﴿ذِكْرًا﴾، وما سر تنكيرها في خبر ذي القرنين؟","answer":"الذكر هنا الخبر الذي يُتلى ويُحفظ للاتعاظ، وجاء منكرًا لأن المقصود بعض أخباره النافعة للعبرة، لا استقصاء جميع أحواله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص485، تحت «معنى ﴿ذِكْرًا﴾ وسر وروده منكرًا»","url":""}]},{"id":"s18-179","number":179,"surah":18,"verses":[84],"references":[{"surah":18,"verses":[84]}],"verseLabel":"الكهف: 84","question":"ما دلالة الجمع لذي القرنين بين التمكين وإيتاء الأسباب؟","answer":"مكّن الله له في الأرض وآتاه وسائل الوصول إلى مقاصده؛ فالسبب هو الوسيلة، ويطلق في سياق رحلاته على الطريق الموصل إلى المكان المقصود.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص489، تحت «سر التقييد بالمفعول به سببًا منكرًا مفردًا»","url":""}]},{"id":"s18-180","number":180,"surah":18,"verses":[85],"references":[{"surah":18,"verses":[85]}],"verseLabel":"الكهف: 85","question":"ما دلالة تكرار ذكر السبب واتباعه في رحلات ذي القرنين؟","answer":"يدل تكرار ذكر السبب واتباعه على سلوك ذي القرنين طريقًا مناسبًا لكل وجهة من رحلاته. وجاء الانتقال بين الرحلات مع استمرار الأخذ بما آتاه الله من وسائل بلوغ المقاصد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص533، تحت «دلالة التكرار في قوله ثم أتبع سببًا»","url":""}]},{"id":"s18-181","number":181,"surah":18,"verses":[86],"references":[{"surah":18,"verses":[86]}],"verseLabel":"الكهف: 86","question":"ما سرّ التعبير بـ﴿وَجَدَهَا تَغْرُبُ فِي عَيْنٍ حَمِئَةٍ﴾؟","answer":"وصف ما يلوح للناظر عند منتهى المعمور من جهة الغرب؛ فليس للشمس مغرب حقيقي في عين، وإنما يبدو ذلك للتخيل عند الأفق.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص501، تحت «سر وصف العين بحمئة»","url":""}]},{"id":"s18-182","number":182,"surah":18,"verses":[86],"references":[{"surah":18,"verses":[86]}],"verseLabel":"الكهف: 86","question":"ما دلالة تخيير ذي القرنين بين تعذيب القوم والإحسان إليهم؟","answer":"يدل على تمكينه من الحكم مع إلزامه بالعدل، فيعامل الناس بحسب إيمانهم وظلمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص503، تحت «دلالة التخيير»","url":""}]},{"id":"s18-242","number":242,"surah":18,"verses":[86],"references":[{"surah":18,"verses":[86]}],"verseLabel":"الكهف: 86","question":"ما دلالة قوله لذي القرنين: ﴿أو تتخذ فيهم حسنًا﴾؟","answer":"أطلق الحسن وأريد به المعاملة الحسنة من الدعوة والرفق والعدل؛ فعبّر بالمعنى الجامع عن وجوه الإحسان كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص506، تحت «بلاغة المجاز المرسل في حسنًا»","url":""}]},{"id":"s18-183","number":183,"surah":18,"verses":[87,88],"references":[{"surah":18,"verses":[87,88]}],"verseLabel":"الكهف: 87-88","question":"ما دلالة تكرار ﴿أما﴾ في حكم ذي القرنين؟","answer":"يفصل بين مصير الظالم والمؤمن فصلًا واضحًا، ويبرز عدله في تنزيل الجزاء على اختلاف العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص514، تحت «سر تكرار أما»","url":""}]},{"id":"s18-243","number":243,"surah":18,"verses":[87,88],"references":[{"surah":18,"verses":[87,88]}],"verseLabel":"الكهف: 87-88","question":"لماذا عطف العمل الصالح على الإيمان في حكم ذي القرنين؟","answer":"لأن دعوى الإيمان لا تكفي وحدها، بل يظهر صدقها في العمل الصالح الذي يستحق صاحبه الحسنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص515، تحت «دلالة عطف العمل الصالح على الإيمان»","url":""}]},{"id":"s18-184","number":184,"surah":18,"verses":[88],"references":[{"surah":18,"verses":[88]}],"verseLabel":"الكهف: 88","question":"ما سرّ التعبير بـ﴿وَسَنَقُولُ لَهُ مِنْ أَمْرِنَا يُسْرًا﴾؟","answer":"أي نكلف المؤمن بما هو سهل ونخاطبه بلين، فجمع له حسن الجزاء وحسن المعاملة في سلطان ذي القرنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص519، تحت «الغرض من تنكير لفظ يسرًا»","url":""}]},{"id":"s18-185","number":185,"surah":18,"verses":[90],"references":[{"surah":18,"verses":[90]}],"verseLabel":"الكهف: 90","question":"ما دلالة قوله عن القوم ﴿لَمْ نَجْعَلْ لَهُمْ مِنْ دُونِهَا سِتْرًا﴾؟","answer":"كانوا في أرض مكشوفة لا ساتر فيها من حر الشمس، أو لم تكن لهم ثياب ولا مساكن تقيهم منها؛ وهو وصف لشدة انكشاف بيئتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص529، تحت «بلاغة الكناية في عدم جعل الستر من دونها»","url":""}]},{"id":"s18-186","number":186,"surah":18,"verses":[91],"references":[{"surah":18,"verses":[91]}],"verseLabel":"الكهف: 91","question":"ما دلالة قوله ﴿وَقَدْ أَحَطْنَا بِمَا لَدَيْهِ خُبْرًا﴾؟","answer":"أي أحاط الله علمًا بما عند ذي القرنين من عظمة الملك والجند والقوة والثروة؛ وفي التعبير كناية عن عظم ذلك بحيث لا يحيط به إلا علام الغيوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص531، تحت «دلالة التعبير بجملة وقد أحطنا»","url":""}]},{"id":"s18-187","number":187,"surah":18,"verses":[93],"references":[{"surah":18,"verses":[93]}],"verseLabel":"الكهف: 93","question":"ما سرّ وصف القوم بأنهم ﴿لَا يَكَادُونَ يَفْقَهُونَ قَوْلًا﴾؟","answer":"يصوّر صعوبة التفاهم معهم، ومن توجيهاته غرابة لغتهم أو قلة فهمهم وبداوتهم. ولا ينفي حصول التفاهم بعد جهد؛ فقد حكى السياق طلبهم وجواب ذي القرنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص541، تحت «سر التعبير بالفعل يفقهون دون غيره»","url":""}]},{"id":"s18-188","number":188,"surah":18,"verses":[94],"references":[{"surah":18,"verses":[94]}],"verseLabel":"الكهف: 94","question":"ما دلالة قولهم ﴿إِنَّ يَأْجُوجَ وَمَأْجُوجَ مُفْسِدُونَ فِي الْأَرْضِ﴾؟","answer":"بيّنوا سبب طلب السد: كانوا أضعف من يأجوج ومأجوج ويصيب بلادهم فسادهم المتكرر، فطلبوا حاجزًا يقيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص546، تحت «دلالة التعبير بالمسند مفسدون جمعًا»","url":""}]},{"id":"s18-189","number":189,"surah":18,"verses":[94],"references":[{"surah":18,"verses":[94]}],"verseLabel":"الكهف: 94","question":"ما دلالة عرض القوم ﴿خَرْجًا﴾ على ذي القرنين؟","answer":"عرضوا مالًا يجمعونه له في مقابلة أن يجعل بينهم وبين المفسدين سدًا، لما علموا أن العمل يحتاج مؤونة وصناعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص548، تحت «دلالة لفظ خرجًا وتنكيره وتأخيره»","url":""}]},{"id":"s18-190","number":190,"surah":18,"verses":[95],"references":[{"surah":18,"verses":[95]}],"verseLabel":"الكهف: 95","question":"ما دلالة استغناء ذي القرنين عن مالهم بقوله: ﴿مَا مَكَّنِّي فِيهِ رَبِّي خَيْرٌ﴾؟","answer":"استغنى بما مكّنه الله فيه من الملك والقدرة عن مالهم، واكتفى بأن يعينوه بقوة العمل والآلات.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص561، تحت «سر اختيار لفظ الربوبية مضافًا»","url":""}]},{"id":"s18-191","number":191,"surah":18,"verses":[95],"references":[{"surah":18,"verses":[95]}],"verseLabel":"الكهف: 95","question":"ما دلالة قوله ﴿فَأَعِينُونِي بِقُوَّةٍ﴾؟","answer":"طلب منهم قوة الأبدان والعمل والآلات لإقامة الردم، بدل المال الذي عرضوه؛ فكانوا عمال التنفيذ تحت تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص562، تحت «سر التعبير بالقوة نكرة»","url":""}]},{"id":"s18-192","number":192,"surah":18,"verses":[97],"references":[{"surah":18,"verses":[97]}],"verseLabel":"الكهف: 97","question":"ما سرّ اختلاف الصيغتين في ﴿فَمَا اسْطَاعُوا أَنْ يَظْهَرُوهُ وَمَا اسْتَطَاعُوا لَهُ نَقْبًا﴾؟","answer":"خففت الأولى للتفنن وتجنب إعادة الكلمة، وناسبت الصيغة الزائدة النقب لأنه أشد من تسلق الردم؛ فزيادة المبنى وافقت زيادة المعنى.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص573، 574، 575، 576، تحت «دلالة التعبير باسطاعوا محذوف التاء؛ سر عدم حذف التاء من الفعل كسابقه»","url":""}]},{"id":"s18-193","number":193,"surah":18,"verses":[98],"references":[{"surah":18,"verses":[98]}],"verseLabel":"الكهف: 98","question":"ما دلالة قول ذي القرنين ﴿هَذَا رَحْمَةٌ مِنْ رَبِّي﴾ بعد الإنجاز؟","answer":"نسب إنجاز الردم إلى رحمة الله وتوفيقه، لما فيه من حماية الناس من فساد يأجوج ومأجوج. وفي ذلك اعتراف بالنعمة وتواضع عند ظهور القوة، وتنكير «رحمة» لتعظيمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص581، تحت «علة التعبير بلفظ رحمة وتنكيره»","url":""}]},{"id":"s18-194","number":194,"surah":18,"verses":[98],"references":[{"surah":18,"verses":[98]}],"verseLabel":"الكهف: 98","question":"ما دلالة قوله ﴿فَإِذَا جَاءَ وَعْدُ رَبِّي جَعَلَهُ دَكَّاءَ﴾؟","answer":"مهما بلغ الردم من الصلابة فبقاؤه مؤقت إلى الوقت الذي وعد الله فيه بخروج يأجوج ومأجوج؛ عندئذ يسويه بالأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص585، تحت «سر إضافة الوعد إلى لفظ الربوبية»","url":""}]},{"id":"s18-195","number":195,"surah":18,"verses":[99],"references":[{"surah":18,"verses":[99]}],"verseLabel":"الكهف: 99","question":"ما سرّ التعبير بـ﴿يَمُوجُ فِي بَعْضٍ﴾؟","answer":"تصوّر الاستعارة كثرة الخلق واضطرابهم وتدافعهم كموج البحر. ويرجح المصدر عود الضمير إلى عموم الخلق يوم القيامة لمناسبة ما بعده من الجمع، ويذكر وجهًا آخر في يأجوج ومأجوج عند خروجهم؛ فلا يُحصر المعنى في الوجه الأخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص593، تحت «بلاغة الاستعارة في جملة يموج في بعض»","url":""}]},{"id":"s18-196","number":196,"surah":18,"verses":[100],"references":[{"surah":18,"verses":[100]}],"verseLabel":"الكهف: 100","question":"ما دلالة توكيد ﴿وَعَرَضْنَا جَهَنَّمَ يَوْمَئِذٍ لِلْكَافِرِينَ عَرْضًا﴾ بالمصدر؟","answer":"يحقق المصدر وقوع العرض ويؤكده، ويهوّل تنكيره ذلك المشهد. ويذكر المصدر في «عرضنا» وجهًا من التهكم بإظهار جهنم كأنها مما يُرغَب فيه، ووجهًا آخر هو الكناية عن تعذيبهم بها؛ فلا يلزم حصر التعبير في التهكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص603، تحت «دلالة التعبير بالمفعول المطلق عرضًا»","url":""}]},{"id":"s18-197","number":197,"surah":18,"verses":[101],"references":[{"surah":18,"verses":[101]}],"verseLabel":"الكهف: 101","question":"ما سرّ التعبير بـ﴿فِي غِطَاءٍ عَنْ ذِكْرِي﴾؟","answer":"الغطاء استعارة لعدم انتفاعهم بدلالة أبصارهم على تفرد الله، و﴿في﴾ تصور تمكن الغطاء منهم، و﴿عن﴾ مجاوزتهم النظر فيما يذكر بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص607، تحت «بلاغة الاستعارة في غطاء»","url":""}]},{"id":"s18-198","number":198,"surah":18,"verses":[101],"references":[{"surah":18,"verses":[101]}],"verseLabel":"الكهف: 101","question":"ما سرّ التعبير بـ﴿لَا يَسْتَطِيعُونَ سَمْعًا﴾؟","answer":"يصوّر شدة إعراضهم عن سماع الحق حتى كأنهم فقدوا القدرة على الانتفاع بالسمع. ويذكر المصدر نفي مطاوعة نفوسهم للاستماع لشدة كراهتهم له؛ فالمراد إعراض راسخ، لا مجرد فقد الحاسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص609، تحت «سر التعبير بنفي استطاعة السمع دون الصمم»","url":""}]},{"id":"s18-199","number":199,"surah":18,"verses":[102],"references":[{"surah":18,"verses":[102]}],"verseLabel":"الكهف: 102","question":"ما دلالة الاستفهام في إنكار اتخاذ عباد الله أولياء من دونه؟","answer":"الاستفهام إنكاري لحسبانهم الباطل أن أولياءهم من دون الله سينفعونهم وينصرونهم، وقد نشأ هذا الحسبان من إعراضهم عن دلائل التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص614، تحت «بلاغة الاستفهام في صدر الآية الكريمة»","url":""}]},{"id":"s18-200","number":200,"surah":18,"verses":[103],"references":[{"surah":18,"verses":[103]}],"verseLabel":"الكهف: 103","question":"ما دلالة الاستفهام في ﴿هَلْ نُنَبِّئُكُمْ بِالْأَخْسَرِينَ أَعْمَالًا﴾؟","answer":"الاستفهام للتشويق إلى خبر عجيب: أناس ضل عملهم وهم يحسبون أنهم يحسنون، فجمعوا خسارة السعي وخسارة الاعتقاد فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص625، تحت «الغرض من افتتاح الكلام بالاستفهام في صدر الآية»","url":""}]},{"id":"s18-201","number":201,"surah":18,"verses":[104],"references":[{"surah":18,"verses":[104]}],"verseLabel":"الكهف: 104","question":"ما دلالة الجمع بين ضلال السعي وحسبان أصحابه أنهم يحسنون صنعًا؟","answer":"ضل عملهم عن طريق النفع وبطل أثره، وزاد خسارهم أنهم كانوا يعتقدون فسادهم صلاحًا؛ فجهلوا سوء العمل وسوء اعتقادهم فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص636، تحت «سر التعبير بالجملة الحالية في وهم يحسبون»","url":""}]},{"id":"s18-202","number":202,"surah":18,"verses":[105],"references":[{"surah":18,"verses":[105]}],"verseLabel":"الكهف: 105","question":"ما سرّ التعبير بـ﴿فَحَبِطَتْ أَعْمَالُهُمْ﴾؟","answer":"الحبوط بطلان أثر العمل بعد وجود صورته؛ فكفرهم بآيات الله ولقائه أذهب ما توهموه نافعًا من أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص644، تحت «دلالة التعبير بصيغة الماضي حبطت»","url":""}]},{"id":"s18-203","number":203,"surah":18,"verses":[105],"references":[{"surah":18,"verses":[105]}],"verseLabel":"الكهف: 105","question":"ما سرّ التعبير بـ﴿فَلَا نُقِيمُ لَهُمْ يَوْمَ الْقِيَامَةِ وَزْنًا﴾؟","answer":"نفي الوزن كناية عن عدم الاعتداد بهم وحقارتهم؛ فالشيء التافه لا يوزن، وقد تفرع ذلك على حبوط أعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص647، تحت «الغرض من التعبير بعدم إقامة الوزن»","url":""}]},{"id":"s18-204","number":204,"surah":18,"verses":[106],"references":[{"surah":18,"verses":[106]}],"verseLabel":"الكهف: 106","question":"ما دلالة قوله ﴿ذَلِكَ جَزَاؤُهُمْ جَهَنَّمُ﴾؟","answer":"من توجيهات اسم الإشارة أنه يعود إلى إعداد جهنم السابق، فتكون «جزاؤهم» خبرًا و«جهنم» بدلًا يبينه ويؤكد الوعيد. ويذكر المصدر أوجهًا أخرى في مرجع الإشارة والإعراب، تشترك في بيان استحقاقهم الجزاء بسبب كفرهم واستهزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص649، تحت «نكتة مرجع الإشارة للفظ ذلك وسر التعبير به»","url":""}]},{"id":"s18-205","number":205,"surah":18,"verses":[107],"references":[{"surah":18,"verses":[107]}],"verseLabel":"الكهف: 107","question":"لماذا قال في الكافرين: ﴿إنا أعتدنا﴾ ولم يكررها عند ذكر جنات المؤمنين؟","answer":"دل ذكر الإعداد أولًا وسياق المقابلة على المحذوف، فاستغنى عن تكراره مع المؤمنين إيجازًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص660، تحت «نكتة عدم ذكر أعتدنا للمؤمنين مع ذكره للكافرين»","url":""}]},{"id":"s18-244","number":244,"surah":18,"verses":[107],"references":[{"surah":18,"verses":[107]}],"verseLabel":"الكهف: 107","question":"ما سر وصف جنات الفردوس بأنها ﴿نزلًا﴾؟","answer":"النزل ما يهيأ للضيف عند قدومه؛ فوصف الجنة به يشعر بالإكرام، وإذا كان هذا نزلهم فما أعظم ما وراءه من نعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص661، تحت «دلالة التعبير بالنزل في سياق الآية الأكمل»","url":""}]},{"id":"s18-206","number":206,"surah":18,"verses":[108],"references":[{"surah":18,"verses":[108]}],"verseLabel":"الكهف: 108","question":"ما سرّ التعبير بـ﴿لَا يَبْغُونَ عَنْهَا حِوَلًا﴾؟","answer":"لا يتطلعون إلى مفارقتها إلى مكان خير، لأنهم يجدون فيها كل ما تشتهيه نفوسهم من ضروب اللذات.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص666، تحت «بلاغة التعبير بقوله لا يبغون عنها حولًا»","url":""}]},{"id":"s18-207","number":207,"surah":18,"verses":[109],"references":[{"surah":18,"verses":[109]}],"verseLabel":"الكهف: 109","question":"ما دلالة تمثيل البحر مدادًا لكلمات الله؟","answer":"شبهت معلومات الله التي يخبر بها بالمكتوبات، ورمز إلى الكتابة بالمداد؛ فلو كان البحر حبرًا لكتابتها لنفد مع استحالة نفاد معلومات الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص673، تحت «بلاغة المجاز في لو كان البحر مدادًا لكلمات ربي»","url":""}]},{"id":"s18-208","number":208,"surah":18,"verses":[109],"references":[{"surah":18,"verses":[109]}],"verseLabel":"الكهف: 109","question":"ما دلالة قوله ﴿وَلَوْ جِئْنَا بِمِثْلِهِ مَدَدًا﴾؟","answer":"هذه مبالغة ثانية: حتى لو مُد البحر ببحر مثله لبقي نفاد المداد ممكنًا، ولم تقارب كلمات الله النفاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص676، تحت «موقع قوله ولو جئنا بمثله مددًا مما قبله ودلالته»","url":""}]},{"id":"s18-209","number":209,"surah":18,"verses":[110],"references":[{"surah":18,"verses":[110]}],"verseLabel":"الكهف: 110","question":"ما دلالة قوله في ختام السورة: ﴿إِنَّمَا أَنَا بَشَرٌ مِثْلُكُمْ﴾؟","answer":"يبين أنه بشر لا يحيط بالغيب، وأن ما أخبر به من أمر الغيب مستند إلى الوحي. فبعد الأجوبة الواردة في السورة يوجّه الختام إلى حقيقة الرسالة وما أوحاه الله إليه من التوحيد والعمل الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص683، تحت «الغرض من التعبير بأسلوب القصر في الآية»","url":""}]},{"id":"s18-210","number":210,"surah":18,"verses":[110],"references":[{"surah":18,"verses":[110]}],"verseLabel":"الكهف: 110","question":"ما دلالة إبراز توحيد الله في قوله: ﴿أَنَّمَا إِلَهُكُمْ إِلَهٌ وَاحِدٌ﴾؟","answer":"لأن توحيد الله أهم ما أوحي إلى الرسول وما بعث لأجله، ثم فرع عليه الإيمان بالبعث والعمل الصالح والنهي عن الإشراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص685، تحت «بلاغة القصر في قوله أنما إلهكم إله واحد»","url":""}]},{"id":"s18-211","number":211,"surah":18,"verses":[110],"references":[{"surah":18,"verses":[110]}],"verseLabel":"الكهف: 110","question":"ما دلالة الأمر بالعمل الصالح في ختام سورة الكهف؟","answer":"يبين أن رجاء لقاء الله لا يصح بالدعوى، بل يصدقه عمل صالح موافق لأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص688، تحت «الغرض من التعبير بالأمر بالعمل الصالح»","url":""}]},{"id":"s18-245","number":245,"surah":18,"verses":[110],"references":[{"surah":18,"verses":[110]}],"verseLabel":"الكهف: 110","question":"ما دلالة الجمع بين العمل الصالح وقوله: ﴿ولا يشرك بعبادة ربه أحدًا﴾؟","answer":"جمع بين صحة العمل وإخلاص القصد؛ فلا يقبل العمل حتى يكون صالحًا وخالصًا لله من الشرك والرياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص689، تحت «دلالة الواو في ولا يشرك»","url":""}]},{"id":"s18-212","number":212,"surah":18,"verses":[110],"references":[{"surah":18,"verses":[110]}],"verseLabel":"الكهف: 110","question":"ما سرّ تنكير ﴿أَحَدًا﴾ في قوله ﴿وَلَا يُشْرِكْ بِعِبَادَةِ رَبِّهِ أَحَدًا﴾؟","answer":"النكرة في سياق النهي تعم كل أحد، فيكون ختام السورة تأكيدًا لوحدانية الله ونفي كل مشاركة في عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص691، تحت «النكتة من تنكير ﴿أحدًا﴾»","url":""}]},{"id":"s19-1","number":1,"surah":19,"verses":[1],"references":[{"surah":19,"verses":[1]}],"verseLabel":"مريم: 1","question":"ما دلالة افتتاح السورة بالحروف ﴿كهيعص﴾؟","answer":"يذكر المصدر أقوالًا في الحروف المقطعة، منها تفويض علم حقيقتها إلى الله، ويرجح هنا أنها حروف تنبّه إلى إعجاز القرآن المؤلف من جنس حروف العرب. فلا يجزم بمعنى تفصيلي لكل حرف.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص704–705، تحت عنوان «بيان المراد بالحروف المقطعة»","url":""}]},{"id":"s19-2","number":2,"surah":19,"verses":[2],"references":[{"surah":19,"verses":[2]}],"verseLabel":"مريم: 2","question":"لماذا استُهلت قصة زكريا بقوله ﴿ذِكْرُ رَحْمَتِ رَبِّكَ﴾؟","answer":"ليستحضر السامع رحمة الله السابقة وكرامته لأوليائه قبل سرد تفاصيل القصص؛ فجاء الافتتاح مهيئًا لتلقي القصة بوصفها أثرًا من آثار رحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص706–707، تحت عنوان «حسن الافتتاح بقوله: ﴿ذِكْرُ﴾»","url":""}]},{"id":"s19-120","number":120,"surah":19,"verses":[2],"references":[{"surah":19,"verses":[2]}],"verseLabel":"مريم: 2","question":"لماذا قيل ﴿رَحْمَتِ رَبِّكَ﴾ في قصة زكريا مع أن الخطاب للنبي ﷺ؟","answer":"في إضافة الرب إلى ضمير النبي ﷺ تنويه بشأنه؛ فالربوبية تتضمن التربية والتكميل، وتنزيل هذه السورة عليه من آثار هذه العناية به، فشمل التكريم متلقي القصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص708–709، تحت عنوان «نكتة إضافة الربوبية إلى ضمير الخطاب»","url":""}]},{"id":"s19-121","number":121,"surah":19,"verses":[2],"references":[{"surah":19,"verses":[2]}],"verseLabel":"مريم: 2","question":"لماذا وصف زكريا بالعبودية في قوله ﴿عَبْدَهُ زَكَرِيَّا﴾؟","answer":"تنويهًا بشأنه وتعظيمًا لحاله؛ فالعبودية لله غاية الشرف والكرامة، وفي الوصف إشارة إلى أنها سبيل نيل الهبات والرحمات.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص709، تحت عنوان «سر التعبير بالعبودية»","url":""}]},{"id":"s19-3","number":3,"surah":19,"verses":[3],"references":[{"surah":19,"verses":[3]}],"verseLabel":"مريم: 3","question":"ما دلالة الجمع بين النداء والخفاء في دعاء زكريا؟","answer":"يذكر المصدر أن النداء كناية عن شدة الاحتياج، وأن وصفه بالخفاء يدفع توهم رفع الصوت؛ وهذا أوضح الأوجه عنده. ويذكر وجهًا آخر يجعل الخفاء دالًا على الإخلاص، أما الإخلاص على الوجه الأول فيُفهم من حال زكريا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص713، تحت عنوان «بلاغة الجمع بين النداء والخفاء»","url":""}]},{"id":"s19-4","number":4,"surah":19,"verses":[4],"references":[{"surah":19,"verses":[4]}],"verseLabel":"مريم: 4","question":"ما سرّ التعبير بـ﴿وَهَنَ الْعَظْمُ مِنِّي﴾ لا «ضعف جسمي»؟","answer":"العظم قوام البدن؛ فإذا دب الوهن في أصله دل على بلوغ الضعف غايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص722–723، تحت عنوان «بلاغة إسناد الوهن إلى العظم بين الكناية والمجاز»","url":""}]},{"id":"s19-5","number":5,"surah":19,"verses":[4],"references":[{"surah":19,"verses":[4]}],"verseLabel":"مريم: 4","question":"ما سر صورة ﴿وَاشْتَعَلَ الرَّأْسُ شَيْبًا﴾؟","answer":"شبّه انتشار الشيب باشتعال النار، فصور سرعة عمومه وسطوعه في الرأس كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص725–726، تحت عنوان «براعة الاستعارة وقوتها»","url":""}]},{"id":"s19-6","number":6,"surah":19,"verses":[4],"references":[{"surah":19,"verses":[4]}],"verseLabel":"مريم: 4","question":"ما سرّ التعبير بـ﴿وَلَمْ أَكُنْ بِدُعَائِكَ رَبِّ شَقِيًّا﴾؟","answer":"توسل بسابق لطف الله؛ فلم تكن دعواته الماضية سبب خيبة، فرجا استمرار العناية.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص728، تحت عنوان «غرض الإخبار بما كان»","url":""}]},{"id":"s19-7","number":7,"surah":19,"verses":[5],"references":[{"surah":19,"verses":[5]}],"verseLabel":"مريم: 5","question":"ما سرّ التعبير بـ﴿خِفْتُ الْمَوَالِيَ مِنْ وَرَائِي﴾؟","answer":"خاف ممن يلون أمر قومه بعده أن يضيعوا الدين، لا مجرد فقد وارث لماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص731–732، تحت عنوان «نكتة استعمال مفردة الخوف»","url":""}]},{"id":"s19-8","number":8,"surah":19,"verses":[5],"references":[{"surah":19,"verses":[5]}],"verseLabel":"مريم: 5","question":"لماذا قال زكريا ﴿وَكَانَتِ امْرَأَتِي عَاقِرًا﴾ بصيغة الماضي؟","answer":"للدلالة على أن العقر قديم فيها، وأنها لم تلد منذ زمن؛ ففيه بيان استبعاد حصول الولد بحسب الأسباب العادية، وزيادة الاستعطاف في الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص733–734، تحت عنوان «دلالة التعبير بصيغة الماضي في فعل الكون»","url":""}]},{"id":"s19-122","number":122,"surah":19,"verses":[5],"references":[{"surah":19,"verses":[5]}],"verseLabel":"مريم: 5","question":"ماذا تضيف صيغة اسم الفاعل ﴿عَاقِرًا﴾ إلى وصف امرأة زكريا؟","answer":"تدل، في هذا السياق، على تمكن صفة العقر منها وثبوتها واستمرارها؛ ويؤكد هذا الرسوخ التعبير بالماضي في ﴿كانت﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص760، تحت عنوان «دلالة التعبير بصيغة اسم الفاعل»","url":""}]},{"id":"s19-9","number":9,"surah":19,"verses":[5],"references":[{"surah":19,"verses":[5]}],"verseLabel":"مريم: 5","question":"ما سر طلب زكريا ﴿وَلِيًّا﴾ في هذا المقام؟","answer":"لأنه طلب من يلي أمر الدين ويحفظ الدعوة، لا ولدًا لمجرد الأنس والنسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص736، تحت عنوان «سر التعبير بقوله: ﴿وَلِيًّا﴾»","url":""}]},{"id":"s19-10","number":10,"surah":19,"verses":[6],"references":[{"surah":19,"verses":[6]}],"verseLabel":"مريم: 6","question":"لماذا عُبّر بالإرث في دعاء زكريا ﴿يَرِثُنِي وَيَرِثُ مِنْ آلِ يَعْقُوبَ﴾؟","answer":"يرجح المصدر أن المراد وراثة العلم والدين؛ فاستعير الإرث، الذي أصله انتقال المال، لانتقال هذا الخير المعنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص738، تحت عنوان «بلاغة الاستعارة في مفردة الإرث»","url":""}]},{"id":"s19-123","number":123,"surah":19,"verses":[6],"references":[{"surah":19,"verses":[6]}],"verseLabel":"مريم: 6","question":"لماذا تكرر فعل الإرث في ﴿يَرِثُنِي وَيَرِثُ مِنْ آلِ يَعْقُوبَ﴾؟","answer":"لزيادة العناية بالإرث من آل يعقوب وجعله مقصودًا مستقلًا، بدل الاكتفاء بعطفهم على زكريا تحت فعل واحد؛ وفي ذلك مبالغة في طلب الوارث الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص739، تحت عنوان «نكتة تكرار فعل الإرث»","url":""}]},{"id":"s19-11","number":11,"surah":19,"verses":[6],"references":[{"surah":19,"verses":[6]}],"verseLabel":"مريم: 6","question":"ما سرّ التعبير بـ﴿وَاجْعَلْهُ رَبِّ رَضِيًّا﴾؟","answer":"لم يكتف بوجود الوارث، بل سأل صلاحه وقبول الله له؛ فالذرية نعمة بصلاحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص741، تحت عنوان «نوع الواو ودلالتها في قوله تعالى: ﴿وَاجْعَلْهُ﴾»","url":""}]},{"id":"s19-12","number":12,"surah":19,"verses":[7],"references":[{"surah":19,"verses":[7]}],"verseLabel":"مريم: 7","question":"ما سرّ التعبير بـ﴿لَمْ نَجْعَلْ لَهُ مِنْ قَبْلُ سَمِيًّا﴾؟","answer":"من وجوه التكريم أن الله اختار له اسم يحيى، ولم يسبق أن سُمّي به أحد على ظاهر هذا التوجيه. وفي الاسم المبتكر تشريف للمولود وإكرام لأبيه زكريا.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص752–753، تحت عنوان «فائدة اختصاص يحيى بهذا الاسم»","url":""}]},{"id":"s19-13","number":13,"surah":19,"verses":[8],"references":[{"surah":19,"verses":[8]}],"verseLabel":"مريم: 8","question":"ما دلالة سؤال زكريا عن حصول الولد بعد أن بُشّر به؟","answer":"لم يشك في القدرة، وإنما سأل عن كيفية تحقق البشرى مع اجتماع الشيخوخة والعقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص757–758، تحت عنوان «غرض الاستفهام»","url":""}]},{"id":"s19-14","number":14,"surah":19,"verses":[8],"references":[{"surah":19,"verses":[8]}],"verseLabel":"مريم: 8","question":"ما دلالة وصف زكريا حاله بأنه بلغ من الكبر ﴿عِتِيًّا﴾؟","answer":"شُبهت عظام زكريا بالأعواد اليابسة، وأثبت لها العتي، وهو اليبس؛ فتصور الاستعارة ما بلغته شيخوخته من شدة الضعف.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص764، تحت عنوان «بلاغة الاستعارة في: ﴿عِتِيًّا﴾»","url":""}]},{"id":"s19-15","number":15,"surah":19,"verses":[9],"references":[{"surah":19,"verses":[9]}],"verseLabel":"مريم: 9","question":"كيف يفيد قوله ﴿هُوَ عَلَيَّ هَيِّنٌ﴾ كمال القدرة؟","answer":"الهين في الاستعمال المعتاد ما لا يعجز فاعله؛ فأُطلق هنا للدلالة على كمال قدرة الله، وأن خلق يحيى مع عقر أمه وكبر أبيه لا يعجزه ولا يدعو إلى استبعاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص772، تحت عنوان «بلاغة المجاز في مفردة: ﴿هَيِّنٌ﴾»","url":""}]},{"id":"s19-124","number":124,"surah":19,"verses":[9],"references":[{"surah":19,"verses":[9]}],"verseLabel":"مريم: 9","question":"لماذا ذُكّر زكريا بخلقه هو في ﴿وَقَدْ خَلَقْتُكَ مِنْ قَبْلُ﴾ بدل ذكر خلق آدم؟","answer":"لأن عدم زكريا ووجوده أظهر عنده وأجلى، فكان الاحتجاج بما يعرفه من أصل نفسه أقوى في بيان إمكان ما بُشر به؛ وخلقه داخل في الخلق الذي بدأه الله من العدم.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص773–774، تحت عنوان «توجيه نسبة الخلق من العدم إلى زكريا لا إلى آدم»","url":""}]},{"id":"s19-16","number":16,"surah":19,"verses":[10],"references":[{"surah":19,"verses":[10]}],"verseLabel":"مريم: 10","question":"ما دلالة انحباس كلام زكريا مع وصفه بأنه ﴿سَوِيًّا﴾؟","answer":"انحباس الكلام مع سلامة الجسد علامة خارقة لا تُفسر بمرض أو عجز طبيعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص781، تحت عنوان «بلاغة الاحتراس والتأكيد في تعدد أوجه الإعراب»","url":""}]},{"id":"s19-17","number":17,"surah":19,"verses":[11],"references":[{"surah":19,"verses":[11]}],"verseLabel":"مريم: 11","question":"ماذا أفادت الفاء في ﴿فَخَرَجَ عَلَى قَوْمِهِ مِنَ الْمِحْرَابِ﴾؟","answer":"دلّت على خروجه عقب تحقق الآية التي أُعطيها، وهي ألا يكلم الناس ثلاث ليال سويًا؛ فهي فاء فصيحة تتضمن التعقيب، ثم خرج إلى قومه ليطلب منهم التسبيح.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص788، تحت عنوان «نوع الفاء ودلالتها»","url":""}]},{"id":"s19-18","number":18,"surah":19,"verses":[11],"references":[{"surah":19,"verses":[11]}],"verseLabel":"مريم: 11","question":"ما سرّ التعبير بـ﴿فَأَوْحَى إِلَيْهِمْ﴾ مع أنه لم يتكلم؟","answer":"الوحي هنا إبلاغ بغير الكلام المعتاد، ففسره المصدر بالإشارة، وذكر الكتابة وجهًا آخر. وهو يناسب حال زكريا حين امتنع عليه كلام الناس، فأفهمهم طلب التسبيح بهذه الوسيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص790، تحت عنوان «سر اختيار مفردة الوحي»","url":""}]},{"id":"s19-19","number":19,"surah":19,"verses":[12],"references":[{"surah":19,"verses":[12]}],"verseLabel":"مريم: 12","question":"ما دلالة الأمر ليحيى: ﴿خُذِ الْكِتَابَ بِقُوَّةٍ﴾؟","answer":"القوة جدّ في الفهم والعمل والحفظ، لا مجرد حمل الكتاب أو قراءته.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص797، تحت عنوان «دلالة التعبير بشبه الجملة: ﴿بِقُوَّةٍ﴾»","url":""}]},{"id":"s19-20","number":20,"surah":19,"verses":[12],"references":[{"surah":19,"verses":[12]}],"verseLabel":"مريم: 12","question":"ما المراد بـ﴿الْحُكْمَ﴾ في قوله ﴿وَآتَيْنَاهُ الْحُكْمَ﴾؟","answer":"يذكر المصدر أن الحكم أوسع من الحكمة؛ إذ يطلق على الحكمة والنبوة والأحكام والمعرفة بها. ومن تفسيره هنا أن الله أحكم عقل يحيى في صباه وأوحى إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص799، تحت عنوان «سر التعبير بـ: ﴿الْحُكْمَ﴾»","url":""}]},{"id":"s19-125","number":125,"surah":19,"verses":[12],"references":[{"surah":19,"verses":[12]}],"verseLabel":"مريم: 12","question":"لماذا قُيّد إيتاء يحيى الحكم بقوله ﴿صَبِيًّا﴾؟","answer":"لإبراز تعجيل إكرامه؛ فقد آتاه الله استقامة الفكر وقوة إدراك الحقائق في عمر مبكر على غير المعتاد. واختيار ﴿صبيًّا﴾ يحمل في هذا السياق معنى المدح الذي قد لا يؤديه لفظ «صغيرًا».","sources":[{"label":"موسوعة التفسير البلاغي، ج30، ص800، تحت عنوان «دلالة التعبير بـ: ﴿صَبِيًّا﴾»","url":""}]},{"id":"s19-21","number":21,"surah":19,"verses":[13],"references":[{"surah":19,"verses":[13]}],"verseLabel":"مريم: 13","question":"ما سرّ اختيار لفظ ﴿حَنَانًا﴾ لا «رحمة» فقط؟","answer":"الحنان رحمة مشوبة بعطف ورقة وإقبال، فناسب قلب النبي البار.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص12، تحت عنوان «سر التعبير بـ: ﴿وَحَنَانًا﴾»","url":""}]},{"id":"s19-22","number":22,"surah":19,"verses":[13],"references":[{"surah":19,"verses":[13]}],"verseLabel":"مريم: 13","question":"ماذا تضيف ﴿مِنْ لَدُنَّا﴾ إلى الحنان الذي أوتيه يحيى؟","answer":"تعظم هذا الحنان بنسبته إلى الله؛ فـ«لدن» تفيد صدوره من عنده وإمداده به، وهي أبلغ وأخص من «عندنا»، وتدل على حنان زائد على المعتاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص12–13، تحت عنوان «سر التعبير بـ: ﴿مِنْ لَدُنَّا﴾»","url":""}]},{"id":"s19-126","number":126,"surah":19,"verses":[13],"references":[{"surah":19,"verses":[13]}],"verseLabel":"مريم: 13","question":"ماذا تضيف ﴿زَكَاةً﴾ في وصف يحيى إلى مجرد الطهارة؟","answer":"الزكاة تجمع طهارة النفس وتنميتها بالخيرات والبركات؛ فليست مجرد تنقية من الدنس، بل تنقية مقرونة بالنماء في الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص15، تحت عنوان «الزكاة والطهارة»","url":""}]},{"id":"s19-23","number":23,"surah":19,"verses":[14],"references":[{"surah":19,"verses":[14]}],"verseLabel":"مريم: 14","question":"لماذا نُفي عن يحيى ﴿عَصِيًّا﴾، وعن عيسى ﴿شَقِيًّا﴾؟","answer":"خبر يحيى ثناء من الله عليه، فناسبه نفي المعصية. أما عيسى فيتحدث عن نفسه، فكان نفي الشقاء أدبًا عن تزكية النفس بنفي المعصية، وهو ملائم كذلك لنفي عقوق أمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص21، تحت عنوان «سر اختلاف التعبير: ﴿عَصِيًّا﴾، و﴿شَقِيًّا﴾»","url":""}]},{"id":"s19-127","number":127,"surah":19,"verses":[14],"references":[{"surah":19,"verses":[14]}],"verseLabel":"مريم: 14","question":"لماذا قيل في يحيى ﴿وَلَمْ يَكُنْ﴾، وفي كلام عيسى ﴿وَلَمْ يَجْعَلْنِي﴾؟","answer":"جاء نفي الصفة موافقًا لإثبات الصفات في كل سياق: سبق في يحيى ﴿وَكَانَ تَقِيًّا﴾ فناسبه ﴿وَلَمْ يَكُنْ﴾، وسبق في كلام عيسى ﴿وَجَعَلَنِي نَبِيًّا﴾ فناسبه ﴿وَلَمْ يَجْعَلْنِي﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص21–22، تحت عنوان «التشابه اللفظي»","url":""}]},{"id":"s19-24","number":24,"surah":19,"verses":[15],"references":[{"surah":19,"verses":[15]}],"verseLabel":"مريم: 15","question":"ما دلالة تخصيص الولادة والموت والبعث بالسلام على يحيى؟","answer":"هذه أشد مواطن الوحشة والانتقال، فخصه الله بالأمان فيها كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص31، تحت عنوان «دلالة تخصيص هذه الأوقات بالسلام»","url":""}]},{"id":"s19-25","number":25,"surah":19,"verses":[15,33],"references":[{"surah":19,"verses":[15,33]}],"verseLabel":"مريم: 15، 33","question":"ما سرّ تنكير السلام في يحيى ﴿وَسَلَامٌ عَلَيْهِ﴾ وتعريفه في عيسى ﴿وَالسَّلَامُ عَلَيَّ﴾؟","answer":"نُكّر السلام على يحيى لتفخيمه وتعظيمه، فهو سلام من الله يحفّه في أطوار حياته. ويقابل المصدر ذلك بالسلام المعرّف الوارد على لسان عيسى، مع التنبيه إلى اختلاف جهة صدور الكلام في الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص27، تحت عنوان «دلالة التنكير في: ﴿وَسَلَامٌ﴾»","url":""}]},{"id":"s19-26","number":26,"surah":19,"verses":[16],"references":[{"surah":19,"verses":[16]}],"verseLabel":"مريم: 16","question":"لماذا افتُتحت قصة مريم بالأمر ﴿وَاذْكُرْ﴾؟","answer":"لزيادة الاهتمام بشأن القصة وتشويق السامع إلى تدبرها؛ ففيها دلائل تبين قدرة الله على الخلق وتدعو إلى تأمل ولادة عيسى على غير الأسباب المألوفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص37، تحت عنوان «دلالة افتتاح القصة بفعل الذكر»","url":""}]},{"id":"s19-128","number":128,"surah":19,"verses":[16],"references":[{"surah":19,"verses":[16]}],"verseLabel":"مريم: 16","question":"ماذا أفاد تقييد ذكر مريم بقوله ﴿فِي الْكِتَابِ﴾؟","answer":"نبه إلى أن قصتها مذكورة في القرآن الكريم في مواضع متعددة؛ والمراد تلاوة خبرها القرآني المحفوظ، لا مجرد الحديث عنها في كلام آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص37، تحت عنوان «دلالة التعبير بشبه الجملة: ﴿فِي الْكِتَابِ﴾»","url":""}]},{"id":"s19-129","number":129,"surah":19,"verses":[16],"references":[{"surah":19,"verses":[16]}],"verseLabel":"مريم: 16","question":"لماذا قال ﴿وَاذْكُرْ فِي الْكِتَابِ مَرْيَمَ﴾، والمقصود ذكر قصتها؟","answer":"حُذف المضاف إيجازًا لظهور المراد؛ فالتقدير ذكر نبأ مريم أو قصتها، لأن المقصود تذكير السامع بشأنها وما وقع لها، لا ذكر ذاتها مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص38، تحت عنوان «بلاغة حذف المضاف في قوله: ﴿مَرْيَمَ﴾»","url":""}]},{"id":"s19-27","number":27,"surah":19,"verses":[16],"references":[{"surah":19,"verses":[16]}],"verseLabel":"مريم: 16","question":"ما دلالة وصف مكان اعتزال مريم بأنه ﴿شَرْقِيًّا﴾؟","answer":"يحدد الوصف جهة خلوتها، ويذكر المصدر مناسبة المشرق لطلوع الأنوار وإشارة ذلك إلى الروح الآتي إليها، وفيه بشارة وتمهيد لميلاد عيسى؛ فهو وجه بياني يذكره المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص41، تحت عنوان «دلالة وصف المكان بالشرقي»","url":""}]},{"id":"s19-130","number":130,"surah":19,"verses":[16],"references":[{"surah":19,"verses":[16]}],"verseLabel":"مريم: 16","question":"لماذا عُبّر عن اعتزال مريم أهلها بلفظ ﴿انْتَبَذَتْ﴾؟","answer":"الانتباذ يتضمن معنى الطرح والبعد؛ فيصور أنها تنحت عن مخالطة أهلها طلبًا للخلوة والانصراف إلى العبادة، فهو أبلغ في تصوير اعتزالها من مجرد ذكر البعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص39، تحت عنوان «سر التعبير بالانتباذ»","url":""}]},{"id":"s19-28","number":28,"surah":19,"verses":[17],"references":[{"surah":19,"verses":[17]}],"verseLabel":"مريم: 17","question":"ما سرّ التعبير بـ﴿فَاتَّخَذَتْ مِنْ دُونِهِمْ حِجَابًا﴾؟","answer":"دلّ الاتخاذ على اجتهادها في إحكام خلوتها؛ فلم تكتف بالاعتزال، بل نصبت حجابًا تستتر به. ويذكر المصدر أن هذه العزلة هيأتها لتلقي أمر ربها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص44–45، تحت عنوان «دلالة التعبير بالاتخاذ في قوله: ﴿فَاتَّخَذَتْ﴾»","url":""}]},{"id":"s19-29","number":29,"surah":19,"verses":[17],"references":[{"surah":19,"verses":[17]}],"verseLabel":"مريم: 17","question":"ما دلالة تمثل الروح لمريم ﴿بَشَرًا سَوِيًّا﴾؟","answer":"وُصف باعتدال الخلق وحسن الهيئة لتألفه العين وتتمكن مريم من سماع كلامه؛ فلو ظهر بصورته الملائكية لنفرت ولم تقدر على استماع رسالته. وفي هذا الظهور ابتلاء أظهر ورعها وعفافها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص50، تحت عنوان «دلالة وصفه بكونه: ﴿سَوِيًّا﴾»","url":""}]},{"id":"s19-30","number":30,"surah":19,"verses":[18],"references":[{"surah":19,"verses":[18]}],"verseLabel":"مريم: 18","question":"لماذا استعاذت مريم باسم ﴿الرَّحْمَنِ﴾ في مقام الخوف؟","answer":"استحضرت ما عهدته من رحمة الله وعطفه، واستجلبت آثار هذه الرحمة في دفع ما خافته؛ فاسم الرحمن يلائم رجاء الحماية واللطف.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص53–54، تحت عنوان «سر استعاذتها بصفة الرحمن»","url":""}]},{"id":"s19-131","number":131,"surah":19,"verses":[18],"references":[{"surah":19,"verses":[18]}],"verseLabel":"مريم: 18","question":"ما دلالة قول مريم ﴿إِنْ كُنْتَ تَقِيًّا﴾ لمن ظهر في خلوتها؟","answer":"استثارت تقواه وذكرته بالله؛ فمن كان يتقي الله كان له وازع يمنعه من التعرض لها. فالعبارة تستدعي الخشية في مقام احتماء المستجير.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص55، تحت عنوان «سر تخصيص الاستعاذة بالتقوى»","url":""}]},{"id":"s19-31","number":31,"surah":19,"verses":[19],"references":[{"surah":19,"verses":[19]}],"verseLabel":"مريم: 19","question":"ما سرّ وصف الغلام بـ﴿زَكِيًّا﴾؟","answer":"ليطمئنها أن الولد طاهر النفس مبارك، لا وصمة فيه رغم غرابة مولده.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص62، تحت «سر الوصف بقوله زكيًّا»","url":""}]},{"id":"s19-32","number":32,"surah":19,"verses":[20],"references":[{"surah":19,"verses":[20]}],"verseLabel":"مريم: 20","question":"ما دلالة قولها: ﴿وَلَمْ أَكُ بَغِيًّا﴾ بعد نفي مساس البشر؟","answer":"نفت الطريقين: الزواج المشروع والفاحشة، فاستحال الحمل بحسب الأسباب المعتادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص69، تحت عنوان «دلالة الواو في: ﴿وَلَمْ أَكُ بَغِيًّا﴾»","url":""}]},{"id":"s19-33","number":33,"surah":19,"verses":[21],"references":[{"surah":19,"verses":[21]}],"verseLabel":"مريم: 21","question":"لماذا وُصف عيسى بأنه ﴿آيَةً لِلنَّاسِ﴾؟","answer":"لأن خلقه من غير أب علامة على كمال قدرة الله على الخلق والبعث؛ فمن قدر على إيجاده بهذه الكيفية قدر على إحياء الموتى.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص80، تحت عنوان «دلالة التعبير بـ: ﴿آيَةً﴾»","url":""}]},{"id":"s19-132","number":132,"surah":19,"verses":[21],"references":[{"surah":19,"verses":[21]}],"verseLabel":"مريم: 21","question":"لماذا وُصف عيسى بأنه ﴿رَحْمَةً مِنَّا﴾؟","answer":"جعله الله رحمة للعباد بما يهتدون به من إرشاده؛ فهو هاد إلى الحق ودليل عليه، ومن اقتدى به واتبعه كان ذلك نجاة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص81، تحت عنوان «دلالة وصف عيسى بالرحمة»","url":""}]},{"id":"s19-34","number":34,"surah":19,"verses":[21],"references":[{"surah":19,"verses":[21]}],"verseLabel":"مريم: 21","question":"ما دلالة ختام البشارة بـ﴿وَكَانَ أَمْرًا مَقْضِيًّا﴾؟","answer":"جاءت الجملة مستأنفة لقطع المحاورة بعد بيان الغرض من خلق عيسى؛ فقد قُدّر الأمر وحُتم، فلا بد من وقوعه، مهما بدا مستبعدًا بحسب الأسباب.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص82، تحت عنوان «دلالة الواو في: ﴿وَكَانَ أَمْرًا مَقْضِيًّا﴾»","url":""}]},{"id":"s19-35","number":35,"surah":19,"verses":[22],"references":[{"surah":19,"verses":[22]}],"verseLabel":"مريم: 22","question":"ما دلالة تصوير انفراد مريم بحملها بقوله ﴿فَانْتَبَذَتْ بِهِ مَكَانًا قَصِيًّا﴾؟","answer":"الانتباذ بعدٌ مع انفراد؛ فقد تنحت إلى ناحية بعيدة عن أهلها اتقاء ما يعرضها له الحمل من القيل والقال. وفي اعتزالها وهي حامل تحتاج إلى المعونة تصوير لشدة معاناتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص86–87، تحت عنوان «سر التعبير بالانتباذ في: ﴿فَانْتَبَذَتْ﴾»","url":""}]},{"id":"s19-36","number":36,"surah":19,"verses":[23],"references":[{"surah":19,"verses":[23]}],"verseLabel":"مريم: 23","question":"ما دلالة ذكر ﴿جِذْعِ النَّخْلَةِ﴾ في مشهد المخاض؟","answer":"ألجأها المخاض إلى جذع النخلة لتستند إليه عند شدة الولادة، ثم خُص الجذع تمهيدًا للكرامة التي ظهرت بتساقط الرطب.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص94، تحت عنوان «سر تخصيص جذع النخلة»","url":""}]},{"id":"s19-37","number":37,"surah":19,"verses":[23],"references":[{"surah":19,"verses":[23]}],"verseLabel":"مريم: 23","question":"لماذا تمنت مريم الموت مع سبق بشارتها بالغلام الزكي؟","answer":"يذكر المصدر أنها استحيت من الناس وخافت اتهامهم، أو خافت وقوعهم في المعصية بما يقولونه عنها؛ فاشتداد الأمر وخوف التهمة هما باعث التمني المذكور في هذا التوجيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص96–97، تحت عنوان «سر تمني مريم الموت بعد بشارة جبريل لها»","url":""}]},{"id":"s19-133","number":133,"surah":19,"verses":[23],"references":[{"surah":19,"verses":[23]}],"verseLabel":"مريم: 23","question":"ماذا أضاف وصف ﴿مَنْسِيًّا﴾ بعد قول مريم ﴿نَسْيًا﴾؟","answer":"زاد في تصوير زوال الذكر؛ فالنسي ما شأنه أن ينسى، ثم وصفته بأنه منسي بالفعل، فكأنها تمنت ألا يبقى لها ذكر بين أهلها من شدة ما ألم بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص97، تحت عنوان «دلالة الوصف بـ: ﴿مَنْسِيًّا﴾»","url":""}]},{"id":"s19-38","number":38,"surah":19,"verses":[24],"references":[{"surah":19,"verses":[24]}],"verseLabel":"مريم: 24","question":"كيف تتصل عبارة ﴿مِنْ تَحْتِهَا﴾ بالخلاف فيمن نادى مريم؟","answer":"في قراءة كسر الميم تكون «مِن» حرف جر يحدد جهة النداء، ويُذكر للمنادي عيسى أو جبريل. وفي قراءة فتحها تكون «مَن» اسمًا لمن حصل تحتها، ويفسره المصدر بعيسى؛ فلا يلزم من كل وجه تعيين المنادي أو حمل العبارة وحدها على انفصال المولود.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص100، تحت عنوان «دلالة تعدد القراءات في: ﴿مِنْ تَحْتِهَا﴾»","url":""}]},{"id":"s19-134","number":134,"surah":19,"verses":[24],"references":[{"surah":19,"verses":[24]}],"verseLabel":"مريم: 24","question":"ماذا أفادت الفاء في ﴿فَنَادَاهَا﴾ عقب تمني مريم الموت؟","answer":"رتبت النداء على ما قالته، وأفادت مجيء التطمين على الفور بعد حزنها؛ فبادرها النداء بالتسلية وتطييب القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص99، تحت عنوان «دلالة الفاء في: ﴿فَنَادَاهَا﴾»","url":""}]},{"id":"s19-39","number":39,"surah":19,"verses":[24],"references":[{"surah":19,"verses":[24]}],"verseLabel":"مريم: 24","question":"ما المراد بـ﴿سَرِيًّا﴾ ولماذا اختير؟","answer":"السري قيل: جدول الماء الجاري تحتها، وقيل: عيسى، أي السيد الشريف؛ والقول الأول هو قول جمهور المفسرين في الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص98–99، تحت عنوان «شرح المفردات»","url":""}]},{"id":"s19-40","number":40,"surah":19,"verses":[25],"references":[{"surah":19,"verses":[25]}],"verseLabel":"مريم: 25","question":"ما دلالة أمر مريم بهز جذع النخلة مع قدرتـه تعالى على رزقها بلا هز؟","answer":"أمرها بهز الجذع، مع أن المعتاد أن هزه لا يُسقط الثمر؛ وفي تأكيد تعلق الهز به إظهار للكرامة بأدنى سبب. فكان منها فعل السبب المأمور به، وحصول الرزق بفضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص108، تحت عنوان «دلالة الباء في: ﴿بِجِذْعِ﴾»","url":""}]},{"id":"s19-41","number":41,"surah":19,"verses":[25],"references":[{"surah":19,"verses":[25]}],"verseLabel":"مريم: 25","question":"ما سرّ وصف الرطب بـ﴿جَنِيًّا﴾؟","answer":"أي قد طاب وصلح للاجتناء؛ فالوصف يدل على اكتمال نضجه وكمال الانتفاع به.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص111، تحت عنوان «دلالة التعبير بـ: ﴿جَنِيًّا﴾»","url":""}]},{"id":"s19-135","number":135,"surah":19,"verses":[25],"references":[{"surah":19,"verses":[25]}],"verseLabel":"مريم: 25","question":"لماذا ذُكر الرطب في رزق مريم دون التمر؟","answer":"لأن السياق سياق إكرام وتسلية، فناسبه الثمر في صورة تشتهيها النفس وتسر العين؛ ويذكر المصدر أن لين الرطب يناسب حالها بعد آلام المخاض.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص110–111، تحت عنوان «سر التعبير بـ: ﴿رُطَبًا﴾»","url":""}]},{"id":"s19-42","number":42,"surah":19,"verses":[26],"references":[{"surah":19,"verses":[26]}],"verseLabel":"مريم: 26","question":"ما دلالة الجمع لمريم بين ﴿فَكُلِي وَاشْرَبِي وَقَرِّي عَيْنًا﴾؟","answer":"جمعت الواو لها ما يقوي البدن ويريح النفس: الطعام والشراب وقرة العين، فشمل الإحسان ظاهرها وباطنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص115، تحت عنوان «دلالة العطف بالواو في: ﴿وَاشْرَبِي وَقَرِّي﴾»","url":""}]},{"id":"s19-136","number":136,"surah":19,"verses":[26],"references":[{"surah":19,"verses":[26]}],"verseLabel":"مريم: 26","question":"لماذا ذُكر الطعام والشراب قبل قرة العين في خطاب مريم؟","answer":"يذكر المصدر أن ترتيب التسلية ارتقى من تقوية البدن إلى طمأنينة النفس؛ فإذا تهيأت بالغذاء كان ذلك تمهيدًا لسكون القلب وراحة البال.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص115–116، تحت عنوان «سر تقديم دفع ضرر الجوع والعطش على دفع ضرر الخوف»","url":""}]},{"id":"s19-43","number":43,"surah":19,"verses":[26],"references":[{"surah":19,"verses":[26]}],"verseLabel":"مريم: 26","question":"ما دلالة تفسير نذر الصوم بقول مريم: ﴿فَلَنْ أُكَلِّمَ الْيَوْمَ إِنْسِيًّا﴾؟","answer":"الفاء للسببية؛ فامتناعها عن الكلام مترتب على نذرها. ويذكر المصدر أن إعراضها عن المجادلة يتيح أن يتكلم عنها المولود، وكلامه أقطع للحجة من كلام تقوله هي فيقبل الرد والجدال.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص120، تحت عنوان «معنى الفاء ودلالتها في: ﴿فَلَنْ﴾»","url":""}]},{"id":"s19-137","number":137,"surah":19,"verses":[26],"references":[{"surah":19,"verses":[26]}],"verseLabel":"مريم: 26","question":"كيف جُمِع بين أمر مريم أن تقول نذرها وصومها عن الكلام؟","answer":"ظاهر الأمر يبيح لها التلفظ بصيغة النذر، وهو قول الجمهور المذكور في المصدر. وقيل: المراد الإبلاغ بالإشارة لأن المنع يشمل الكلام، وقيل: أخّرت إعلان نذرها حتى أتت قومها؛ فهذه أوجه في كيفية إبلاغ النذر، لا في إباحة مجادلتهم بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص121–122، تحت عنوان «النهي عن الكلام بقول تقوله مريم»","url":""}]},{"id":"s19-44","number":44,"surah":19,"verses":[27],"references":[{"surah":19,"verses":[27]}],"verseLabel":"مريم: 27","question":"ما سرّ التعبير بـ﴿فَأَتَتْ بِهِ قَوْمَهَا تَحْمِلُهُ﴾؟","answer":"التصريح بحمله يرسم شجاعتها في مواجهة القوم بالآية نفسها بدل إخفائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص127–128، تحت عنوان «سر تقييد الفعل ﴿فَأَتَتْ﴾ بالجملة الحالية ﴿تَحْمِلُهُ﴾»","url":""}]},{"id":"s19-45","number":45,"surah":19,"verses":[27],"references":[{"surah":19,"verses":[27]}],"verseLabel":"مريم: 27","question":"ما دلالة وصف قوم مريم ما رأوه بـ﴿شَيْئًا فَرِيًّا﴾؟","answer":"وصفوا ما رأوه بأنه أمر عظيم منكر، و«فريًّا» تحتمل الشنيع المستنكر أو المفترى. فحكى التعبير شدة صدمتهم واستعظامهم، وما بنوه على ظاهر الحال من اتهام لمريم قبل ظهور براءتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص130، تحت عنوان «سر تقييد المفعول به بالصفة ﴿فَرِيًّا﴾»","url":""}]},{"id":"s19-46","number":46,"surah":19,"verses":[28],"references":[{"surah":19,"verses":[28]}],"verseLabel":"مريم: 28","question":"ما دلالة نداء مريم بـ﴿يَا أُخْتَ هَارُونَ﴾ في مقام اللوم؟","answer":"استدعوا بهذه الإضافة صورة الصلاح المعروفة في أهلها للمبالغة في لومها على ما توهموه؛ فكأنهم يبرزون التناقض بين نسبها الطاهر وما نسبوه إليها من فعل منكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص136، تحت عنوان «سر التعبير بالمنادى مضافًا: ﴿يَا أُخْتَ هَارُونَ﴾»","url":""}]},{"id":"s19-47","number":47,"surah":19,"verses":[29],"references":[{"surah":19,"verses":[29]}],"verseLabel":"مريم: 29","question":"ما دلالة اكتفاء مريم بالإشارة إلى عيسى عند مواجهة قومها؟","answer":"بادرت بالإشارة إلى عيسى فور تعييرهم لها، ليَنطق ببراءتها؛ ففي التعقيب بالفاء تصوير لسرعة ردها، ولكمال تهيئة الله لها واستعدادها لمواجهتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص143–144، تحت عنوان «معنى الفاء ودلالتها في ﴿فَأَشَارَتْ إِلَيْهِ﴾»","url":""}]},{"id":"s19-48","number":48,"surah":19,"verses":[30],"references":[{"surah":19,"verses":[30]}],"verseLabel":"مريم: 30","question":"ما دلالة افتتاح كلام عيسى بقوله: ﴿إِنِّي عَبْدُ اللَّهِ﴾؟","answer":"بدأ بـ﴿إني عبد الله﴾ لإثبات عبوديته لله من أول كلامه، وفي ذلك ردّ على من غلا فيه وادعى له الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص149، تحت عنوان «غرض التعبير بمقول القول جملة اسمية مؤكدة»","url":""}]},{"id":"s19-49","number":49,"surah":19,"verses":[30],"references":[{"surah":19,"verses":[30]}],"verseLabel":"مريم: 30","question":"ما سرّ التعبير بـ﴿آتَانِيَ الْكِتَابَ وَجَعَلَنِي نَبِيًّا﴾ بصيغة الماضي؟","answer":"لتحقق الوعد في علم الله حتى عُبر عن المستقبل كأنه وقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص150، تحت عنوان «دلالة التعبير بالماضي ﴿آتَانِي﴾»","url":""}]},{"id":"s19-50","number":50,"surah":19,"verses":[31],"references":[{"surah":19,"verses":[31]}],"verseLabel":"مريم: 31","question":"ما سرّ التعبير بـ﴿مُبَارَكًا أَيْنَ مَا كُنْتُ﴾؟","answer":"عمّم الشرط بركته في أي مكان يحل فيه، فمن جالسه أو التقى به ناله من نفعه؛ فليست بركته مقصورة على بقعة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص154، تحت عنوان «الغرض من التعبير بالشرط ﴿أَيْنَ مَا كُنْتُ﴾»","url":""}]},{"id":"s19-51","number":51,"surah":19,"verses":[31],"references":[{"surah":19,"verses":[31]}],"verseLabel":"مريم: 31","question":"ما دلالة تقييد الوصية بالصلاة والزكاة بـ﴿مَا دُمْتُ حَيًّا﴾؟","answer":"يدل القيد على ملازمته العبادة في حياته، ويشرح المصدر الاستغراق هنا بأنه عرفي يراد به الكثرة؛ فالوصية تعود إلى إقراره بالعبودية، وإيتاء الكتاب والنبوة ترقٍّ في هذه العبودية لا خروج منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص156–157، تحت عنوان «الغرض من التعبير بالقيد ﴿حَيًّا﴾»","url":""}]},{"id":"s19-52","number":52,"surah":19,"verses":[32],"references":[{"surah":19,"verses":[32]}],"verseLabel":"مريم: 32","question":"ما صلة قوله ﴿وَلَمْ يَجْعَلْنِي جَبَّارًا شَقِيًّا﴾ ببرّ عيسى بأمه؟","answer":"عطف نفي الجبروت يؤكد البر المذكور قبله؛ فالمعنى أنه متواضع خاضع لأمه، لا قاسيًا متكبرًا مضيعًا لحقها. وعُبر عما يدل عليه البر من حسن المعاملة بطريق نفي ضده.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص160–161، تحت عنوان «دلالة العطف»","url":""}]},{"id":"s19-138","number":138,"surah":19,"verses":[32],"references":[{"surah":19,"verses":[32]}],"verseLabel":"مريم: 32","question":"ما العلاقة بين وصف الجبار بالشقاء في كلام عيسى؟","answer":"الجبار متكبر متسلط غليظ في معاملة الناس، فيجلب لنفسه بغضهم وشقاءه بمعاداتهم، فضلًا عن سوء عاقبته في الآخرة. فنفي الجبروت يتصل بنفي ما يجره من الشقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص161، تحت عنوان «الغرض من تنكير المفعول الثاني ﴿جَبَّارًا﴾»","url":""}]},{"id":"s19-53","number":53,"surah":19,"verses":[33],"references":[{"surah":19,"verses":[33]}],"verseLabel":"مريم: 33","question":"ما سرّ تعبير عيسى بـ﴿وَالسَّلَامُ عَلَيَّ﴾؟","answer":"حكى عيسى ما جعله الله له من السلام والأمان في مواطن الولادة والموت والبعث. وقيل: اللام للعهد بسلام يحيى السابق، والأظهر عند المصدر أنها للجنس، مبالغة في تعلق السلام به.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص163، تحت عنوان «دلالة الواو واللام في ﴿وَالسَّلَامُ﴾»","url":""}]},{"id":"s19-54","number":54,"surah":19,"verses":[34],"references":[{"surah":19,"verses":[34]}],"verseLabel":"مريم: 34","question":"ما دلالة الاستئناف بقوله ﴿ذَلِكَ عِيسَى﴾ بعد كلامه؟","answer":"جاء اسم الإشارة لتمييز حقيقة عيسى وصفاته الصحيحة، ردًا على اختلاف اليهود والنصارى فيه؛ فكأن من وصفوه بغير صفته لا يعرفونه، فعُرّف لهم بحقيقته لتمييزها من الأوصاف الباطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص167، تحت عنوان «دلالة الاستئناف في ﴿ذَلِكَ عِيسَى﴾»","url":""}]},{"id":"s19-55","number":55,"surah":19,"verses":[34],"references":[{"surah":19,"verses":[34]}],"verseLabel":"مريم: 34","question":"ما سرّ وصف خبره بـ﴿قَوْلَ الْحَقِّ﴾؟","answer":"إضافة القول إلى الحق تؤكد صدقه وثبوته من كل جانب، في مقابلة امتراء المختلفين في عيسى ونسبهم إليه ما ليس من صفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص168، تحت عنوان «سر الإضافة في ﴿قَوْلَ الْحَقِّ﴾»","url":""}]},{"id":"s19-56","number":56,"surah":19,"verses":[35],"references":[{"surah":19,"verses":[35]}],"verseLabel":"مريم: 35","question":"ما دلالة نفي اتخاذ الولد عن الله بصيغة ﴿مَا كَانَ لِلَّهِ﴾؟","answer":"تفيد الصيغة أن اتخاذ الولد لا يليق بالله ولا يصح في حقه، فهي نفي بالغ قائم على منافاة ذلك لكمال الألوهية، لا مجرد إخبار بأنه لم يقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص173، تحت عنوان «دلالة التعبير بالكون المنفي بـ: ﴿مَا﴾»","url":""}]},{"id":"s19-139","number":139,"surah":19,"verses":[35],"references":[{"surah":19,"verses":[35]}],"verseLabel":"مريم: 35","question":"ما دلالة التعبير بالمصدر المؤول ﴿أَنْ يَتَّخِذَ﴾ في نفي الولد عن الله؟","answer":"يفيد نفي اتخاذه الولد في أي زمن من الأزمان؛ فينفي التعبير احتمال أن يتخذ سبحانه ولدًا في وقت ما. ويذكر المصدر أن المضارع ينزهه عن تجدد ما يفتقر معه إلى الولد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص173–174، تحت عنوان «إيثار التعبير بالمصدر المؤول ﴿أَنْ يَتَّخِذَ﴾»","url":""}]},{"id":"s19-57","number":57,"surah":19,"verses":[35],"references":[{"surah":19,"verses":[35]}],"verseLabel":"مريم: 35","question":"ما دلالة تعقيب نفي الولد بقوله: ﴿إِذَا قَضَى أَمْرًا فَإِنَّمَا يَقُولُ لَهُ كُنْ فَيَكُونُ﴾؟","answer":"ميلاد عيسى بلا أب أثر لكلمة القدرة، لا دليل بنوة؛ فالخالق لا يحتاج إلى التوالد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص176، تحت عنوان «الغرض من التعبير بجواب الشرط أسلوب قصر»","url":""}]},{"id":"s19-58","number":58,"surah":19,"verses":[36],"references":[{"surah":19,"verses":[36]}],"verseLabel":"مريم: 36","question":"ما سرّ التعبير بـ﴿هَذَا صِرَاطٌ مُسْتَقِيمٌ﴾ بعد الأمر بالعبادة؟","answer":"أشير بـ﴿هذا﴾ إلى توحيد الله وعبادته المذكورين قبله، وجُعلا صراطًا واضحًا مستقيمًا يوصل سالكه إلى الحق بلا اعوجاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص182، تحت عنوان «الغرض من التعبير بالمسند إليه اسم إشارة للقريب ﴿هَذَا﴾»","url":""}]},{"id":"s19-59","number":59,"surah":19,"verses":[37],"references":[{"surah":19,"verses":[37]}],"verseLabel":"مريم: 37","question":"ما سرّ التعبير هنا بـ﴿فَوَيْلٌ لِلَّذِينَ كَفَرُوا﴾، وفي الزخرف ﴿فَوَيْلٌ لِلَّذِينَ ظَلَمُوا﴾؟","answer":"فُصّلت قصة عيسى في مريم، وذُكرت فيها مقالة نسبة الولد إلى الله، فناسب وصف أصحابها بالكفر؛ وأُجملت في الزخرف فجيء بوصف الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص189–190، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s19-60","number":60,"surah":19,"verses":[39],"references":[{"surah":19,"verses":[39]}],"verseLabel":"مريم: 39","question":"ما دلالة تسمية يوم القيامة ﴿يَوْمَ الْحَسْرَةِ﴾؟","answer":"لكثرة ما يقع يوم الحساب من تحسر المجرمين على ما فرطوا فيه من أسباب النجاة؛ فكأن اليوم اختص بالحسرة لشدة ظهورها فيه. وهذا بالنسبة إليهم، وإن كان يوم فرح للصالحين.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص201، تحت عنوان «سر إضافة اليوم إلى ﴿الْحَسْرَةِ﴾»","url":""}]},{"id":"s19-61","number":61,"surah":19,"verses":[40],"references":[{"surah":19,"verses":[40]}],"verseLabel":"مريم: 40","question":"ما سرّ التعبير بـ﴿إِنَّا نَحْنُ نَرِثُ الْأَرْضَ وَمَنْ عَلَيْهَا﴾؟","answer":"صُدرت الجملة بـ«إنّ» لتأكيد فناء الدنيا بمخلوقاتها ورجوعها إلى خالقها؛ فجاء الخبر مؤكدًا في خطاب المشركين الذين ينكرون الجزاء، وفيه زجر عن الاغترار بما يزول.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص208، تحت عنوان «دلالة تصدير الجملة بحرف التأكيد»","url":""}]},{"id":"s19-62","number":62,"surah":19,"verses":[41],"references":[{"surah":19,"verses":[41]}],"verseLabel":"مريم: 41","question":"ما دلالة وصف إبراهيم بـ﴿صِدِّيقًا﴾؟","answer":"جاءت صيغة المبالغة «فعيل» للدلالة على شدة اتصافه بالصدق؛ فصدقه راسخ في القول والعمل والإذعان للحق، ومن شواهده تصديقه أمر ربه وامتثاله له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص217، تحت عنوان «إيثار صيغة المبالغة في ﴿صِدِّيقًا﴾»","url":""}]},{"id":"s19-140","number":140,"surah":19,"verses":[41],"references":[{"surah":19,"verses":[41]}],"verseLabel":"مريم: 41","question":"لماذا قُدّم وصف إبراهيم بالصديقية على وصفه بالنبوة؟","answer":"يذكر المصدر أن التقديم يدفع توهم حصر الصديقية في النبوة؛ فكل نبي صديق، وليس كل صديق نبيًا. ففي الانتقال إلى النبوة بيان لمرتبة أخص بعد إثبات كمال الصدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص218، تحت عنوان «نكتة وصف إبراهيم بالصديقية قبل النبوة»","url":""}]},{"id":"s19-63","number":63,"surah":19,"verses":[42,43,44,45],"references":[{"surah":19,"verses":[42,43,44,45]}],"verseLabel":"مريم: 42-45","question":"ما سر تكرار إبراهيم نداء ﴿يَا أَبَتِ﴾ في حججه لأبيه؟","answer":"ليغلف التصحيح العقدي بالبر واللطف، فلا يحول إنكار الباطل إلى قسوة على الوالد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص227، تحت عنوان «سر تكرار النداء ﴿يَا أَبَتِ﴾»","url":""}]},{"id":"s19-64","number":64,"surah":19,"verses":[42],"references":[{"surah":19,"verses":[42]}],"verseLabel":"مريم: 42","question":"ما سرّ التعبير بـ﴿لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ﴾؟","answer":"بدأ بأوضح تناقض حسي: المعبود العاجز عن الإدراك والنفع لا يستحق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص221، تحت عنوان «بلاغة الاستفهام في الآية»","url":""}]},{"id":"s19-65","number":65,"surah":19,"verses":[43],"references":[{"surah":19,"verses":[43]}],"verseLabel":"مريم: 43","question":"ما سرّ التعبير بـ﴿قَدْ جَاءَنِي مِنَ الْعِلْمِ مَا لَمْ يَأْتِكَ﴾؟","answer":"لم يدع إحاطة العلم، بل ذكر القدر الذي خصه الله به، فجمع الحجة والتواضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص227، 228، 229، تحت «معنى حرف الجر في الآية»","url":""}]},{"id":"s19-66","number":66,"surah":19,"verses":[43],"references":[{"surah":19,"verses":[43]}],"verseLabel":"مريم: 43","question":"ما سرّ وصف الطريق بـ﴿صِرَاطًا سَوِيًّا﴾؟","answer":"السوي مستوٍ لا عوج فيه، يناسب عرض الابن طريقًا مأمونًا لأبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص230، تحت عنوان «دلالة وصف الصراط بقوله: ﴿سَوِيًّا﴾»","url":""}]},{"id":"s19-67","number":67,"surah":19,"verses":[44],"references":[{"surah":19,"verses":[44]}],"verseLabel":"مريم: 44","question":"ما سرّ التعبير بـ﴿لَا تَعْبُدِ الشَّيْطَانَ﴾ مع أن أباه يعبد الأصنام؟","answer":"لأن طاعة وسوسته أفضت إلى عبادة الأصنام، فنُسبت العبادة إلى الشيطان باعتباره سببها. وفي ذلك كشف لقبح الانقياد له وراء التعلق بالأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص233–234، تحت عنوان «سر العدول عن (الأصنام) إلى ﴿الشَّيْطَانَ﴾»","url":""}]},{"id":"s19-68","number":68,"surah":19,"verses":[45],"references":[{"surah":19,"verses":[45]}],"verseLabel":"مريم: 45","question":"لماذا قال إبراهيم لأبيه ﴿أَنْ يَمَسَّكَ عَذَابٌ﴾ دون «يصيبك»؟","answer":"من التوجيهات التي يذكرها المصدر أن المس أقل تمكنًا من الإصابة، فاختير تلطفًا في الإنذار وتقليلًا لدرجة ما يخوفه منه، بما يلائم شفقته على أبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص242، تحت عنوان «نكتة إيثار الفعل ﴿يَمَسَّكَ﴾ دون (يصيبك)»","url":""}]},{"id":"s19-141","number":141,"surah":19,"verses":[45],"references":[{"surah":19,"verses":[45]}],"verseLabel":"مريم: 45","question":"ما دلالة تقييد العذاب بكونه ﴿مِنَ الرَّحْمَنِ﴾ في إنذار إبراهيم لأبيه؟","answer":"يذكر المصدر وجهين: أن العذاب لا ينافي الرحمة بل قد يكون رحمة بالعباد، وأن ذكر الرحمن يغلظ الإنذار؛ فإذا حل العذاب ممن شأنه الرحمة دل ذلك على فظاعة جرم المعذَّب. فاستحضار الرحمة لا يعني انتفاء العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص243، تحت عنوان «نكتة تقييد العذاب بكونه ﴿مِنَ الرَّحْمَنِ﴾»","url":""}]},{"id":"s19-142","number":142,"surah":19,"verses":[45],"references":[{"surah":19,"verses":[45]}],"verseLabel":"مريم: 45","question":"كيف أبقى قول إبراهيم لأبيه ﴿إِنِّي أَخَافُ﴾ باب الرجاء في نجاته؟","answer":"يحمل الأكثرون الخوف هنا على ظاهره، فلا يجزم إبراهيم بعذاب أبيه؛ فقد يؤمن فيكون من أهل الثواب. وفي هذا أدب مع الله وإبقاء للرجاء في نفس الأب ليتخلص من العذاب بترك عبادة الأوثان.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص241–242، تحت عنوان «توجيه معنى الفعل ﴿أَخَافُ﴾ في الآية»","url":""}]},{"id":"s19-69","number":69,"surah":19,"verses":[46],"references":[{"surah":19,"verses":[46]}],"verseLabel":"مريم: 46","question":"كيف قابل أبو إبراهيم لطف ابنه في دعوته؟","answer":"قابل اللطف والرفق بالفظاظة والتهديد؛ فتوعده بالرجم والهجر، وخاطبه باسمه «يا إبراهيم» بدل خطاب البنوة الذي يقابل «يا أبت». فتظهر شدة الجفاء في مقابلة لين الابن.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص252، تحت عنوان «تفاوت الأسلوب بين كلام إبراهيم وكلام أبيه»","url":""}]},{"id":"s19-143","number":143,"surah":19,"verses":[46],"references":[{"surah":19,"verses":[46]}],"verseLabel":"مريم: 46","question":"ما دلالة ﴿مَلِيًّا﴾ في أمر أبي إبراهيم ﴿وَاهْجُرْنِي مَلِيًّا﴾؟","answer":"معناها طويلًا، فتدل على هجر ممتد؛ ويذكر المصدر أنها قد تكون وصفًا لمصدر محذوف، أي هجرًا مليًا، أو لزمان محذوف، أي زمانًا طويلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص257، تحت عنوان «إعراب كلمة ﴿مَلِيًّا﴾ وتوجيهها»","url":""}]},{"id":"s19-70","number":70,"surah":19,"verses":[47],"references":[{"surah":19,"verses":[47]}],"verseLabel":"مريم: 47","question":"ما دلالة جواب إبراهيم لأبيه: ﴿سَلَامٌ عَلَيْكَ﴾؟","answer":"قابل التهديد بالأمان وترك المقابلة بالسوء؛ فالمعنى أنك سالم من أذاي. وفي ذلك لطف وبر حتى عند اختلاف الاعتقاد وشدة الجفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص261–262، تحت عنوان «نكتة التنكير في لفظ ﴿سَلَامٌ﴾»","url":""}]},{"id":"s19-71","number":71,"surah":19,"verses":[48],"references":[{"surah":19,"verses":[48]}],"verseLabel":"مريم: 48","question":"ما دلالة ﴿عَسَى﴾ في قول إبراهيم ﴿عَسَى أَلَّا أَكُونَ بِدُعَاءِ رَبِّي شَقِيًّا﴾؟","answer":"عبّر بالرجاء إظهارًا للتواضع وحسن الأدب؛ فالثواب والإجابة تفضل من الله، لا استحقاق يوجبه العبد على ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص271، تحت عنوان «دلالة ﴿عَسَى﴾ في الآية»","url":""}]},{"id":"s19-144","number":144,"surah":19,"verses":[48],"references":[{"surah":19,"verses":[48]}],"verseLabel":"مريم: 48","question":"لماذا عبّر إبراهيم برجاء نفي الشقاء بدل التصريح برجاء السعادة؟","answer":"في هذا العدول تعريض بأن قومه أشقياء بدعاء آلهتهم؛ فإعلان رجائه في عبادة ربه يتضمن إظهار خيبة عبادتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص271–272، تحت عنوان «سر العدول عن التصريح برجاء السعادة إلى نفي الشقاء»","url":""}]},{"id":"s19-72","number":72,"surah":19,"verses":[49],"references":[{"surah":19,"verses":[49]}],"verseLabel":"مريم: 49","question":"ما سرّ التعبير بـ﴿وَكُلًّا جَعَلْنَا نَبِيًّا﴾ بعد ذكر إسحاق ويعقوب؟","answer":"أكد أن الهبة لم تكن ذرية فحسب، بل امتداد نبوة ورسالة بعد الاعتزال لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص279، تحت عنوان «معنى الواو في قوله ﴿وَكُلًّا جَعَلْنَا﴾»","url":""}]},{"id":"s19-73","number":73,"surah":19,"verses":[50],"references":[{"surah":19,"verses":[50]}],"verseLabel":"مريم: 50","question":"ما وجه التعبير باللسان في قوله ﴿وَجَعَلْنَا لَهُمْ لِسَانَ صِدْقٍ﴾؟","answer":"أُريد باللسان الكلام والثناء الذي يصدر به؛ فذُكرت الآلة وأُريد ما يحصل بها، وهو مجاز يفسره المصدر بعلاقة السببية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص286–287، تحت عنوان «بلاغة المجاز في ذكر اللسان»","url":""}]},{"id":"s19-145","number":145,"surah":19,"verses":[50],"references":[{"surah":19,"verses":[50]}],"verseLabel":"مريم: 50","question":"ما دلالة وصف لسان الصدق بأنه ﴿عَلِيًّا﴾؟","answer":"يصوّر الوصف شرف الثناء وظهوره؛ فالعلو مستعار لعدم الخفاء، لأن ما علا وارتفع كان أبين وأظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص287، تحت عنوان «نكتة وصف اللسان بكونه ﴿عَلِيًّا﴾»","url":""}]},{"id":"s19-74","number":74,"surah":19,"verses":[51],"references":[{"surah":19,"verses":[51]}],"verseLabel":"مريم: 51","question":"ما الذي تفيده قراءتا ﴿مُخْلَصًا﴾ في وصف موسى؟","answer":"قراءة فتح اللام تفيد أن الله اصطفاه واجتباه، وقراءة كسرها تفيد إخلاصه لله في أعماله وأقواله. والمعنيان متلازمان في التوجيه المذكور: اصطفاه الله، وأخلص هو العبادة والعمل له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص292، تحت عنوان «إيثار التعبير بلفظ ﴿مُخْلَصًا﴾»","url":""}]},{"id":"s19-146","number":146,"surah":19,"verses":[51],"references":[{"surah":19,"verses":[51]}],"verseLabel":"مريم: 51","question":"لماذا جُمع لموسى الوصفان ﴿رَسُولًا نَبِيًّا﴾؟","answer":"جُمعا تأكيدًا لشرف وصفه وبيانًا لعظم أثر رسالته؛ ويوجه المصدر ذلك بأن الرسول بالمعنى الشرعي أخص من النبي، فيكون الجمع بينهما تنويهًا برسالته ونبوته معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص293، تحت عنوان «علة وصف موسى بكونه ﴿رَسُولًا نَبِيًّا﴾»","url":""}]},{"id":"s19-75","number":75,"surah":19,"verses":[52],"references":[{"surah":19,"verses":[52]}],"verseLabel":"مريم: 52","question":"ما سرّ التعبير بـ﴿وَقَرَّبْنَاهُ نَجِيًّا﴾؟","answer":"المناجاة خطاب خاص، والتقريب يبرز رفعة منزلة موسى وتشريفه بالكلام. ويشرح المصدر قربه بأنه قرب رتبة وإكرام، مصوّرًا بالقرب الذي يختص به المناجي.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص304، تحت عنوان «بلاغة الاستعارة في ﴿وَقَرَّبْنَاهُ نَجِيًّا﴾»","url":""}]},{"id":"s19-76","number":76,"surah":19,"verses":[53],"references":[{"surah":19,"verses":[53]}],"verseLabel":"مريم: 53","question":"لماذا عُبّر عن إشراك هارون مع موسى بلفظ الهبة؟","answer":"لأن إشراكه معه كان محض فضل من الله وعطاءً لا مقابل له ولا استحقاق؛ وفي لفظ الهبة تعظيم لهذه النعمة، إذ ضم الله أخاه إليه بالنبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص305، تحت عنوان «إيثار لفظ الهبة، دون غيره»","url":""}]},{"id":"s19-147","number":147,"surah":19,"verses":[53],"references":[{"surah":19,"verses":[53]}],"verseLabel":"مريم: 53","question":"ما دلالة اللام في ﴿وَوَهَبْنَا لَهُ﴾ عند ذكر هارون؟","answer":"اللام للاختصاص وللأجل؛ فهذه الهبة لأجل موسى لإعانته. ويذكر المصدر أنها، بخلاف النداء والتقريب السابقين، كانت بعد طلب وسؤال من موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص305–306، تحت عنوان «دلالة اللام في قوله: ﴿لَهُ﴾»","url":""}]},{"id":"s19-77","number":77,"surah":19,"verses":[54],"references":[{"surah":19,"verses":[54]}],"verseLabel":"مريم: 54","question":"لماذا خُصّ إسماعيل بوصف ﴿صَادِقَ الْوَعْدِ﴾؟","answer":"لكمال اشتهاره بهذه الصفة، فمدح بما غلب عليه من الوفاء. ويشمل ذلك وعده لله وللناس، ومنه وفاؤه لأبيه بما وعده من الصبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص314، تحت عنوان «سر إيثار صفة (صدق الوعد)»","url":""}]},{"id":"s19-148","number":148,"surah":19,"verses":[54],"references":[{"surah":19,"verses":[54]}],"verseLabel":"مريم: 54","question":"ما دلالة مجيء ﴿صَادِقَ﴾ اسم فاعل في وصف إسماعيل؟","answer":"يدل على رسوخ الصدق فيه حتى صار خُلُقًا ملازمًا له؛ فهو يزاول الوفاء بالوعد باستمرار، وليس وصفًا عارضًا في واقعة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص314–315، تحت عنوان «نكتة المجيء بالمسند اسم فاعل»","url":""}]},{"id":"s19-78","number":78,"surah":19,"verses":[55],"references":[{"surah":19,"verses":[55]}],"verseLabel":"مريم: 55","question":"لماذا خُصّ أهل إسماعيل بأمره بالصلاة في قوله ﴿وَكَانَ يَأْمُرُ أَهْلَهُ﴾؟","answer":"لشدة عنايته بإصلاح الأقربين؛ يبدأ المرء بتكميل نفسه ومن هو أقرب الناس إليه. ويذكر المصدر أن المراد قد يكون أهله خاصة، أو قومه باعتبارهم أهلًا له، فالمقصود إبراز العناية بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص316–317، تحت عنوان «نكتة اختصاص المفعول ﴿أَهْلَهُ﴾»","url":""}]},{"id":"s19-79","number":79,"surah":19,"verses":[57],"references":[{"surah":19,"verses":[57]}],"verseLabel":"مريم: 57","question":"ما دلالة قوله في إدريس: ﴿وَرَفَعْنَاهُ مَكَانًا عَلِيًّا﴾؟","answer":"ورد في رفع إدريس قولان مشهوران: رفع المنزلة والذكر، ورفع المكان حقيقة؛ فإطلاق ﴿مكانًا عليًا﴾ يحتمل رفعة القدر ورفعة المكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص328، تحت عنوان «بلاغة الاستعارة في: ﴿وَرَفَعْنَاهُ مَكَانًا﴾»","url":""}]},{"id":"s19-80","number":80,"surah":19,"verses":[58],"references":[{"surah":19,"verses":[58]}],"verseLabel":"مريم: 58","question":"ما سرّ التعبير بـ﴿خَرُّوا سُجَّدًا وَبُكِيًّا﴾؟","answer":"جمع التعبير بين الخضوع الظاهر وخشوع القلب؛ فالسجود يصور وضع الجباه، و«بكيًّا» تدل على التأثر الباطن، فتتكامل هيئة الجسد وحال القلب عند تلاوة الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص343، تحت عنوان «سر إيثار صيغة ﴿سُجَّدًا﴾»","url":""}]},{"id":"s19-81","number":81,"surah":19,"verses":[59],"references":[{"surah":19,"verses":[59]}],"verseLabel":"مريم: 59","question":"ما دلالة اقتران إضاعة الصلاة باتباع الشهوات؟","answer":"جاء اتباع الشهوات عقب إضاعة الصلاة؛ لأن تضييع أعظم الصلات بالله يفتح طريق الانقياد للشهوات، فجمع النص أصل التفريط وأثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص352، 353، 354، تحت «دلالة العطف»","url":""}]},{"id":"s19-82","number":82,"surah":19,"verses":[59],"references":[{"surah":19,"verses":[59]}],"verseLabel":"مريم: 59","question":"ما دلالة التعبير بـ﴿غَيًّا﴾ في وعيد من أضاعوا الصلاة واتبعوا الشهوات؟","answer":"يرد الغي بمعنى الضلال والخيبة؛ وهو هنا وعيد بعاقبة سيئة تنفر منها النفوس، تقابل ما طلبوه من لذة الشهوات.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص356، تحت عنوان «سر إيثار التعبير بالغيّ، ودلالة تنكيره»","url":""}]},{"id":"s19-149","number":149,"surah":19,"verses":[59],"references":[{"surah":19,"verses":[59]}],"verseLabel":"مريم: 59","question":"لماذا عُبّر عن جزاء مضيعي الصلاة ومتّبعي الشهوات بقوله ﴿يَلْقَوْنَ﴾؟","answer":"يصور اللقاء موافاتهم الجزاء الذي استحقوه بأعمالهم؛ فكأن العاقبة تأتيهم ويلتقون بها بعد أن غفلوا عنها وانشغلوا بلذة الشهوات.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص355، تحت عنوان «سر التعبير بالفعل ﴿يَلْقَوْنَ﴾»","url":""}]},{"id":"s19-83","number":83,"surah":19,"verses":[60],"references":[{"surah":19,"verses":[60]},{"surah":25,"verses":[70]}],"verseLabel":"مريم: 60؛ الفرقان: 70","question":"ما سرّ التعبير في الفرقان بـ﴿وَعَمِلَ عَمَلًا صَالِحًا﴾، وفي مريم بـ﴿وَعَمِلَ صَالِحًا﴾؟","answer":"في مريم اكتُفي بالوصف «صالحًا» دون التصريح بموصوفه. أما في الفرقان فذُكر «عملًا» مع فعله تأكيدًا لضرورة سعي التائب في الأعمال الصالحة المخالفة لسيئاته السابقة؛ فاجتماع الفعل ومصدره يقوي التوكيد ويلائم مقام التوبة منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج38، ص238، تحت عنوان «نكتة التعبير بالمفعول ﴿عَمَلًا﴾»","url":""}]},{"id":"s19-84","number":84,"surah":19,"verses":[61],"references":[{"surah":19,"verses":[61]}],"verseLabel":"مريم: 61","question":"ما دلالة وصف الجنات بأنها مما وعد الرحمن عباده ﴿بِالْغَيْبِ﴾؟","answer":"وُعدوا بجنات لم يروها؛ فآمنوا بالغيب اعتمادًا على وعد الله. وفي القيد تنويه بصدق إيمانهم واختبار لهم بما غاب عن مشاهدتهم، مع كون الجنات مهيأة لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص370–371، تحت عنوان «فائدة التقييد بشبه الجملة في: ﴿بِالْغَيْبِ﴾»","url":""}]},{"id":"s19-85","number":85,"surah":19,"verses":[61],"references":[{"surah":19,"verses":[61]}],"verseLabel":"مريم: 61","question":"ما سرّ التعبير بـ﴿إِنَّهُ كَانَ وَعْدُهُ مَأْتِيًّا﴾ لا «آتيا»؟","answer":"صوّر الوعد كأنه مقصد يأتيه أهله ويصلون إليه، مبالغة في تحقق الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص372–373، تحت عنوان «دلالة صيغة اسم المفعول ﴿مَأْتِيًّا﴾ دون غيرها»","url":""}]},{"id":"s19-86","number":86,"surah":19,"verses":[62],"references":[{"surah":19,"verses":[62]}],"verseLabel":"مريم: 62","question":"ما دلالة الاستثناء في ﴿لَا يَسْمَعُونَ فِيهَا لَغْوًا إِلَّا سَلَامًا﴾؟","answer":"يرجح المصدر الاستثناء المنقطع: لا يسمعون لغوًا، لكن يسمعون سلامًا؛ فالسلام ليس من اللغو. ويذكر وجه الاتصال بتفسير اللغو بمطلق الكلام، فيكون ما يسمعونه سلامًا. والمقصود تنزيه خطاب أهل الجنة عن الكلام المؤذي والباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص374–375، تحت عنوان «معنى الاستثناء ودلالته»","url":""}]},{"id":"s19-87","number":87,"surah":19,"verses":[63],"references":[{"surah":19,"verses":[63]}],"verseLabel":"مريم: 63","question":"لماذا أُشير إلى الجنة باسم الإشارة للبعيد في ﴿تِلْكَ الْجَنَّةُ﴾؟","answer":"للإيذان بعلو مرتبتها وبُعد منزلتها في الشرف؛ فالبعد هنا يعظم شأن الجنة وما أعد الله فيها لعباده.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص379، تحت عنوان «نكتة التعبير باسم الإشارة للبعيد»","url":""}]},{"id":"s19-88","number":88,"surah":19,"verses":[64],"references":[{"surah":19,"verses":[64]}],"verseLabel":"مريم: 64","question":"ما دلالة قول الملائكة: ﴿وَمَا نَتَنَزَّلُ إِلَّا بِأَمْرِ رَبِّكَ﴾؟","answer":"تنفي استقلالها بالنزول وترد تأخر الوحي أو مجيئه إلى تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص387، تحت عنوان «معنى الاستثناء ودلالته»","url":""}]},{"id":"s19-89","number":89,"surah":19,"verses":[65],"references":[{"surah":19,"verses":[65]}],"verseLabel":"مريم: 65","question":"ما سرّ التعبير بـ﴿هَلْ تَعْلَمُ لَهُ سَمِيًّا﴾؟","answer":"ينفي أن يكون لله نظير يماثله أو يستحق أن يُعبد معه. ويذكر المصدر أيضًا تفسير السمي بالمشارك في الاسم المختص به، كاسم «الله»؛ فالمقصود تقرير تفرده واستحقاقه العبادة، لا جعل مجرد الاشتراك في لفظ صفة مماثلةً له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص401–402، تحت عنوان «سر التعبير بـ﴿سَمِيًّا﴾ دون غيرها»","url":""}]},{"id":"s19-90","number":90,"surah":19,"verses":[66],"references":[{"surah":19,"verses":[66]}],"verseLabel":"مريم: 66","question":"لماذا جاء زمن الموت بعد همزة الاستفهام في إنكار البعث: ﴿أَإِذَا مَا مِتُّ﴾؟","answer":"لأن موضع استبعاده هو وقوع الحياة بعد الموت؛ فتقديم الظرف بعد همزة الإنكار يسلط الإنكار على هذا الوقت الذي يتوهم أن الإحياء بعده محال.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص406، تحت عنوان «سر إيلاء الظرف همزة الاستفهام في ﴿أَإِذَا﴾»","url":""}]},{"id":"s19-150","number":150,"surah":19,"verses":[66],"references":[{"surah":19,"verses":[66]}],"verseLabel":"مريم: 66","question":"لماذا اقترنت ﴿سَوْفَ﴾ باللام في حكاية إنكار البعث: ﴿لَسَوْفَ أُخْرَجُ حَيًّا﴾؟","answer":"حُكي وعد البعث مؤكدًا باللام كما يسمعه المنكر من الرسول والمؤمنين، ثم أُدخل عليه الإنكار؛ فالتأكيد في الكلام المحكي لا يدل على إقرار المنكر بالبعث، بل يبرز جحوده للوعد المؤكد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص407، تحت عنوان «دلالة اقتران سوف باللام»","url":""}]},{"id":"s19-91","number":91,"surah":19,"verses":[67],"references":[{"surah":19,"verses":[67]}],"verseLabel":"مريم: 67","question":"ما دلالة الاحتجاج على منكر البعث بأنه خُلق من قبل ﴿وَلَمْ يَكُ شَيْئًا﴾؟","answer":"ذكّره بخلقه الأول من العدم ليبطل استبعاد الإعادة؛ فالذي أوجده ولم يكن شيئًا لا يعجز عن بعثه. والاحتجاج يرد المنكر إلى أصل وجوده الذي يغفل عن دلالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص412–413، تحت عنوان «موقع جملة ﴿وَلَمْ يَكُ شَيْئًا﴾ ودلالته»","url":""}]},{"id":"s19-92","number":92,"surah":19,"verses":[68],"references":[{"surah":19,"verses":[68]}],"verseLabel":"مريم: 68","question":"ما دلالة جمع الكافرين مع الشياطين في الحشر؟","answer":"يجمع الحشر بين المشركين والشياطين الذين أغووهم، فتظهر الصلة بين إضلال الشياطين واتباع الكافرين لهم. ويذكر المصدر في الواو العطف، ويجيز معنى المصاحبة، بما يزيد تصوير مهانتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص417–418، تحت عنوان «دلالة الواو في قوله: ﴿وَالشَّيَاطِينَ﴾»","url":""}]},{"id":"s19-93","number":93,"surah":19,"verses":[68],"references":[{"surah":19,"verses":[68]}],"verseLabel":"مريم: 68","question":"ما سرّ التعبير بـ﴿ثُمَّ لَنُحْضِرَنَّهُمْ حَوْلَ جَهَنَّمَ جِثِيًّا﴾؟","answer":"«جثيا» على الركب تصور ذلهم وعجزهم وهم ينتظرون الحكم حول النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص419، تحت عنوان «سر التقييد بالحال ﴿جِثِيًّا﴾»","url":""}]},{"id":"s19-94","number":94,"surah":19,"verses":[69],"references":[{"surah":19,"verses":[69]}],"verseLabel":"مريم: 69","question":"ما دلالة التفضيل بـ﴿أَشَدُّ﴾ في نزع أهل العتو من كل شيعة؟","answer":"يدل على تمييز الأشد عصيانًا وتمردًا من كل طائفة؛ فليس أهل العتو سواءً، ويختص الأشد منهم بشدة العذاب، مع اشتراكهم في أصل الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص425–426، تحت عنوان «دلالة التعبير بالتفضيل ﴿أَشَدُّ﴾»","url":""}]},{"id":"s19-95","number":95,"surah":19,"verses":[71],"references":[{"surah":19,"verses":[71]}],"verseLabel":"مريم: 71","question":"ما سرّ التعبير بـ﴿وَإِنْ مِنْكُمْ إِلَّا وَارِدُهَا﴾؟","answer":"التعبير باسم الفاعل يدل على ثبوت الورود واستقراره، ثم تختلف العاقبة: فإما نجاة وحسن مصير، وإما بقاء وسوء مصير. فيقرر حتمية المشهد ويبعث على الخوف من عاقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص435، تحت عنوان «سر التعبير باسم الفاعل ﴿وَارِدُهَا﴾»","url":""}]},{"id":"s19-96","number":96,"surah":19,"verses":[72],"references":[{"surah":19,"verses":[72]}],"verseLabel":"مريم: 72","question":"ما سرّ التعبير بـ﴿وَنَذَرُ الظَّالِمِينَ فِيهَا جِثِيًّا﴾؟","answer":"تصور إعادة الجثو بقاء الظالمين في النار جاثين على ركبهم عاجزين عن الحركة من شدة الهول؛ أما الجثو السابق حول جهنم فكان في مقام الإحضار وانتظار الحساب. فلكل موضع ما يزيد تصوير المهانة والذل.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص443، تحت عنوان «سر إعادة لفظ ﴿جِثِيًّا﴾»","url":""}]},{"id":"s19-97","number":97,"surah":19,"verses":[73],"references":[{"surah":19,"verses":[73]}],"verseLabel":"مريم: 73","question":"ما دلالة تفاخر الكافرين بـ﴿خَيْرٌ مَقَامًا وَأَحْسَنُ نَدِيًّا﴾؟","answer":"جمعوا التفاخر بحسن المقام وحسن المجلس، يتوهمون أن ما لهم من سعة المعيشة وزينة المجالس يدل على أفضليتهم. وفي حكاية قولهم كشف لنظرتهم القاصرة وتهكمهم بفقراء المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص450، تحت عنوان «دلالة العطف بالواو: ﴿وَأَحْسَنُ نَدِيًّا﴾»","url":""}]},{"id":"s19-98","number":98,"surah":19,"verses":[74],"references":[{"surah":19,"verses":[74]}],"verseLabel":"مريم: 74","question":"لماذا قُدّم ﴿أَثَاثًا﴾ على ﴿رِئْيًا﴾ في وصف متاع الأمم السابقة؟","answer":"الأثاث متاع البيت، والرئي الزينة والمنظر الحسن. قُدّم المتاع لأنه أعم وأغلب، ثم عُطف عليه حسن المنظر الذي يقوم به؛ فرتب الأصل وما يتبعه من الزينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص457، تحت عنوان «غرض تقديم ﴿أَثَاثًا﴾ على ﴿وَرِئْيًا﴾»","url":""}]},{"id":"s19-99","number":99,"surah":19,"verses":[75],"references":[{"surah":19,"verses":[75]}],"verseLabel":"مريم: 75","question":"ما دلالة صيغة الأمر في ﴿فَلْيَمْدُدْ لَهُ الرَّحْمَنُ مَدًّا﴾؟","answer":"استُعمل الأمر في معنى تحقيق الخبر والتهديد: سيمد له في الإمهال حتى يعاين العاقبة. ويذكر المصدر وجه الدعاء بطول الإمهال؛ وفي الحالين لا تكون الصيغة وعدًا بالرضا، بل وعيدًا للمستمر في ضلاله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص464، تحت عنوان «دلالة اللام في ﴿فَلْيَمْدُدْ﴾»","url":""}]},{"id":"s19-100","number":100,"surah":19,"verses":[76],"references":[{"surah":19,"verses":[76]}],"verseLabel":"مريم: 76","question":"ما دلالة وصف الباقيات الصالحات بأنها ﴿خَيْرٌ ثَوَابًا وَخَيْرٌ مَرَدًّا﴾؟","answer":"تكرار «خير» يزيد بيان أفضلية ثواب الصالحات وعاقبتها وتأكيدها. وفي مقابلة أهلها بالكافرين تهكم بعاقبة الكفر وتحسير لأصحابه على مفاخرتهم بزينة الدنيا؛ فحسن المآل للعمل الصالح، لا لما اغتروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص477، تحت عنوان «وجه عقد مفاضلة بين النقيضين وتأكيده بالتكرير»","url":""}]},{"id":"s19-101","number":101,"surah":19,"verses":[77],"references":[{"surah":19,"verses":[77]}],"verseLabel":"مريم: 77","question":"ما سرّ التعبير بـ﴿أَفَرَأَيْتَ الَّذِي كَفَرَ بِآيَاتِنَا﴾؟","answer":"الاستفهام يعجب من جرأته على الجمع بين الكفر والقطع بأنه سيؤتى مالًا وولدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص483، تحت عنوان «سر إيثار التعريف بالاسم الموصول»","url":""}]},{"id":"s19-102","number":102,"surah":19,"verses":[78],"references":[{"surah":19,"verses":[78]}],"verseLabel":"مريم: 78","question":"ما دلالة الاستفهام في ﴿أَطَّلَعَ الْغَيْبَ أَمِ اتَّخَذَ عِنْدَ الرَّحْمَنِ عَهْدًا﴾؟","answer":"حصر مستند دعواه في علم الغيب أو عهد من الله، وكلاهما معدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص491، تحت عنوان «بلاغة حصر أقسام المعرفة»","url":""}]},{"id":"s19-103","number":103,"surah":19,"verses":[79],"references":[{"surah":19,"verses":[79]}],"verseLabel":"مريم: 79","question":"ما دلالة المضارع في ﴿سَنَكْتُبُ مَا يَقُولُ﴾؟","answer":"يدل على استمرار إثبات قوله عليه ما دام قوله مستمرًا؛ فما تلفظ به محفوظ، ويظهر له ويحاسب عليه، فلا يضيع بتجدد الزمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص495، تحت عنوان «دلالة التعبير بالمضارع ﴿سَنَكْتُبُ﴾»","url":""}]},{"id":"s19-151","number":151,"surah":19,"verses":[79],"references":[{"surah":19,"verses":[79]}],"verseLabel":"مريم: 79","question":"كيف قابل قوله ﴿وَنَمُدُّ لَهُ مِنَ الْعَذَابِ مَدًّا﴾ زعم الكافر أنه سيؤتى مالًا وولدًا؟","answer":"قوبل ما ادعاه من الإمداد بالمال والولد بإمداده بالعذاب وزيادته؛ فكان الجزاء موافقًا لجرأته في دعواه. وإسناد المد إلى ضمير العظمة يزيد الوعيد تفخيمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص498، تحت عنوان «بلاغة إسناد فعل (المدّ) إلى نون العظمة»","url":""}]},{"id":"s19-104","number":104,"surah":19,"verses":[80],"references":[{"surah":19,"verses":[80]}],"verseLabel":"مريم: 80","question":"ما دلالة الجمع بين ﴿وَنَرِثُهُ مَا يَقُولُ﴾ و﴿وَيَأْتِينَا فَرْدًا﴾؟","answer":"عُطف إتيانه منفردًا على نزع ما ادعاه من المال والولد؛ فيأتي يوم القيامة معزولًا عما ظنه عزًا وقوة، لا يملك شيئًا مما زعم أنه سيؤتاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص502–503، تحت عنوان «معنى الواو في جملة ﴿وَيَأْتِينَا فَرْدًا﴾»","url":""}]},{"id":"s19-105","number":105,"surah":19,"verses":[81,82],"references":[{"surah":19,"verses":[81,82]}],"verseLabel":"مريم: 81-82","question":"ما دلالة انقلاب ما طلبوه من الآلهة ﴿عِزًّا﴾ إلى ﴿ضِدًّا﴾؟","answer":"يؤول ما رجوا به الرفعة والمنعة إلى الذلة والصغار؛ فالتعبير بالضد كناية عن انقلاب حالهم إلى خلاف ما كانوا يؤملونه من العز.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص518، تحت عنوان «بلاغة الكناية عن الصفة»","url":""}]},{"id":"s19-152","number":152,"surah":19,"verses":[81,82],"references":[{"surah":19,"verses":[81,82]}],"verseLabel":"مريم: 81-82","question":"إلى من يعود الضمير في ﴿سَيَكْفُرُونَ بِعِبَادَتِهِمْ وَيَكُونُونَ عَلَيْهِمْ ضِدًّا﴾؟","answer":"يذكر المصدر وجهين: عوده إلى المعبودين، فيتبرؤون من عبادة المشركين لهم، وعوده إلى العابدين، فينكرون أنهم عبدوا تلك الآلهة. ويعرض الوجهين باعتبار ما يحتمله السياق، دون حصره في أحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص515، تحت عنوان «مرجع الضمير في ﴿سَيَكْفُرُونَ﴾، وفي ﴿بِعِبَادَتِهِمْ﴾، وفي ﴿وَيَكُونُونَ﴾»","url":""}]},{"id":"s19-106","number":106,"surah":19,"verses":[83],"references":[{"surah":19,"verses":[83]}],"verseLabel":"مريم: 83","question":"ما سرّ التعبير بـ﴿تَؤُزُّهُمْ أَزًّا﴾؟","answer":"يصور المضارع تجدد إزعاج الشياطين لهم وتهييجهم إلى المعاصي مرة بعد أخرى؛ فكلما فتروا عاودتهم الإثارة، فيستمر دفعهم إلى الشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص532، تحت عنوان «دلالة التعبير بالمضارع ﴿تَؤُزُّهُمْ﴾»","url":""}]},{"id":"s19-107","number":107,"surah":19,"verses":[84],"references":[{"surah":19,"verses":[84]}],"verseLabel":"مريم: 84","question":"ما سرّ التعبير بـ﴿إِنَّمَا نَعُدُّ لَهُمْ عَدًّا﴾؟","answer":"يؤكد المصدر «عدًّا» إحصاء أنفاسهم وأعمارهم وأعمالهم حتى يستوفوا آجالهم، من غير زيادة ولا نقص؛ فليس تأخير عقوبتهم نسيانًا لهم، إذ لا يخفى على الله شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص538، تحت عنوان «نكتة القيد بالمفعول المطلق ﴿عَدًّا﴾»","url":""}]},{"id":"s19-108","number":108,"surah":19,"verses":[85,86],"references":[{"surah":19,"verses":[85,86]}],"verseLabel":"مريم: 85-86","question":"ما دلالة حشر المتقين ﴿وَفْدًا﴾ وسوق المجرمين ﴿وِرْدًا﴾؟","answer":"تقابل الآيتان بين وفادة المتقين على الرحمن في كرامة، وسوق المجرمين إلى النار في إهانة؛ فالسوق يشعر بالإكراه، ويصورهم كالأنعام العطاش التي تساق إلى الماء، فإذا مصيرهم جهنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص543، تحت عنوان «نكتة إيثار الفعل ﴿وَنَسُوقُ﴾»","url":""}]},{"id":"s19-109","number":109,"surah":19,"verses":[87],"references":[{"surah":19,"verses":[87]}],"verseLabel":"مريم: 87","question":"ما دلالة تقييد الشفاعة باتخاذ ﴿عِنْدَ الرَّحْمَنِ عَهْدًا﴾؟","answer":"قيدت الشفاعة بالعهد عند الرحمن؛ أي بالإيمان والتوحيد وما يأذن الله به، فنفى أن تملكها الآلهة أو تنال بمجرد الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص548، تحت عنوان «بلاغة تقييد الاتخاذ بالعندية»","url":""}]},{"id":"s19-110","number":110,"surah":19,"verses":[88],"references":[{"surah":19,"verses":[88]}],"verseLabel":"مريم: 88","question":"ما دلالة مجيء حكاية ﴿اتَّخَذَ الرَّحْمَنُ وَلَدًا﴾ بعد حكاية اتخاذ الآلهة؟","answer":"عُطفت حكاية دعوى الولد على حكاية اتخاذ الآلهة تتميمًا لعرض أقوالهم الباطلة؛ فالجنايتان تشتركان في الضلالة، وجاءت الثانية بعد جناية عبادة الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص554–555، تحت عنوان «بلاغة عطف القصة على القصة»","url":""}]},{"id":"s19-111","number":111,"surah":19,"verses":[89],"references":[{"surah":19,"verses":[89]}],"verseLabel":"مريم: 89","question":"ما سرّ وصف قولهم بالولد بـ﴿شَيْئًا إِدًّا﴾؟","answer":"الإد الأمر الفظيع المنكر الذي يثقل سماعه، فناسب أثره الكوني في الآيات التالية.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص561، تحت عنوان «بلاغة الوصف بـ﴿إِدًّا﴾»","url":""}]},{"id":"s19-112","number":112,"surah":19,"verses":[90],"references":[{"surah":19,"verses":[90]}],"verseLabel":"مريم: 90","question":"ما دلالة تصوير السماوات تكاد تتفطر والأرض تنشق والجبال تخر عند دعوى الولد؟","answer":"يصور المشهد عظم هذه المقالة وشناعتها؛ فكأن السماوات والأرض والجبال لا تقوى على حملها وتوشك أن تتصدع من هولها. وفي فعل المقاربة تهويل للقول وتنفير من الاستهانة به، من غير أن يدل على وقوع هذا التداعي بالفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص562، تحت عنوان «بلاغة التعبير بفعل المقاربة (كاد)»","url":""}]},{"id":"s19-113","number":113,"surah":19,"verses":[92],"references":[{"surah":19,"verses":[92]}],"verseLabel":"مريم: 92","question":"ما دلالة نفي الانبغاء في ﴿وَمَا يَنْبَغِي لِلرَّحْمَنِ أَنْ يَتَّخِذَ وَلَدًا﴾؟","answer":"يدل على استحالة اتخاذ الولد في حق الله، لا مجرد نفي وقوعه؛ فالولد يشبه أباه ويحتاج إليه، والله منزّه عن الحاجة والمماثلة، ومخلوقاته عباد له لا تشاركه ألوهيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص574–575، تحت عنوان «بلاغة نفي الانبغاء»","url":""}]},{"id":"s19-153","number":153,"surah":19,"verses":[92],"references":[{"surah":19,"verses":[92]}],"verseLabel":"مريم: 92","question":"لماذا أُظهر اسم ﴿الرَّحْمَنِ﴾ في نفي اتخاذ الولد بدل الاكتفاء بالضمير؟","answer":"فيه إشعار بعلة الحكم: كل موجود سواه مفتقر إلى رحمته، إما نعمة أو منعَم عليه، والجميع عباده. فلا يجانس المخلوق خالقه حتى يتوهم اتخاذه ولدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص575–576، تحت عنوان «بلاغة وضع الظاهر موضع المضمر»","url":""}]},{"id":"s19-114","number":114,"surah":19,"verses":[93],"references":[{"surah":19,"verses":[93]}],"verseLabel":"مريم: 93","question":"ما سرّ التعبير بـ﴿إِلَّا آتِي الرَّحْمَنِ عَبْدًا﴾؟","answer":"يقرر وصف العبودية خضوع الجميع لله وعدم استقلالهم عنه بشيء؛ حتى من نُسبت إليهم البنوة يأتونه عبادًا، فلا تثبت لهم ألوهية ولا بنوة كما زعم المبطلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص578، تحت عنوان «بلاغة التعبير بمفردة ﴿عَبْدًا﴾»","url":""}]},{"id":"s19-115","number":115,"surah":19,"verses":[94],"references":[{"surah":19,"verses":[94]}],"verseLabel":"مريم: 94","question":"ما دلالة الجمع بين ﴿أَحْصَاهُمْ وَعَدَّهُمْ عَدًّا﴾؟","answer":"العد سرد الأشياء واحدًا بعد آخر، أما الإحصاء فيشمل العد مع الحصر والضبط والحفظ. فالجمع بينهما يقرر إحاطةً لا يفوتها شيء، وليس مجرد معرفة عدد إجمالي.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص583، تحت عنوان «الإحصاء والعدّ»","url":""}]},{"id":"s19-116","number":116,"surah":19,"verses":[95],"references":[{"surah":19,"verses":[95]}],"verseLabel":"مريم: 95","question":"ما سرّ التعبير بـ﴿وَكُلُّهُمْ آتِيهِ يَوْمَ الْقِيَامَةِ فَرْدًا﴾؟","answer":"يأتي كل إنسان يوم القيامة منفردًا، لا ينفعه ما اغتر به من أعوان أو أنصار أو مال أو ولد؛ فلا يملك لنفسه نفعًا، فضلًا عن أن يحميه غيره مما يستحقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص582، تحت عنوان «دلالة القيد بالحال ﴿فَرْدًا﴾»","url":""}]},{"id":"s19-117","number":117,"surah":19,"verses":[96],"references":[{"surah":19,"verses":[96]}],"verseLabel":"مريم: 96","question":"ما دلالة اختيار لفظ ﴿وُدًّا﴾ في وعد المؤمنين؟","answer":"يجمع الود المحبة والألفة والقبول والطمأنينة في المعاملة والصحبة؛ فلا يقتصر على الميل الباطن، بل يتصل بحسن الصلة والخلو من إرادة المكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص590، تحت عنوان «نكتة التعبير بلفظ ﴿وُدًّا﴾»","url":""}]},{"id":"s19-154","number":154,"surah":19,"verses":[96],"references":[{"surah":19,"verses":[96]}],"verseLabel":"مريم: 96","question":"لماذا اختير اسم ﴿الرَّحْمَنُ﴾ في وعد المؤمنين بأن يجعل لهم ودًّا؟","answer":"للإيذان بأن جعل الود لهم أثر من آثار رحمته؛ وفي الاسم تذكير بعظم هذه النعمة ومصدرها، وهو ملائم لما غلب على السورة من ذكر الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص590، تحت عنوان «إيثار التعبير بصفة الرحمن»","url":""}]},{"id":"s19-118","number":118,"surah":19,"verses":[97],"references":[{"surah":19,"verses":[97]}],"verseLabel":"مريم: 97","question":"ما دلالة حذف متعلق التيسير في ﴿فَإِنَّمَا يَسَّرْنَاهُ بِلِسَانِكَ﴾؟","answer":"يفيد عموم التيسير: تيسير قراءة القرآن وذكره والنطق به بالعربية، وتبليغه وفهمه وحفظه؛ ليبشر الرسول به المتقين وينذر المعاندين. فلا يقتصر التيسير على وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص595، تحت عنوان «فائدة حذف متعلّق الفعل ﴿يَسَّرْنَاهُ﴾»","url":""}]},{"id":"s19-119","number":119,"surah":19,"verses":[98],"references":[{"surah":19,"verses":[98]}],"verseLabel":"مريم: 98","question":"ما دلالة ختام السورة بـ﴿هَلْ تُحِسُّ مِنْهُمْ مِنْ أَحَدٍ أَوْ تَسْمَعُ لَهُمْ رِكْزًا﴾؟","answer":"جمع نفي رؤيتهم ونفي سماع صوتهم الخفي كناية عن استئصالهم وهلاكهم؛ فانتفاء ما يدل على وجودهم يصور زوالهم الكامل بعد قوتهم وتجبرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص610، تحت عنوان «بلاغة الكناية في الآية»","url":""}]},{"id":"s20-1","number":1,"surah":20,"verses":[1],"references":[{"surah":20,"verses":[1]}],"verseLabel":"طه: 1","question":"ما دلالة افتتاح السورة بـ﴿طه﴾، وهل يُجزم بأنها اسم للنبي؟","answer":"يذكر المصدر أن جمهور المفسرين يعدون «طه» من الحروف المقطعة، ويرجح هذا القول. ويورد أقوالًا أخرى في تفسيرها؛ لذلك لا يصح الجزم من هذا الموضع بأنها اسم للنبي أو نداء له.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص625، تحت «شرح المفردات»، المدخل (1): ﴿طه﴾","url":""}]},{"id":"s20-2","number":2,"surah":20,"verses":[2],"references":[{"surah":20,"verses":[2]}],"verseLabel":"طه: 2","question":"ما سرّ التعبير بـ﴿مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَى﴾؟","answer":"لم ينزل القرآن ليكون سببًا لشقاء الرسول؛ وإنما يجتهد في تبليغه والتذكير به والعبادة دون أن يبلغ بنفسه حد الشقاء. وما يلحقه من جهد في ذلك لا يجعل الوحي عَنتًا، بل هو سبب سعادته وسعادة من اهتدى به.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص631، تحت عنوان «فائدة الجملة الخبرية في الآية»","url":""}]},{"id":"s20-3","number":3,"surah":20,"verses":[3],"references":[{"surah":20,"verses":[3]}],"verseLabel":"طه: 3","question":"ما نكتة اختيار لفظ ﴿تَذْكِرَةً﴾ في مطلع سورة طه؟","answer":"التذكرة ترد الشيء إلى الذهن بعد نسيانه وتديم حفظه؛ فالقرآن يوقظ ما استقر في الفطرة من التوحيد، ويزيل ما عرض لها من الغفلة والشرك، ويذكر بملة إبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص633، تحت عنوان «نكتة التعبير بلفظ ﴿تَذْكِرَةً﴾»","url":""}]},{"id":"s20-141","number":141,"surah":20,"verses":[3],"references":[{"surah":20,"verses":[3]}],"verseLabel":"طه: 3","question":"ما وجها الاستثناء في ﴿مَا أَنْزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَى إِلَّا تَذْكِرَةً لِمَنْ يَخْشَى﴾؟","answer":"يذكر المصدر وجهين: استثناء مفرغ من أعم أحوال إنزال القرآن، بتقدير «ما أنزلناه إلا تذكرة»، فيفيد القصر؛ واستثناء منقطع، لأن التذكرة ليست من جنس الشقاء، أي: لكن أنزلناه تذكرة لمن يخشى، فلا يفيد القصر على هذا الوجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص632، تحت عنوان «معنى الاستثناء في ﴿إِلَّا﴾»","url":""}]},{"id":"s20-4","number":4,"surah":20,"verses":[4],"references":[{"surah":20,"verses":[4]}],"verseLabel":"طه: 4","question":"ما دلالة نسبة تنزيل القرآن إلى ﴿مِمَّنْ خَلَقَ الْأَرْضَ وَالسَّمَاوَاتِ الْعُلَا﴾؟","answer":"تعظم صلة الموصول منزّل القرآن بذكر خلق الأرض والسماوات؛ فمن أنزل هذا الكتاب هو صاحب العظمة والقدرة، وفي ذلك إشعار بنصره رسوله وتأييده في التبليغ، وإلزام بإفراده بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص640، تحت عنوان «بلاغة التعبير في قوله: ﴿مِمَّنْ خَلَقَ﴾»","url":""}]},{"id":"s20-142","number":142,"surah":20,"verses":[4],"references":[{"surah":20,"verses":[4]}],"verseLabel":"طه: 4","question":"ما نكتة وصف السماوات بـ﴿الْعُلَا﴾ في مطلع سورة طه؟","answer":"هو وصف كاشف يؤكد ضخامة السماوات وعلوها، ويزيد تقرير عظمة خالقها وقدرته. وفي مقابلتها بالأرض إشعار بشرف العالم العلوي، مع مراعاة فواصل الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص643، تحت عنوان «نكتة وصف السماوات بـ﴿الْعُلَا﴾»","url":""}]},{"id":"s20-5","number":5,"surah":20,"verses":[5],"references":[{"surah":20,"verses":[5]}],"verseLabel":"طه: 5","question":"ما مناسبة اسم ﴿الرَّحْمَنُ﴾ في ﴿الرَّحْمَنُ عَلَى الْعَرْشِ اسْتَوَى﴾؟","answer":"يفيد أن خلق الأرض والسماوات وما يتصل بتدبير الملك جارٍ برحمة الله؛ ففي اختيار الاسم جمع بين عظمة الملك وشمول الرحمة ومصالح الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص645، تحت عنوان «نكتة التعبير بوصف الرحمن دون غيره»","url":""}]},{"id":"s20-6","number":6,"surah":20,"verses":[6],"references":[{"surah":20,"verses":[6]}],"verseLabel":"طه: 6","question":"ما دلالة الجمع بين ﴿مَا فِي السَّمَاوَاتِ﴾ و﴿مَا تَحْتَ الثَّرَى﴾؟","answer":"كرر «ما» لبيان شمول ملك الله لكل شيء، مع اختلاف أجناس المخلوقات في السماوات والأرض وبينهما وتحت الثرى؛ فلا يخرج شيء من ظاهر الكون أو خفيه عن ملكه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص650، تحت عنوان «نكتة تتابع التعبير بـ(ما) في الآية»","url":""}]},{"id":"s20-7","number":7,"surah":20,"verses":[7],"references":[{"surah":20,"verses":[7]}],"verseLabel":"طه: 7","question":"ما دلالة الجمع بين ﴿السِّرَّ وَأَخْفَى﴾ في بيان علم الله؟","answer":"اسم التفضيل يبين أن وراء السر ما هو أشد خفاء، وحذف المفضل عليه يعمم كل ما هو أخفى من السر. فيشمل علم الله حديث النفس وما لم يخطر بالبال مما يكون لاحقًا؛ فلا تقف إحاطته عند ما يسره الإنسان بلسانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص659، تحت عنوان «نكتة التعبير باسم التفضيل ﴿وَأَخْفَى﴾»","url":""}]},{"id":"s20-8","number":8,"surah":20,"verses":[8],"references":[{"surah":20,"verses":[8]}],"verseLabel":"طه: 8","question":"ما سرّ التعبير بـ﴿لَهُ الْأَسْمَاءُ الْحُسْنَى﴾؟","answer":"تقديم «له» يفيد اختصاص الله بالأسماء الحسنى على وجه الكمال؛ فقد يشترك غيره في مجرد الاسم، لكن حقيقة معناه لا تبلغ في المخلوق كمالها الذي يختص به الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص664، تحت عنوان «بلاغة التقديم في قوله: ﴿لَهُ الْأَسْمَاءُ الْحُسْنَى﴾»","url":""}]},{"id":"s20-9","number":9,"surah":20,"verses":[9],"references":[{"surah":20,"verses":[9]}],"verseLabel":"طه: 9","question":"ما دلالة الاستفهام في ﴿وَهَلْ أَتَاكَ حَدِيثُ مُوسَى﴾ في سورة طه؟","answer":"ليس طلبًا لجواب، بل يقرر الخبر ويشوق إلى سماعه وينبه إلى عظم شأنه؛ فيتهيأ السامع للإصغاء إلى القصة والاعتبار بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص669–670، تحت عنوان «بلاغة الاستفهام المجازي في الآية»","url":""}]},{"id":"s20-10","number":10,"surah":20,"verses":[10],"references":[{"surah":20,"verses":[10]}],"verseLabel":"طه: 10","question":"ما سرّ التعبير في قول موسى بـ﴿آنَسْتُ نَارًا﴾ لا «رأيت»؟","answer":"الإيناس هنا رؤية بينة لا شبهة فيها، ومعها شعور بالأنس والسكون إلى النار في وحشة الليل وشدة البرد؛ لذلك اتصل بها رجاؤه أن يجد قبسًا أو دلالة على الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص675–676، تحت عنوان «نكتة العدول إلى لفظ ﴿آنَسْتُ﴾»","url":""}]},{"id":"s20-11","number":11,"surah":20,"verses":[10],"references":[{"surah":20,"verses":[10]}],"verseLabel":"طه: 10","question":"لماذا قُدّم القبس في قول موسى في طه، وقُدّم الخبر في النمل والقصص؟","answer":"في طه يناسب تقديم القبس حال موسى وأهله في السفر والبرد، رجاء الانتفاع بالنار. وفي النمل قُدم الخبر، وهو المطلوب الأعم، إذ لم يتقدم ذكر مشقة السفر؛ وفي القصص ناسبه ما سبق من حديث موسى ورحلته وأخبارها. فلكل ترتيب مناسبته في سياق السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص682، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s20-143","number":143,"surah":20,"verses":[10],"references":[{"surah":20,"verses":[10]}],"verseLabel":"طه: 10","question":"ما المراد بـ﴿هُدًى﴾ في قول موسى: ﴿أَوْ أَجِدُ عَلَى النَّارِ هُدًى﴾؟","answer":"يتسع الهدى لما يدل على الطريق: طريق أو مرشد أو علامة؛ فموسى يرجو ما يخرجه من ضلال الطريق. ويذكر المصدر احتمال إرادة شخص هادٍ، مع ترجيح المعنى الأعم الذي يشمل وجوه الدلالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص679، تحت عنوان «نكتة التعبير بلفظ ﴿هُدًى﴾ وتنكيرها»","url":""}]},{"id":"s20-144","number":144,"surah":20,"verses":[10],"references":[{"surah":20,"verses":[10]}],"verseLabel":"طه: 10","question":"ما الفرق بين «قبس» في طه و«شهاب قبس» في النمل و«جذوة» في القصص؟","answer":"القبس أعم: جزء يؤخذ من النار للانتفاع به، والجذوة قطعة من الحطب فيها نار، والشهاب لهب النار. فذكر الشهاب والجذوة يلائم التصريح بالاصطلاء في النمل والقصص، وذكر القبس في طه يلائم مطلق الانتفاع دون التصريح بالاصطلاء؛ فلا تتعارض هذه الأوصاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص681، تحت عنوان «توجيه المتشابه اللفظي»","url":""}]},{"id":"s20-12","number":12,"surah":20,"verses":[11],"references":[{"surah":20,"verses":[11]}],"verseLabel":"طه: 11","question":"ما معنى الفاء في ﴿فَلَمَّا أَتَاهَا نُودِيَ يَا مُوسَى﴾؟","answer":"تفيد الترتيب والتعقيب: مضى موسى إلى النار عقب إخبار أهله بعزمه على ذلك، وتعقيب كل شيء بحسب وقته وحاله، فلا يلزم منه نفي زمن السير.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص687، تحت عنوان «معنى الفاء في قوله ﴿فَلَمَّا﴾»","url":""}]},{"id":"s20-145","number":145,"surah":20,"verses":[11],"references":[{"surah":20,"verses":[11]}],"verseLabel":"طه: 11","question":"ما دلالة ﴿لَمَّا﴾ في ﴿فَلَمَّا أَتَاهَا نُودِيَ يَا مُوسَى﴾؟","answer":"تربط النداء بوقت إتيانه النار؛ فبعد أن سار إليها بلغ الموضع المبارك، فكان النداء عند وصوله تكريمًا وتشريفًا. وقد أوجز السياق بحذف ذكر السير المفهوم مما قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص687، تحت عنوان «بلاغة التعبير بـ﴿فَلَمَّا﴾»","url":""}]},{"id":"s20-146","number":146,"surah":20,"verses":[11],"references":[{"surah":20,"verses":[11]}],"verseLabel":"طه: 11","question":"ما نكتة بناء ﴿نُودِيَ﴾ لما لم يسم فاعله في قصة موسى بطه؟","answer":"إبهام المنادي يشوق إلى معرفته، ثم يأتي ﴿إِنِّي أَنَا رَبُّكَ﴾ فيتمكن العلم به في النفس. ويصور التعبير حال موسى حين سمع النداء قبل أن يعرف مناديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص687–688، تحت عنوان «نكتة بناء الفعل ﴿نُودِيَ﴾»","url":""}]},{"id":"s20-13","number":13,"surah":20,"verses":[12],"references":[{"surah":20,"verses":[12]}],"verseLabel":"طه: 12","question":"ما دلالة أمر موسى بخلع نعليه في الوادي المقدس؟","answer":"يشرح المصدر خلع النعلين بأنه تعظيم للموضع الذي يسمع فيه موسى كلام الله، وإظهار للخضوع والتواضع. وتعقيب الأمر بقوله «إنك بالواد المقدس طوى» يبين مناسبة الخلع لبركة المكان وتقديسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص690، تحت عنوان «دلالة التعبير بالفعل ﴿فَاخْلَعْ﴾»","url":""}]},{"id":"s20-14","number":14,"surah":20,"verses":[12],"references":[{"surah":20,"verses":[12]},{"surah":79,"verses":[16]}],"verseLabel":"طه: 12؛ النازعات: 16","question":"ما دلالة وصف الوادي الذي نودي فيه موسى بـ﴿الْمُقَدَّسِ﴾؟","answer":"يدل الوصف على أنه موضع مطهر مبارك مشرف؛ وقد ازداد تشريفًا بوقوع النداء والتكليم والوحي فيه. وصيغة «المقدس» تؤكد غاية التطهير والمبالغة فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج65، ص778، تحت عنوان «نكتة وصف الوادي بالمقدس»","url":""}]},{"id":"s20-147","number":147,"surah":20,"verses":[12],"references":[{"surah":20,"verses":[12]},{"surah":79,"verses":[16]}],"verseLabel":"طه: 12؛ النازعات: 16","question":"ما المراد بـ﴿طُوًى﴾ في وصف الوادي الذي نودي فيه موسى؟","answer":"هو اسم الوادي على قول جمهور المفسرين؛ فذكره بعد «الواد المقدس» يعيّن الموضع ويوضحه. ويذكر المصدر أقوالًا أخرى، فلا تعرض التسمية باعتبارها القول الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص691–692، تحت عنوان «دلالة التعبير بـ﴿طُوًى﴾»","url":""}]},{"id":"s20-15","number":15,"surah":20,"verses":[13],"references":[{"surah":20,"verses":[13]}],"verseLabel":"طه: 13","question":"ما دلالة تقديم ﴿أَنَا﴾ على الفعل في ﴿وَأَنَا اخْتَرْتُكَ﴾؟","answer":"يقوي الإخبار باختيار الله موسى ويثبت قلبه؛ لأن غرابة هذا الخبر والمناجاة قد تعرض النفس للشك. فالمقصود تقوية الحكم ودفع الشك، لا إفادة التخصيص في هذا الموضع.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص694، تحت عنوان «دلالة تقديم المسند إليه على المسند الفعلي في ﴿وَأَنَا اخْتَرْتُكَ﴾»","url":""}]},{"id":"s20-148","number":148,"surah":20,"verses":[13],"references":[{"surah":20,"verses":[13]}],"verseLabel":"طه: 13","question":"ما دلالة الفاء في ﴿فَاسْتَمِعْ لِمَا يُوحَى﴾ بعد ﴿وَأَنَا اخْتَرْتُكَ﴾؟","answer":"ترتب الأمر بالاستماع على الاختيار؛ فمن أثر اختيار موسى أن يتلقى ما يوحيه الله إليه ويصغي له. فالفاء تصل الاصطفاء بمقتضاه من تلقي الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص696، تحت عنوان «معنى الفاء ودلالتها في ﴿فَاسْتَمِعْ﴾»","url":""}]},{"id":"s20-16","number":16,"surah":20,"verses":[14],"references":[{"surah":20,"verses":[14]}],"verseLabel":"طه: 14","question":"ما دلالة توالي المؤكدات في ﴿إِنَّنِي أَنَا اللَّهُ لَا إِلَهَ إِلَّا أَنَا﴾؟","answer":"تقوي المؤكدات الخبر وتدفع ما قد يعرض للنفس من الشك عند غرابة المناجاة؛ فيعلم موسى أن المتكلم هو الله. ويقرر النفي والاستثناء انفراده بالألوهية، فتثبت المعرفة التي ينبني عليها الأمر بالعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص703، تحت عنوان «بلاغة توالي المؤكدات في الآية الكريمة»","url":""}]},{"id":"s20-17","number":17,"surah":20,"verses":[14],"references":[{"surah":20,"verses":[14]}],"verseLabel":"طه: 14","question":"ما سرّ التعبير بـ﴿وَأَقِمِ الصَّلَاةَ لِذِكْرِي﴾؟","answer":"على وجه التعليل، المعنى: أقم الصلاة لأجل ذكري؛ فإنها تذكر العبد بخالقه وتشعره بأنه واقف بين يديه للمناجاة. فالأمر بإقامتها يربط الذكر بالعبادة العملية التي يتحقق فيها كماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص710–711، تحت عنوان «معنى اللام ودلالتها في ﴿لِذِكْرِي﴾»","url":""}]},{"id":"s20-18","number":18,"surah":20,"verses":[15],"references":[{"surah":20,"verses":[15]}],"verseLabel":"طه: 15","question":"ما سرّ التعبير عن الساعة بـ﴿أَكَادُ أُخْفِيهَا﴾؟","answer":"يعرض المصدر العبارة على أسلوب العرب في المبالغة في كتمان السر، كقولهم «أخفيته من نفسي»، أي بلغ إخفاؤه الغاية. والمقصود إخفاء وقت الساعة مع القطع بإتيانها؛ ليبقى الناس على حذر واستعداد، لا أن شيئًا يخفى على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص718، تحت عنوان «دلالة التعبير بالمضارع في قوله: ﴿أَكَادُ﴾»","url":""}]},{"id":"s20-19","number":19,"surah":20,"verses":[16],"references":[{"surah":20,"verses":[16]}],"verseLabel":"طه: 16","question":"ما سرّ التعبير بـ﴿فَلَا يَصُدَّنَّكَ عَنْهَا مَنْ لَا يُؤْمِنُ بِهَا﴾؟","answer":"جاء النهي في ظاهره عن صد الكافر موسى عن الساعة، وهو في معناه نهي لموسى عن الانصراف عنها وعن أسباب ذلك. فالنهي عن السبب ومباديه مبالغة في لزوم الإيمان والعمل والاستعداد، وأكد الفعل بنون التوكيد الثقيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص725–726، تحت عنوان «دلالة النهي في قوله: ﴿فَلَا يَصُدَّنَّكَ﴾»","url":""}]},{"id":"s20-20","number":20,"surah":20,"verses":[17],"references":[{"surah":20,"verses":[17]}],"verseLabel":"طه: 17","question":"ما دلالة سؤال الله موسى: ﴿وَمَا تِلْكَ بِيَمِينِكَ﴾ مع علمه بها؟","answer":"هو استفهام تقريري يثبت في نفس موسى أن ما يمسكه عصاه المألوفة، حتى إذا انقلبت حية تيقن أنها العصا نفسها. وفي استمرار المكالمة طمأنة لقلبه وإيناس له في مقام الإصغاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص735، تحت عنوان «بلاغة الاستفهام ﴿وَمَا﴾»","url":""}]},{"id":"s20-21","number":21,"surah":20,"verses":[18],"references":[{"surah":20,"verses":[18]}],"verseLabel":"طه: 18","question":"ما دلالة بسط موسى جوابه وذكر منافع العصا في مقام المناجاة؟","answer":"بسط موسى الجواب وذكر المسند إليه مع إمكان الاستغناء عنه؛ لما وجده من لذة المناجاة، فاغتنم مقام الخطاب وأطال الجواب بما يلائم الأدب. كما أجاب بما يوضح مقصوده من اتخاذ العصا ومنافعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص737، تحت عنوان «نكتة التعبير بالضمير المنفصل ﴿هِيَ﴾»","url":""}]},{"id":"s20-22","number":22,"surah":20,"verses":[18],"references":[{"surah":20,"verses":[18]}],"verseLabel":"طه: 18","question":"ما دلالة لفظ ﴿أَهُشُّ﴾ في قول موسى: ﴿وَأَهُشُّ بِهَا عَلَى غَنَمِي﴾؟","answer":"الهش هنا خبط أغصان الشجر بالعصا ليسقط ورقها فتأكله الغنم. وفي اللفظ معنى اللين والرفق، فيصور عناية موسى بغنمه ولطفه بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص741، تحت عنوان «دلالة التعبير ﴿وَأَهُشُّ﴾»","url":""}]},{"id":"s20-149","number":149,"surah":20,"verses":[18],"references":[{"surah":20,"verses":[18]}],"verseLabel":"طه: 18","question":"ما دلالة المضارع في ﴿أَتَوَكَّأُ عَلَيْهَا وَأَهُشُّ بِهَا عَلَى غَنَمِي﴾؟","answer":"يفيد التجدد والتكرر؛ فالاتكاء في المشي ورعاية الغنم وإطعامها أعمال تتكرر، واستخدام العصا فيها مستمر. فجاء المضارع مناسبًا لهذه المنافع المتجددة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص740، تحت عنوان «دلالة التعبير بالمضارع في قوله: ﴿وَأَهُشُّ﴾ و: ﴿أَتَوَكَّأُ﴾»","url":""}]},{"id":"s20-23","number":23,"surah":20,"verses":[20],"references":[{"surah":20,"verses":[20]}],"verseLabel":"طه: 20","question":"ما دلالة وصف العصا بعد تحولها بأنها ﴿حَيَّةٌ تَسْعَى﴾؟","answer":"وصفها بالسعي يثبت أنها حية كاملة الحياة والحركة، وليست صورة جامدة ولا تخييلًا. والمضارع يستحضر حركتها المتجددة كأن السامع يراها الآن، فيتأكد انقلاب العصا حقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص751، تحت عنوان «نكتة التعبير بالمضارع ﴿تَسْعَى﴾ بعد الماضي ﴿فَأَلْقَاهَا﴾»","url":""}]},{"id":"s20-24","number":24,"surah":20,"verses":[21],"references":[{"surah":20,"verses":[21]}],"verseLabel":"طه: 21","question":"ما دلالة تعدية ﴿سَنُعِيدُهَا سِيرَتَهَا الْأُولَى﴾ دون ذكر «إلى»؟","answer":"إفضاء الفعل مباشرة إلى مفعوله، دون «إلى سيرتها»، يصور تحقق العودة سريعًا بلا مهلة؛ فكما انقلبت العصا حية تُرد إلى هيئتها المألوفة عصًا. وفي ذلك بيان لقدرة الله على الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص754، تحت عنوان «نكتة تعدية الفعل بنفسه دون تعديته بالحرف (إلى)»","url":""}]},{"id":"s20-25","number":25,"surah":20,"verses":[22],"references":[{"surah":20,"verses":[22]}],"verseLabel":"طه: 22","question":"ما سرّ وصف اليد بأنها تخرج ﴿بَيْضَاءَ مِنْ غَيْرِ سُوءٍ﴾؟","answer":"لو اقتصر على «بيضاء» لأمكن توهم البرص أو عيب في اليد؛ فجاء «من غير سوء» لينفي ذلك ويبين أن البياض آية خارقة للعادة، لا مرضًا ولا عيبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص764، تحت عنوان «نكتة الإطناب بالاحتراس في قوله: ﴿مِنْ غَيْرِ سُوءٍ﴾»","url":""}]},{"id":"s20-26","number":26,"surah":20,"verses":[23],"references":[{"surah":20,"verses":[23]}],"verseLabel":"طه: 23","question":"ما سرّ التعبير بـ﴿لِنُرِيَكَ مِنْ آيَاتِنَا الْكُبْرَى﴾؟","answer":"علل إظهار العصا واليد بإراءة موسى بعض آيات الله الكبرى أولًا؛ ليعلم قدرته ويقوى قلبه قبل مناظرة فرعون. فالمعجزتان تهيئة له لما سيظهره بعد ذلك في مقام التحدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص767، تحت عنوان «معنى اللام ودلالتها في ﴿لِنُرِيَكَ﴾»","url":""}]},{"id":"s20-27","number":27,"surah":20,"verses":[24],"references":[{"surah":20,"verses":[24]}],"verseLabel":"طه: 24","question":"ما وجه تعليل الأمر بالذهاب إلى فرعون بقوله: ﴿إِنَّهُ طَغَى﴾؟","answer":"الجملة جواب عن سؤال مقدر: لماذا أذهب إلى فرعون؟ فقد تجاوز حد الكفر والتجبر حتى ادعى الربوبية، فكان طغيانه علة لإرساله إليه بالدعوة والإنذار. وفي بيان ذلك تهيئة لموسى لما يلقاه من صعوبة المهمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص773، تحت عنوان «علة فصل قوله: ﴿إِنَّهُ طَغَى﴾ عن سابقه»","url":""}]},{"id":"s20-28","number":28,"surah":20,"verses":[25],"references":[{"surah":20,"verses":[25]}],"verseLabel":"طه: 25","question":"ما دلالة بدء موسى دعاءه بـ﴿رَبِّ اشْرَحْ لِي صَدْرِي﴾؟","answer":"قدم طلب شرح الصدر ليزول من نفسه ما يعوق الإقدام على المهمة، ويتسع قلبه لتحمل أعباء الرسالة وأذى الناس بحلم وصبر؛ فتهيئة النفس تسبق ما طلبه من أسباب حسن التبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص779، تحت عنوان «سر تقديم سؤال الشرح على غيره مما سُئل»","url":""}]},{"id":"s20-29","number":29,"surah":20,"verses":[26],"references":[{"surah":20,"verses":[26]}],"verseLabel":"طه: 26","question":"ما دلالة طلب موسى ﴿وَيَسِّرْ لِي أَمْرِي﴾ عقب تكليفه بالرسالة؟","answer":"الأمر هنا دعاء يظهر افتقار موسى إلى الله وتضرعه؛ طلب أن يسهل عليه القيام بأعباء الرسالة وتحمل واجباتها، فالمطلوب الإعانة على أداء ما كلف به.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص781، تحت عنوان «الغرض من التعبير بفعل الأمر: ﴿وَيَسِّرْ﴾»","url":""}]},{"id":"s20-30","number":30,"surah":20,"verses":[27,28],"references":[{"surah":20,"verses":[27,28]}],"verseLabel":"طه: 27-28","question":"ما الغرض من تنكير ﴿عُقْدَةً﴾ في دعاء موسى: ﴿وَاحْلُلْ عُقْدَةً مِنْ لِسَانِي﴾؟","answer":"من الأوجه المذكورة أنه سأل حل ما يمنع الناس من فهمه، لا بلوغ غاية الفصاحة؛ لأن غرضه التبليغ الذي يقتضيه البيان المفهوم. ويذكر المصدر أيضًا وجه التعظيم لشدة العقدة وثقلها، فلا يحصر التنكير في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص783، تحت عنوان «الغرض من تنكير ﴿عُقْدَةً﴾ وتوجيه المراد بها»","url":""}]},{"id":"s20-31","number":31,"surah":20,"verses":[29,30,31,32],"references":[{"surah":20,"verses":[29,30,31,32]}],"verseLabel":"طه: 29-32","question":"لماذا وصف موسى هارون بالأخوة عند طلبه وزيرًا يعينه في الدعوة؟","answer":"جعل طلبه مشفوعًا بعلته؛ فهو يريد وزيرًا مخلصًا أمينًا يكون محل ثقته، وهارون معروف عنده بأصالة الرأي. فذكر الأخوة يبرز سبب اختيار هذا المعين ومؤازرته، لا مجرد طلب أي وزير.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص792، تحت عنوان «بلاغة الإطناب بذكر وصف الأخوة بعد قوله: ﴿هَارُونَ﴾»","url":""}]},{"id":"s20-32","number":32,"surah":20,"verses":[33,34],"references":[{"surah":20,"verses":[33,34]}],"verseLabel":"طه: 33-34","question":"ما دلالة «كي» في جعل التسبيح والذكر غاية لطلب موسى مؤازرة هارون؟","answer":"جعل موسى التسبيح والذكر غاية لطلبه أن يكون هارون وزيرًا له، وأن يشد به أزره ويشاركه في أمره؛ فالمؤازرة مطلوبة للإعانة على عبادة الله والإكثار منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص796، تحت عنوان «معنى ﴿كَيْ﴾ ودلالتها في قوله: ﴿كَيْ نُسَبِّحَكَ﴾»","url":""}]},{"id":"s20-150","number":150,"surah":20,"verses":[33,34],"references":[{"surah":20,"verses":[33,34]}],"verseLabel":"طه: 33-34","question":"ما الغرض من تكرير ﴿كَثِيرًا﴾ في ﴿كَيْ نُسَبِّحَكَ كَثِيرًا وَنَذْكُرَكَ كَثِيرًا﴾؟","answer":"يخص كلًّا من التسبيح والذكر بالكثرة: تنزيهًا كثيرًا في زمان كثير، وثناءً بصفات الكمال كثيرًا في وقت كثير. فالتكرير مع دلالة اللفظ على الكثرة يبالغ في طلب كثرة لا يحدها حد.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص797–798، تحت عنوان «الغرض من تكرير ﴿كَثِيرًا﴾ في الموضعين»","url":""}]},{"id":"s20-33","number":33,"surah":20,"verses":[35],"references":[{"surah":20,"verses":[35]}],"verseLabel":"طه: 35","question":"ما الغرض من تقديم ﴿بِنَا﴾ على ﴿بَصِيرًا﴾ في دعاء موسى؟","answer":"يفيد تقوية الخبر وتأكيد إحاطة علم الله بحالهما؛ فإشعار التقديم بالتخصيص هنا للمبالغة في التأكيد، لا لقصر بصر الله عليهما. كما يراعي هذا التقديم فواصل الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص800، تحت عنوان «الغرض من تقديم شبه الجملة على الخبر في قوله: ﴿إِنَّكَ كُنْتَ بِنَا بَصِيرًا﴾»","url":""}]},{"id":"s20-151","number":151,"surah":20,"verses":[35],"references":[{"surah":20,"verses":[35]}],"verseLabel":"طه: 35","question":"ما دلالة الماضي ﴿كُنْتَ﴾ في قول موسى: ﴿إِنَّكَ كُنْتَ بِنَا بَصِيرًا﴾؟","answer":"يقوي التعبير بالماضي ثبوت الخبر وتحققه واستمراره في الزمن الماضي، ويجتمع مع توكيد الجملة بـ«إن». فلا يعرض بصر الله بحالهما أمرًا مستحدثًا عند الدعاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج31، ص799–800، تحت عنوان «دلالة التعبير بفعل الكون ماضيًا: ﴿كُنْتَ﴾»","url":""}]},{"id":"s20-34","number":34,"surah":20,"verses":[36],"references":[{"surah":20,"verses":[36]}],"verseLabel":"طه: 36","question":"لماذا قيل لموسى: ﴿أُوتِيتَ سُؤْلَكَ﴾ بدلًا من «أوتيت ما سألت»؟","answer":"«ما سألت» تخصص العطاء بما طلبه في هذا المقام، أما «سؤلك» فتشمل مطالبه فيه وما قبله وما بعده، كما يبين المصدر؛ فالتعبير أوسع في بيان شمول الإجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص12، تحت عنوان «سر العدول عن (أوتيت ما سألت) إلى ﴿أُوتِيتَ سُؤْلَكَ﴾»","url":""}]},{"id":"s20-152","number":152,"surah":20,"verses":[36],"references":[{"surah":20,"verses":[36]}],"verseLabel":"طه: 36","question":"ما دلالة ﴿قَدْ﴾ في قوله لموسى: ﴿قَدْ أُوتِيتَ سُؤْلَكَ﴾؟","answer":"تؤكد «قد» مع الماضي تحقق الإجابة فتطمئن موسى إلى قبول دعائه. ويذكر المصدر فيها أيضًا التقريب، أي قرب الإجابة، والتوقع؛ لأنها جاءت جوابًا لسؤاله وتطلعه إلى ما سأل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص11–12، تحت عنوان «دلالة التعبير بحرف التحقيق»","url":""}]},{"id":"s20-35","number":35,"surah":20,"verses":[37],"references":[{"surah":20,"verses":[37]}],"verseLabel":"طه: 37","question":"ما دلالة تذكير موسى بالمنة عليه ﴿مَرَّةً أُخْرَى﴾؟","answer":"«أخرى» بمعنى غير هذه المنة، وقد تكون سابقة لها في الزمن. يذكره الله بحفظه وكفالته عند ولادته ليطمئن إلى استمرار العناية به بعد تأهيله للرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص16، تحت عنوان «نكتة مجيء قوله: ﴿مَرَّةً﴾ نكرة موصوفة ﴿أُخْرَى﴾»","url":""}]},{"id":"s20-153","number":153,"surah":20,"verses":[37],"references":[{"surah":20,"verses":[37]}],"verseLabel":"طه: 37","question":"ما بلاغة إجمال المنة على موسى في ﴿مَرَّةً أُخْرَى﴾ قبل تفصيلها؟","answer":"الإجمال قبل التفصيل يؤكد المعنى بذكره مرتين، إحداهما مجملة والأخرى مفصلة، ويشوق السامع إلى معرفة تفاصيل النعمة التي أُجملت له.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص16، تحت عنوان «بلاغة الإطناب بالتفصيل بعد الإجمال في قوله: ﴿مَرَّةً أُخْرَى﴾»","url":""}]},{"id":"s20-36","number":36,"surah":20,"verses":[38],"references":[{"surah":20,"verses":[38]}],"verseLabel":"طه: 38","question":"ما دلالة تسمية ما أُلقي إلى أم موسى ﴿وَحْيًا﴾؟","answer":"من أوجه الوحي هنا إلهام أم موسى بما تصنع بولدها وإلقاء اليقين في قلبها؛ إذ لا يكون إقدامها على هذا الأمر المعتاد الخوف منه بتدبير بشري مجرد. وتسميته وحيًا لا تجعله وحي نبوة، فقد ورد الوحي لغير الأنبياء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص21–22، تحت عنوان «سر التعبير بالوحي في قوله: ﴿أَوْحَيْنَا﴾»","url":""}]},{"id":"s20-37","number":37,"surah":20,"verses":[39],"references":[{"surah":20,"verses":[39]}],"verseLabel":"طه: 39","question":"لماذا تكرر الأمر بالقذف في ﴿اقْذِفِيهِ فِي التَّابُوتِ فَاقْذِفِيهِ فِي الْيَمِّ﴾؟","answer":"لتعدد المعنى: القذف الأول وضع موسى في التابوت، والثاني الإلقاء في اليم على حقيقة معنى القذف. ويذكر المصدر احتمال عود الضمير الثاني إلى التابوت أو إلى موسى، والقصد في الحالين إنفاذ الأمر المتعلق بموسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص33–34، تحت عنوان «سر تكرار الأمر بالقذف»","url":""}]},{"id":"s20-38","number":38,"surah":20,"verses":[39],"references":[{"surah":20,"verses":[39]}],"verseLabel":"طه: 39","question":"ما سرّ التعبير بـ﴿وَأَلْقَيْتُ عَلَيْكَ مَحَبَّةً مِنِّي﴾؟","answer":"صور تعلق المحبة به بالإلقاء: خلق الله له المحبة في القلوب من غير سبب عادي، حتى أحبه فرعون وامرأته. ففي التعبير بيان عناية الله ورعايته له، وأن هذه المحبة مقدرة منه تتجاوز أسباب البشر المعتادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص42–43، تحت عنوان «سر التعبير بالإلقاء في قوله: ﴿وَأَلْقَيْتُ﴾»","url":""}]},{"id":"s20-39","number":39,"surah":20,"verses":[40],"references":[{"surah":20,"verses":[40]}],"verseLabel":"طه: 40","question":"ما سرّ التعبير بـ﴿فَرَجَعْنَاكَ إِلَى أُمِّكَ كَيْ تَقَرَّ عَيْنُهَا﴾؟","answer":"إسناد الرجوع إلى أمه يمهد لذكر قرة عينها؛ فالنعمة مشتركة بينهما: عادت هي إلى رضاعه وكفالته، وهو عاد إلى حنانها وتربيتها. وهكذا جمع تفضل الله بين رعاية موسى وإسعاد أمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص63، تحت عنوان «سر إسناد الرجوع إلى أم موسى في السياق»","url":""}]},{"id":"s20-40","number":40,"surah":20,"verses":[41],"references":[{"surah":20,"verses":[41]}],"verseLabel":"طه: 41","question":"ما دلالة اختيار الاصطناع دون الصنع في ﴿وَاصْطَنَعْتُكَ لِنَفْسِي﴾؟","answer":"الاصطناع أبلغ في الإكرام من الصنع؛ فالزيادة في بنائه تقوي المعنى. وهو يدل هنا على اختيار موسى وتقريبه وجعله من خواصه سبحانه، فيبرز العناية الخاصة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص85، تحت عنوان «سر التعبير بالاصطناع دون الصنع»","url":""}]},{"id":"s20-154","number":154,"surah":20,"verses":[41],"references":[{"surah":20,"verses":[41]}],"verseLabel":"طه: 41","question":"ما دلالة اللام في ﴿لِنَفْسِي﴾ من قوله: ﴿وَاصْطَنَعْتُكَ لِنَفْسِي﴾؟","answer":"هي لام الأجل؛ أي جعلتك قائمًا بأمري من إقامة الحجة وتبليغ الرسالة. فتكون حركاتك وسكناتك في ذلك لي، لا لنفسك ولا لأحد سواي، وهو معنى إخلاص المهمة لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص85، تحت عنوان «دلالة اللام في شبه الجملة: ﴿لِنَفْسِي﴾»","url":""}]},{"id":"s20-41","number":41,"surah":20,"verses":[42],"references":[{"surah":20,"verses":[42]}],"verseLabel":"طه: 42","question":"ما سرّ التعبير بـ﴿وَلَا تَنِيَا فِي ذِكْرِي﴾؟","answer":"يوجه التعبير إلى استغراق أوقاتهما بالذكر؛ فهو يقوي فؤاديهما بالطمأنينة فلا يهابانه. ومن يلازم ذكر الله ولا يفتر عنه يستحضر معيته ويثبت قلبه عند مواجهة فرعون.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص92، تحت عنوان «دلالة التعبير بالظرفية ﴿فِي﴾»","url":""}]},{"id":"s20-42","number":42,"surah":20,"verses":[43,44],"references":[{"surah":20,"verses":[43,44]}],"verseLabel":"طه: 43-44","question":"ما دلالة أمر موسى وهارون بالقول اللين لفرعون؟","answer":"القول اللين أقرب إلى القلب وأدعى إلى الإصغاء والقبول؛ فالمقصود اهتداء المدعو. وقد جاء عرض الدعوة على فرعون بصيغة العرض والمشورة، حتى لا تدفعه الحماقة إلى التجبر والعناد عند الإغلاظ عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص103، تحت عنوان «بلاغة التعبير بالقول اللين في دعوة فرعون والطغاة»","url":""}]},{"id":"s20-43","number":43,"surah":20,"verses":[44],"references":[{"surah":20,"verses":[44]}],"verseLabel":"طه: 44","question":"إلى من يرجع الترجي في ﴿لَعَلَّهُ يَتَذَكَّرُ أَوْ يَخْشَى﴾؟","answer":"يرجع الترجي إلى موسى وهارون: اذهبا على رجائكما وطمعكما في انتفاع فرعون؛ ليجدا في دعوته ويباشرا الأمر باهتمام. ولا يرجع إلى تردد في علم الله؛ فهو يعلم ما كان وما سيكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص104، تحت عنوان «دلالة الترجي في قوله: ﴿لَعَلَّهُ﴾»","url":""}]},{"id":"s20-44","number":44,"surah":20,"verses":[45],"references":[{"surah":20,"verses":[45]}],"verseLabel":"طه: 45","question":"ما سر اختيار ﴿يَفْرُطَ عَلَيْنَا﴾ في خوف موسى وهارون من فرعون؟","answer":"يفيد أن يعاجلهما فرعون بالعقوبة فلا يتأنى لسماع ما يعرضانه عليه. فالخوف من مبادرته بالأذى قبل إتمام البيان، لا من مجرد حصول العقوبة بعد استيفاء سماع الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص111–112، تحت عنوان «سر التعبير بالفعل ﴿يَفْرُطَ﴾ دون غيره»","url":""}]},{"id":"s20-155","number":155,"surah":20,"verses":[45],"references":[{"surah":20,"verses":[45]}],"verseLabel":"طه: 45","question":"ما دلالة ذكر ﴿أَنْ يَطْغَى﴾ بعد ﴿أَنْ يَفْرُطَ عَلَيْنَا﴾؟","answer":"يعرض المصدر الانتقال على أنه من الأشد إلى الأضعف: يخافان المعاجلة بالعقاب، ويرجوان ألا يقع منه الطغيان عليهما أصلًا، فضلًا عن صورته الأشد. فالمقصود نفي الأذى من أصله، ولا يفسر الترتيب هنا بأنه زيادة في الأذى بعد وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص113، تحت عنوان «دلالة ذكر ﴿أَنْ يَطْغَى﴾ بعد ﴿أَنْ يَفْرُطَ﴾»","url":""}]},{"id":"s20-45","number":45,"surah":20,"verses":[46],"references":[{"surah":20,"verses":[46]}],"verseLabel":"طه: 46","question":"ما سرّ التعبير بـ﴿إِنَّنِي مَعَكُمَا أَسْمَعُ وَأَرَى﴾؟","answer":"جمع السمع والرؤية لأن المواجهة بين الرسولين وفرعون تشتمل على القول والفعل؛ فيناسب السمع القول، والرؤية الفعل. وفي هذا تأكيد حفظ خاص مستمر لهما من أذى فرعون وعدوانه، يثبت قلبيهما عند الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص120، تحت عنوان «دلالة الجمع بين السمع والرؤية»","url":""}]},{"id":"s20-46","number":46,"surah":20,"verses":[47],"references":[{"surah":20,"verses":[47]}],"verseLabel":"طه: 47","question":"ما الغرض من ختام خطاب موسى وهارون لفرعون بـ﴿وَالسَّلَامُ عَلَى مَنِ اتَّبَعَ الْهُدَى﴾؟","answer":"هي جملة جامعة تدعوه إلى الإيمان والانقياد، وتبشر من اتبع الهدى بالسلامة في الدنيا والآخرة. كما تحذر من عاقبة التكذيب والإعراض؛ فربط السلامة باتباع الهدى يحمل الوعد والتحذير في خطاب موجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص137، تحت عنوان «سر ختام تكليفات الله موسى وهارون بالتحية»","url":""}]},{"id":"s20-47","number":47,"surah":20,"verses":[49],"references":[{"surah":20,"verses":[49]}],"verseLabel":"طه: 49","question":"ما دلالة التثنية في ﴿فَمَنْ رَبُّكُمَا﴾ وتخصيص موسى بالنداء في ﴿يَا مُوسَى﴾؟","answer":"الخطاب موجه إلى موسى وهارون معًا، ثم خص موسى بالنداء؛ لأنه الأصل في الرسالة والمتولي للكلام، وهارون تابع له ومعين. ويذكر المصدر وجوهًا أخرى، منها معرفة فرعون السابقة بموسى حين تربى عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص148–149، تحت عنوان «دلالة تثنية خطاب فرعون لهما، وتخصيص موسى بالنداء»","url":""}]},{"id":"s20-48","number":48,"surah":20,"verses":[50],"references":[{"surah":20,"verses":[50]}],"verseLabel":"طه: 50","question":"ما دلالة تعريف موسى ربه بأنه ﴿أَعْطَى كُلَّ شَيْءٍ خَلْقَهُ ثُمَّ هَدَى﴾؟","answer":"جمع الجواب في ألفاظ قليلة إعطاء كل شيء خلقه وهدايته إلى الانتفاع بما أُعطي. فعرّف موسى ربه بآثار صنعه وتدبيره، وسلك طريق الاستدلال والإرشاد بعبارة موجزة جامعة تبلغ بالحجة غايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص159، تحت عنوان «بلاغة الإيجاز في جواب موسى لفرعون»","url":""}]},{"id":"s20-49","number":49,"surah":20,"verses":[51],"references":[{"surah":20,"verses":[51]}],"verseLabel":"طه: 51","question":"ما دلالة انتقال فرعون إلى السؤال: ﴿فَمَا بَالُ الْقُرُونِ الْأُولَى﴾؟","answer":"لما قامت الحجة عليه أراد التشغيب بنقل الحديث إلى مصير القرون السابقة: فإن قيل إنهم في عذاب ثارت أبناؤهم، وإن قيل إنهم في سلام اتخذ ذلك حجة لدينهم. فهو عدول عن الاعتناء بالخلق الأول إلى سؤال تعجيز وتشغيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص164، تحت عنوان «دلالة احتجاج فرعون بالقرون الأولى»","url":""}]},{"id":"s20-50","number":50,"surah":20,"verses":[52],"references":[{"surah":20,"verses":[52]}],"verseLabel":"طه: 52","question":"كيف صرف جواب موسى ﴿عِلْمُهَا عِنْدَ رَبِّي﴾ الحوار عن تشغيب فرعون؟","answer":"فوض تفاصيل أحوال الأمم الماضية إلى علم الله، ولم يسترسل في بحث لا يخدم مقام دعوة الأحياء. فصرف فرعون عن الاشتغال بما لا يجدي، مع إثبات أن علم الله محيط بالتفاصيل التي لا يعلمها موسى كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص168، تحت عنوان «بلاغة الاستئناف البياني في قوله: ﴿قَالَ عِلْمُهَا﴾»","url":""}]},{"id":"s20-51","number":51,"surah":20,"verses":[52],"references":[{"surah":20,"verses":[52]}],"verseLabel":"طه: 52","question":"ما دلالة الجمع بين ﴿لَا يَضِلُّ رَبِّي وَلَا يَنْسَى﴾؟","answer":"استوعب الجمع الآفات التي تخل بالعلم: الغلط في المعلومات هو الضلال، وزوالها هو النسيان. فنفيهما معًا كناية عن كمال العلم وسلامته من الخطأ والذهاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص173–174، تحت عنوان «بلاغة الجمع بين الضلال والنسيان»","url":""}]},{"id":"s20-52","number":52,"surah":20,"verses":[53],"references":[{"surah":20,"verses":[53]}],"verseLabel":"طه: 53","question":"ما سرّ وصف الأرض بـ﴿مَهْدًا﴾؟","answer":"شبّهها بمهد الطفل المهيأ للسكون والحياة، فاستحضر نعمة التهيئة لا مجرد الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص181، 182، 189، تحت «التشبيه البليغ في وصف الأرض بالمهد»","url":""}]},{"id":"s20-53","number":53,"surah":20,"verses":[54],"references":[{"surah":20,"verses":[54]}],"verseLabel":"طه: 54","question":"ما دلالة ختام دلائل النبات بـ﴿لِأُولِي النُّهَى﴾؟","answer":"سميت العقول نهى لأنها تنهى أصحابها عن اتباع الباطل وارتكاب القبائح. فخصت الآيات أصحاب العقول الناهية عن الأباطيل لأنهم المنتفعون بها، وفي ذلك تعريض بمن لم يعتبر بالدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص196، تحت عنوان «سر استعمال النهى عوض عن العقول والألباب»","url":""}]},{"id":"s20-54","number":54,"surah":20,"verses":[55],"references":[{"surah":20,"verses":[55]}],"verseLabel":"طه: 55","question":"ما وجه اتصال ذكر خلق الإنسان وبعثه بذكر إخراج النبات من الأرض؟","answer":"كلاهما يتضمن إخراج أجسام لطيفة من التربة الكثيفة؛ فذكر خلق الإنسان بعد إخراج النبات يلائم السياق، وخروج الموتى يشبه خروج النبات، وفي ذلك تقريب لدليل الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص200، تحت عنوان «براعة الاتساق السياقي»","url":""}]},{"id":"s20-55","number":55,"surah":20,"verses":[56],"references":[{"surah":20,"verses":[56]}],"verseLabel":"طه: 56","question":"ما سرّ التعبير بـ﴿وَلَقَدْ أَرَيْنَاهُ آيَاتِنَا كُلَّهَا﴾؟","answer":"الجمع المضاف المؤكد يفيد العموم، والمراد هنا استغراق الآيات المعهودة من آيات موسى التي أراها الله فرعون. فالمقصود استيفاء البيان في هذا المقام، وليس أن فرعون رأى كل آية لله على الإطلاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص208، تحت عنوان «دلالة الجمع المضاف المؤكد»","url":""}]},{"id":"s20-56","number":56,"surah":20,"verses":[57],"references":[{"surah":20,"verses":[57]}],"verseLabel":"طه: 57","question":"ما سر إضافة السحر إلى ضمير موسى في قول فرعون: ﴿بِسِحْرِكَ﴾؟","answer":"الإضافة للتقليل والتهوين؛ قصد فرعون تحقير ما أتى به موسى، وزعم أن ما عنده ليس إلا سحرًا يسيرًا يمكن أن يأتي بمثله. فهي محاولة لإضعاف أثر الآية في نفوس الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص219، تحت عنوان «سر إضافة السحر إلى ضمير موسى»","url":""}]},{"id":"s20-57","number":57,"surah":20,"verses":[58],"references":[{"surah":20,"verses":[58]}],"verseLabel":"طه: 58","question":"ما دلالة اتساع صيغة ﴿مَوْعِدًا﴾ في طلب فرعون من موسى؟","answer":"تحتمل الصيغة زمان الوعد ومكانه، كما تحتمل المصدر؛ فذكر يوم الزينة يرجح جهة الزمان، وذكر مكانًا سوى جهة المكان، ووصفه بعدم الإخلاف يلائم المواعدة. وهي صيغة موجزة تتسع لهذه المعاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص223، تحت عنوان «دلالة صيغة (مفعل) واتساع معناها»","url":""}]},{"id":"s20-156","number":156,"surah":20,"verses":[58],"references":[{"surah":20,"verses":[58]}],"verseLabel":"طه: 58","question":"لماذا كررت ﴿لَا﴾ في ﴿لَا نُخْلِفُهُ نَحْنُ وَلَا أَنْتَ﴾؟","answer":"لتأكيد عدم الإخلاف من كل جانب بالنص على الطرفين؛ فعدم إخلاف أحدهما لا يستلزم وفاء الآخر. وفي هذا إظهار من فرعون لحرصه على إنجاز الوعد وعزمه على إتمامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص224، تحت عنوان «فائدة تكرار (لا) النافية»","url":""}]},{"id":"s20-157","number":157,"surah":20,"verses":[58],"references":[{"surah":20,"verses":[58]}],"verseLabel":"طه: 58","question":"ما دلالة وصف مكان اللقاء بين موسى وفرعون بأنه ﴿سُوًى﴾؟","answer":"من معانيه مكان تتساوى مسافته بين الفريقين، أو مكان مستو ظاهر بلا ارتفاع وانخفاض، بحيث يشاهد الحاضرون ما يجري. ويذكر المصدر أيضًا دلالة معنوية على العدل والإنصاف وتساوي الطرفين.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص226–227، تحت عنوان «دلالة الوصف بـ﴿سُوًى﴾»","url":""}]},{"id":"s20-58","number":58,"surah":20,"verses":[59],"references":[{"surah":20,"verses":[59]}],"verseLabel":"طه: 59","question":"لماذا اختار موسى ﴿يَوْمُ الزِّينَةِ﴾ موعدًا للمواجهة؟","answer":"ليكون الأمر مشهودًا على رؤوس الأشهاد ويشيع ظهوره بين الحاضرين؛ فاختيار يوم اجتماعهم يظهر ثقته، ويتيح تبليغ الدعوة لأكبر جمع.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص233، تحت عنوان «سر اختيار يوم الزينة»","url":""}]},{"id":"s20-158","number":158,"surah":20,"verses":[59],"references":[{"surah":20,"verses":[59]}],"verseLabel":"طه: 59","question":"لماذا اختير وقت ﴿ضُحًى﴾ لحشر الناس في مواجهة موسى للسحرة؟","answer":"لأنه أول النهار، فإن امتدت المناظرة بقي للناس متسع لمصالحهم، وهو وقت مظنة انتباههم ونشاطهم. كما أنه وقت ظاهر جلي يصلح لإظهار الآيات ووضوح المشاهدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص234، تحت عنوان «نكتة اختيار الظرف ﴿ضُحًى﴾»","url":""}]},{"id":"s20-59","number":59,"surah":20,"verses":[60],"references":[{"surah":20,"verses":[60]}],"verseLabel":"طه: 60","question":"ما دلالة الفاء في ﴿فَجَمَعَ كَيْدَهُ﴾ بعد تولي فرعون؟","answer":"تفيد التعقيب؛ انصرف فرعون فأسرع في استجماع كيده وإعداد خطته للموعد. فتصور الفاء مباشرة الإعداد بعد الانصراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص239–240، تحت عنوان «دلالة العطف بالفاء في: ﴿فَجَمَعَ كَيْدَهُ﴾»","url":""}]},{"id":"s20-159","number":159,"surah":20,"verses":[60],"references":[{"surah":20,"verses":[60]}],"verseLabel":"طه: 60","question":"لماذا سمّي ما أعده فرعون للموعد ﴿كَيْدَهُ﴾؟","answer":"يلائم لفظ الكيد ما يحضره فرعون من السحر؛ فهو إحكام للاحتيال في إعداد الخطة، والسحر قائم على التمويه والخداع. وإسناده إليه يربط هذا التدبير بصاحبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص240، تحت عنوان «سر اختيار لفظ ﴿كَيْدَهُ﴾ وإسناده إلى الضمير»","url":""}]},{"id":"s20-160","number":160,"surah":20,"verses":[60],"references":[{"surah":20,"verses":[60]}],"verseLabel":"طه: 60","question":"ما دلالة ﴿ثُمَّ﴾ في ﴿فَجَمَعَ كَيْدَهُ ثُمَّ أَتَى﴾؟","answer":"تفيد التراخي الزمني بين التحضير للموعد والإتيان إليه؛ فتجهيز ما جمعه وإعداده للمواجهة يستغرق وقتًا، بخلاف التعقيب الذي أفادته الفاء قبل جمع الكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص240، تحت عنوان «نكتة العطف بـ﴿ثُمَّ﴾»","url":""}]},{"id":"s20-60","number":60,"surah":20,"verses":[61],"references":[{"surah":20,"verses":[61]}],"verseLabel":"طه: 61","question":"لماذا افتتح موسى نصحه للسحرة بقوله: ﴿وَيْلَكُمْ﴾؟","answer":"هو إنذار شديد يصدر عن شفقة وحرص على هدايتهم؛ يسترعي أسماعهم للموعظة، ولا يقصد به الدعاء عليهم بالهلاك ابتداءً. فحذرهم من سوء العاقبة إن استمروا في الافتراء، ليجتنبوا أسبابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص242، تحت عنوان «نكتة التعبير بلفظ ﴿وَيْلَكُمْ﴾ دون سواه»","url":""}]},{"id":"s20-161","number":161,"surah":20,"verses":[61],"references":[{"surah":20,"verses":[61]}],"verseLabel":"طه: 61","question":"ما دلالة اختيار فعل السحت في ﴿فَيُسْحِتَكُمْ بِعَذَابٍ﴾؟","answer":"أصل السحت الاستئصال والفناء والإذهاب؛ فالتعبير يصور عذابًا مستأصلًا ينقطع به الأثر، وهو كناية عن المبالغة في الإهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص243، تحت عنوان «دلالة التعبير بفعل السحت»","url":""}]},{"id":"s20-162","number":162,"surah":20,"verses":[61],"references":[{"surah":20,"verses":[61]}],"verseLabel":"طه: 61","question":"ما موقع ﴿وَقَدْ خَابَ مَنِ افْتَرَى﴾ من نهي موسى عن الافتراء؟","answer":"تساق الجملة لتعليل النهي: اجتنبوا الكذب على الله، فقد خاب من افترى قبلكم. ويجوز أن تكون اعتراضية تقرر ما قبلها، فيقوى التحذير بذكر عاقبة المفتري.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص244، تحت عنوان «موقع جملة: ﴿وَقَدْ خَابَ مَنِ افْتَرَى﴾ مما قبلها»","url":""}]},{"id":"s20-61","number":61,"surah":20,"verses":[62],"references":[{"surah":20,"verses":[62]}],"verseLabel":"طه: 62","question":"ما دلالة الجمع بين تنازع السحرة أمرهم وإسرارهم النجوى؟","answer":"عطف إسرار النجوى على التنازع يبين اجتماع اختلاف الرأي مع كتمان الحديث؛ فتنازعهم وتشاورهم كانا محكومين بالسرية، لا مجادلة معلنة أمام الحاضرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص251، تحت عنوان «موقع جملة: ﴿وَأَسَرُّوا﴾ مما قبلها»","url":""}]},{"id":"s20-62","number":62,"surah":20,"verses":[63],"references":[{"surah":20,"verses":[63]}],"verseLabel":"طه: 63","question":"ما دلالة توكيد اتهام موسى وهارون في قولهم: ﴿إِنْ هَذَانِ لَسَاحِرَانِ﴾؟","answer":"افتتحوا القول بالتوكيد ليثبتوا اتهام موسى وهارون بالسحر عند من يخامره الشك في صحة دعوتهما. فجعلوا ما ظهر من المعجزة سحرًا؛ لأنهم كانوا يطلقون السحر على خوارق العادات.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص259، تحت عنوان «دلالة استهلال القول بـ(إن)»","url":""}]},{"id":"s20-63","number":63,"surah":20,"verses":[64],"references":[{"surah":20,"verses":[64]}],"verseLabel":"طه: 64","question":"ما دلالة قوله: ﴿فَأَجْمِعُوا كَيْدَكُمْ﴾؟","answer":"إجماع الكيد إحكام للعزم واستجماع للهمم وتوحيد للتدبير بعد التنازع؛ فانتقلوا من شتات الرأي والتردد إلى قصد واحد وإرادة مجتمعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص264، تحت عنوان «دلالة إجماع الكيد»","url":""}]},{"id":"s20-163","number":163,"surah":20,"verses":[64],"references":[{"surah":20,"verses":[64]}],"verseLabel":"طه: 64","question":"ما دلالة تقييد إتيان السحرة بالحال ﴿صَفًّا﴾؟","answer":"يصور مجيئهم مصطفين في هيئة متماسكة منظمة؛ ليكون ذلك أهيب في نفوس المشاهدين وأقوى في إظهار اجتماعهم. وتنكير ﴿صفًّا﴾ يشعر بعظمة ذلك الصف وكماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص265–266، تحت عنوان «دلالة التقييد بالحال ﴿صَفًّا﴾»","url":""}]},{"id":"s20-64","number":64,"surah":20,"verses":[65],"references":[{"surah":20,"verses":[65]}],"verseLabel":"طه: 65","question":"ما دلالة تخيير السحرة موسى بين أن يلقي أو يكونوا أول من ألقى؟","answer":"أبدى قولهم ﴿نَكُونَ أَوَّلَ مَنْ أَلْقَى﴾ رغبتهم في السبق وثقتهم بسحرهم؛ إذ أرادوا أن يكون لأول مشهد أثر قوي في أعين الجمهور، وظنوا أن ما يلقونه سيحمل موسى على التحدي بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص274، تحت عنوان «نكتة اختيار لفظ ﴿أَوَّلَ﴾ وفائدته»","url":""}]},{"id":"s20-65","number":65,"surah":20,"verses":[66],"references":[{"surah":20,"verses":[66]}],"verseLabel":"طه: 66","question":"ما نكتة بناء ﴿يُخَيَّلُ﴾ للمفعول في وصف سحر السحرة؟","answer":"حذف الفاعل الظاهر يقلل من شأن القوى الخفية التي قامت بالتخييل، في مقابل وضوح مصدر معجزة موسى وأنها من عند الله؛ فلا يبرز النص فاعل التخييل ولا يعظمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص278، تحت عنوان «نكتة بناء فعل ﴿يُخَيَّلُ﴾ للمفعول»","url":""}]},{"id":"s20-164","number":164,"surah":20,"verses":[66],"references":[{"surah":20,"verses":[66]}],"verseLabel":"طه: 66","question":"ما دلالة ﴿مِنْ﴾ في قوله: ﴿مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى﴾؟","answer":"هي سببية؛ أي إن تخيل موسى حركة الحبال والعصي وقع بسبب سحرهم وفعلهم، فصرح التركيب بمصدر ذلك التخييل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص279، تحت عنوان «نوع ﴿مِنْ﴾ ومعناها»","url":""}]},{"id":"s20-66","number":66,"surah":20,"verses":[67],"references":[{"surah":20,"verses":[67]}],"verseLabel":"طه: 67","question":"ما دلالة تصوير خوف موسى بقوله: ﴿فَأَوْجَسَ فِي نَفْسِهِ خِيفَةً﴾؟","answer":"كانت خيفة موسى عارضة مما رأى من مشهد غير مألوف، وهي من مقتضى البشرية لا نقص فيها. وقيل: خشي أن ينصرف الناس قبل ظهور الحق؛ فجاءه التثبيت والأمر بالإلقاء ليزول الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص286، تحت عنوان «دلالة لفظ ﴿خِيفَةً﴾»","url":""}]},{"id":"s20-67","number":67,"surah":20,"verses":[68],"references":[{"surah":20,"verses":[68]}],"verseLabel":"طه: 68","question":"ما دلالة تثبيت موسى بقوله: ﴿إِنَّكَ أَنْتَ الْأَعْلَى﴾؟","answer":"اجتمعت في الجملة مؤكدات منها ﴿إن﴾ وتكرير الضمير وتعريف ﴿الأعلى﴾؛ لتقرير غلبة موسى ورفع ما عرض له من الخوف، مهما عظم السحر في أعين الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص289–290، تحت عنوان «بلاغة اجتماع التوكيدات»","url":""}]},{"id":"s20-68","number":68,"surah":20,"verses":[69],"references":[{"surah":20,"verses":[69]}],"verseLabel":"طه: 69","question":"ما سرّ التعبير بـ﴿تَلْقَفْ مَا صَنَعُوا﴾ لا «عصيهم»؟","answer":"عبر عن الحبال والعصي بالموصول ﴿ما صنعوا﴾ لتهوين شأنها مع استيعاب كل ما أعدوه وأحكموه؛ فالمعجزة تلقف جميع مصنوعهم الكثير ولا تبقي منه شيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص298–299، تحت عنوان «نكتة التعبير عن العصي والحبال بالاسم الموصول»","url":""}]},{"id":"s20-69","number":69,"surah":20,"verses":[69],"references":[{"surah":20,"verses":[69]}],"verseLabel":"طه: 69","question":"ما سرّ التعبير بـ﴿وَلَا يُفْلِحُ السَّاحِرُ حَيْثُ أَتَى﴾؟","answer":"﴿حَيْثُ أَتَى﴾ كناية عن عموم نفي الفلاح في كل مكان وزمان؛ فالساحر لا يدرك فلاحًا حقيقيًا أينما توجه، ولو تنقل في البلاد واستجمع أسباب القوة والشهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص302، تحت عنوان «بلاغة الكناية»","url":""}]},{"id":"s20-70","number":70,"surah":20,"verses":[70],"references":[{"surah":20,"verses":[70]}],"verseLabel":"طه: 70","question":"ما سرّ التعبير بـ﴿فَأُلْقِيَ السَّحَرَةُ سُجَّدًا﴾ لا «فسجدوا»؟","answer":"بني فعل الإلقاء للمجهول لتصوير قوة خارجة عن إرادتهم ألقتهم إلى الأرض ساجدين؛ وفي ذلك إبراز لقوة المعجزة وسرعة استجابتهم للإيمان بلا تردد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص306، تحت عنوان «فائدة بناء فعل الإلقاء للمجهول»","url":""}]},{"id":"s20-71","number":71,"surah":20,"verses":[71],"references":[{"surah":20,"verses":[71]}],"verseLabel":"طه: 71","question":"ما دلالة قول فرعون: ﴿إِنَّهُ لَكَبِيرُكُمُ الَّذِي عَلَّمَكُمُ السِّحْرَ﴾؟","answer":"زعم فرعون أن موسى معلم السحرة الأكبر ورئيسهم؛ ليصور إيمانهم كأنه تواطؤ ومؤامرة سبقت اللقاء، ويصرف الناس عن دلالة المعجزة التي ألزمتهم السجود.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص317، تحت عنوان «دلالة اختيار مفردة ﴿لَكَبِيرُكُم﴾»","url":""}]},{"id":"s20-72","number":72,"surah":20,"verses":[72],"references":[{"surah":20,"verses":[72]}],"verseLabel":"طه: 72","question":"ما سر التعبير بالإيثار في قول السحرة: ﴿لَنْ نُؤْثِرَكَ عَلَى مَا جَاءَنَا مِنَ الْبَيِّنَاتِ﴾؟","answer":"الإيثار اختيار وتفضيل بين أمرين؛ فأعلن السحرة أنهم لا يقدمون طاعة فرعون ومنافع الدنيا الزائلة على البينات التي شاهدوها، لأن منافع الدنيا لا تعارض منافع الآخرة ومضارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص330–331، تحت عنوان «دلالة اختيار مفردة الإيثار»","url":""}]},{"id":"s20-73","number":73,"surah":20,"verses":[72],"references":[{"surah":20,"verses":[72]}],"verseLabel":"طه: 72","question":"ما غرض الأمر في قول السحرة لفرعون: ﴿فَاقْضِ مَا أَنْتَ قَاضٍ﴾؟","answer":"خرج الأمر عن معناه الظاهر إلى التسوية وعدم المبالاة: افعل ما تريد وأنفذ وعيدك؛ فلن يردنا ذلك عن الإيمان. وفيه إظهار لاستخفافهم بتهديده بعد أن ثبت اليقين في قلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص334–335، تحت عنوان «غرض الأمر وبلاغته»","url":""}]},{"id":"s20-165","number":165,"surah":20,"verses":[72],"references":[{"surah":20,"verses":[72]}],"verseLabel":"طه: 72","question":"ما دلالة القصر في قول السحرة: ﴿إِنَّمَا تَقْضِي هَذِهِ الْحَيَاةَ الدُّنْيَا﴾؟","answer":"قصروا سلطان فرعون وحكمه على الحياة الدنيا؛ فلا يتجاوزها إلى الآخرة. وفي ذلك تهوين لوعيده وتقوية للنفوس المؤمنة برجاء الجزاء الباقي عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص335، تحت عنوان «بلاغة القصر ودلالته»","url":""}]},{"id":"s20-74","number":74,"surah":20,"verses":[73],"references":[{"surah":20,"verses":[73]}],"verseLabel":"طه: 73","question":"ما دلالة إضافة الخطايا إلى ضمير الجمع في قول السحرة: ﴿خَطَايَانَا﴾؟","answer":"نسب السحرة الخطايا إلى أنفسهم اعترافًا صريحًا بها واستعظامًا لها وطلبًا للمغفرة، فلم يبرئوا أنفسهم مما وقع منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص342، تحت عنوان «فائدة الإضافة إلى ضمير الجمع»","url":""}]},{"id":"s20-166","number":166,"surah":20,"verses":[73],"references":[{"surah":20,"verses":[73]}],"verseLabel":"طه: 73","question":"ما دلالة قول السحرة لفرعون: ﴿وَمَا أَكْرَهْتَنَا عَلَيْهِ مِنَ السِّحْرِ﴾؟","answer":"صرحوا بأن فرعون أكرههم على ممارسة السحر، فجمعوا الاعتراف بما وقع منهم وبيان تسلطه عليهم. واختيار لفظ الإكراه يبين أن فعل السحر خالف رغبتهم الأصلية، مع طلبهم المغفرة منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص343–344، تحت عنوان «براعة استعمال مفردة الإكراه»","url":""}]},{"id":"s20-75","number":75,"surah":20,"verses":[73],"references":[{"surah":20,"verses":[73]}],"verseLabel":"طه: 73","question":"ما دلالة ختام كلام السحرة بـ﴿وَاللَّهُ خَيْرٌ وَأَبْقَى﴾؟","answer":"جاءت ﴿وَاللَّهُ خَيْرٌ وَأَبْقَى﴾ تذييلًا جامعًا: ما عند الله خير من منفعة فرعون وأبقى منها، وجزاؤه خير وأدوم من وعيد فرعون وعذابه؛ فاختصرت العبارة خلاصة موقفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص344، تحت عنوان «بلاغة التذييل»","url":""}]},{"id":"s20-76","number":76,"surah":20,"verses":[74],"references":[{"surah":20,"verses":[74]},{"surah":87,"verses":[12,13]}],"verseLabel":"طه: 74؛ الأعلى: 12–13","question":"ما سرّ التعبير بـ﴿لَا يَمُوتُ فِيهَا وَلَا يَحْيَى﴾؟","answer":"في الموضعين نفي لراحتي الموت والحياة النافعة: لا يموت المعذب فيستريح، ولا يحيا حياة ينتفع بها. وجاء التعبير في طه في سياق جزاء المجرم، وفي الأعلى وصفًا لحال من يصلى النار الكبرى؛ فالمعنى واحد مع اختلاف السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص351–352، تحت عنوان «توجيه التشابه اللفظي»","url":""}]},{"id":"s20-77","number":77,"surah":20,"verses":[75],"references":[{"surah":20,"verses":[75]}],"verseLabel":"طه: 75","question":"ما سرّ التعبير بـ﴿قَدْ عَمِلَ الصَّالِحَاتِ﴾ بعد الإيمان؟","answer":"تفيد ﴿قد﴾ تحقيق وقوع العمل الصالح والاهتمام به؛ فالمؤمن إنما يستحق الدرجات العالية إذا تحقق منه العمل الصالح، لا بمجرد الدعوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص353، تحت عنوان «دلالة حرف التحقيق»","url":""}]},{"id":"s20-78","number":78,"surah":20,"verses":[77],"references":[{"surah":20,"verses":[77]}],"verseLabel":"طه: 77","question":"ما سرّ وصف الطريق في البحر بـ﴿يَبَسًا﴾؟","answer":"اختير ﴿يَبَسًا﴾ للدلالة على أن الطريق في قاع البحر صار يابسًا جافًا، لا طين فيه ولا ماء، فكان آمنًا سهل السلوك لبني إسرائيل؛ وفي ذلك تمام المعجزة والطمأنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص371–372، تحت عنوان «سر إيثار مفردة ﴿يَبَسًا﴾ دون سواها»","url":""}]},{"id":"s20-79","number":79,"surah":20,"verses":[77],"references":[{"surah":20,"verses":[77]}],"verseLabel":"طه: 77","question":"ما دلالة التعبير بالدرك في قوله: ﴿لَا تَخَافُ دَرَكًا﴾؟","answer":"الدرك مصدر من إدراك العدو ولحاقه؛ فنفى الله عن موسى وقومه خوف أن يصل إليهم فرعون وجنوده من خلفهم، وفي اللفظ طمأنة من جهة المطاردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص375–376، تحت عنوان «دلالة التعبير بالدرك مادة وصيغة»","url":""}]},{"id":"s20-167","number":167,"surah":20,"verses":[77],"references":[{"surah":20,"verses":[77]}],"verseLabel":"طه: 77","question":"ما سر حذف مفعول ﴿تَخْشَى﴾ في قوله: ﴿وَلَا تَخْشَى﴾؟","answer":"حذف المفعول لإفادة العموم: لا تخشى شيئًا من مخاطر البحر ولا غيره. فبعد الأمان الخاص من لحاق العدو جاء الأمان الشامل من سائر المخاوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص377، تحت عنوان «سر حذف مفعول ﴿تَخْشَى﴾»","url":""}]},{"id":"s20-80","number":80,"surah":20,"verses":[78],"references":[{"surah":20,"verses":[78]}],"verseLabel":"طه: 78","question":"ما سرّ التعبير بـ﴿فَغَشِيَهُمْ مِنَ الْيَمِّ مَا غَشِيَهُمْ﴾؟","answer":"أبهم الموصول في ﴿مَا غَشِيَهُمْ﴾ للتهويل والتفخيم؛ فما غمر فرعون وجنوده من اليم أمر عظيم لا يحيط الوصف بكنهه، فكأن ما وقع أعظم من أن يفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص383، تحت عنوان «نوع ﴿مَا﴾ وأثرها في تهويل المشهد»","url":""}]},{"id":"s20-81","number":81,"surah":20,"verses":[79],"references":[{"surah":20,"verses":[79]}],"verseLabel":"طه: 79","question":"ما سرّ التعبير بـ﴿وَأَضَلَّ فِرْعَوْنُ قَوْمَهُ وَمَا هَدَى﴾؟","answer":"نفت ﴿وَمَا هَدَى﴾ عن فرعون الهداية صراحة، مؤكدة ما قبلها من إثبات إضلاله لقومه. وفي ذلك رد على زعمه أنه يهديهم سبيل الرشاد: أضلهم ولم يهدهم إلى خير قط.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص386، تحت عنوان «دلالة نفي الهدى بـ﴿وَمَا﴾»","url":""}]},{"id":"s20-82","number":82,"surah":20,"verses":[80],"references":[{"surah":20,"verses":[80]}],"verseLabel":"طه: 80","question":"ما نكتة إيقاع المواعدة على بني إسرائيل في قوله: ﴿وَوَاعَدْنَاكُمْ جَانِبَ الطُّورِ الْأَيْمَنَ﴾؟","answer":"أوقعت المواعدة على بني إسرائيل مع أن المباشر لها موسى؛ لأن منافعها عادت إليهم، إذ كانت التوراة لهدايتهم وإصلاح شأنهم، فاتصل الوعد بهم تبعًا لنبيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص396، تحت عنوان «نكتة إيقاع المواعدة على بني إسرائيل»","url":""}]},{"id":"s20-168","number":168,"surah":20,"verses":[80],"references":[{"surah":20,"verses":[80]}],"verseLabel":"طه: 80","question":"ما نكتة ترتيب المنن في قوله: ﴿أَنْجَيْنَاكُمْ﴾ ثم ﴿وَوَاعَدْنَاكُمْ﴾ ثم ﴿وَنَزَّلْنَا عَلَيْكُمُ الْمَنَّ وَالسَّلْوَى﴾؟","answer":"رتبت المنن بحسب المقام: بدأ بالإنجاء من العدو لأنه دفع لأعظم الضرر، ثم المواعدة وإنزال التوراة لأنها نعمة الدين والهداية، ثم المن والسلوى لأنهما نعمة البدن والمعاش.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص399، تحت عنوان «نكتة ترتيب المنن الثلاث»","url":""}]},{"id":"s20-83","number":83,"surah":20,"verses":[81],"references":[{"surah":20,"verses":[81]}],"verseLabel":"طه: 81","question":"ما دلالة إطلاق الطغيان دون تقييد في قوله: ﴿وَلَا تَطْغَوْا فِيهِ﴾؟","answer":"أطلق الطغيان ليعم كل مجاوزة للحد في النعمة: من كفرانها وترك شكرها واستعمالها في المعصية والبطر بها. فكل صورة من تجاوز الحد فيها داخلة في النهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص402–403، تحت عنوان «دلالة إطلاق الطغيان دون تقييده»","url":""}]},{"id":"s20-169","number":169,"surah":20,"verses":[81],"references":[{"surah":20,"verses":[81]}],"verseLabel":"طه: 81","question":"ما دلالة الفاء في قوله: ﴿فَيَحِلَّ عَلَيْكُمْ غَضَبِي﴾؟","answer":"الفاء سببية؛ فحلول الغضب مترتب على الطغيان في النعمة ومسبب عنه. وفي الربط بها تحذير من أن مجاوزة الحد تستدعي العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص404، تحت عنوان «دلالة الفاء في ﴿فَيَحِلَّ﴾»","url":""}]},{"id":"s20-170","number":170,"surah":20,"verses":[81],"references":[{"surah":20,"verses":[81]}],"verseLabel":"طه: 81","question":"ما بلاغة استعارة الحلول في قوله: ﴿فَيَحِلَّ عَلَيْكُمْ غَضَبِي﴾؟","answer":"استعير الحلول، وهو النزول والإقامة، لإصابة الغضب والعذاب؛ فصور العقوبة كأنها تنزل بالمخاطبين وتحيط بهم، مبالغة في التهديد والتخويف.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص404، تحت عنوان «بلاغة الاستعارة في لفظ الحلول»","url":""}]},{"id":"s20-84","number":84,"surah":20,"verses":[82],"references":[{"surah":20,"verses":[82]}],"verseLabel":"طه: 82","question":"ما سرّ التعبير بـ﴿وَإِنِّي لَغَفَّارٌ﴾ بصيغة المبالغة؟","answer":"جاء ﴿غفّار﴾ على صيغة المبالغة للدلالة على كثرة مغفرة الله وعظمتها؛ فمهما عظم ذنب من تاب فإن مغفرة الله أوسع، وفي الصيغة تطمين للتائب وفتح لباب الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص409، تحت عنوان «لطيفة التعبير بصيغة ﴿لَغَفَّارٌ﴾»","url":""}]},{"id":"s20-85","number":85,"surah":20,"verses":[83],"references":[{"surah":20,"verses":[83]}],"verseLabel":"طه: 83","question":"ما دلالة سؤال موسى: ﴿وَمَا أَعْجَلَكَ عَنْ قَوْمِكَ﴾؟","answer":"﴿ما﴾ استفهامية إنكارية تحمل عتابًا لطيفًا لموسى على تعجله بمفارقة قومه قبل الإذن. وصيغة الاستفهام أرفق من التصريح باللوم، وفيها تنبيه إلى ما ترتب على غيبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص416، تحت عنوان «دلالة ﴿مَا﴾ في قوله تعالى: ﴿وَمَا أَعْجَلَكَ﴾»","url":""}]},{"id":"s20-86","number":86,"surah":20,"verses":[84],"references":[{"surah":20,"verses":[84]}],"verseLabel":"طه: 84","question":"ما سر اختيار مفردة العجلة في قول موسى: ﴿وَعَجِلْتُ إِلَيْكَ رَبِّ﴾؟","answer":"وصف موسى ذهابه بالعجلة لأنها كانت مسارعة محمودة إلى طاعة الله وطلب رضاه، لا استعجالًا مذمومًا؛ فالعجلة إلى الخير خير.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص421، تحت عنوان «سر اختيار مفردة العجلة»","url":""}]},{"id":"s20-171","number":171,"surah":20,"verses":[84],"references":[{"surah":20,"verses":[84]}],"verseLabel":"طه: 84","question":"ما دلالة تقييد العجلة بـ﴿إِلَيْكَ﴾ في قول موسى: ﴿وَعَجِلْتُ إِلَيْكَ رَبِّ﴾؟","answer":"قيد العجلة بالاتجاه إلى الله لبيان إخلاص القصد وأن مسارعته كانت إليه وإلى رضاه وحده. وتقديم الجار والمجرور يلائم مقام الاعتذار ويؤكد حسن الباعث.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص422، تحت عنوان «دلالة تقييد العجلة بالجار والمجرور ﴿إِلَيْكَ﴾»","url":""}]},{"id":"s20-172","number":172,"surah":20,"verses":[84],"references":[{"surah":20,"verses":[84]}],"verseLabel":"طه: 84","question":"ما دلالة تعليل موسى عجلته بقوله: ﴿لِتَرْضَى﴾؟","answer":"جعل موسى غاية عجلته طلب رضا الله، فبين أن باعثه الاجتهاد في الطاعة لا مخالفة الأمر. والتعبير بالرضا يستصحب رجاء قبول الاعتذار واستمرار رضا ربه عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص423–424، تحت عنوان «دلالة التعبير بالرضا»","url":""}]},{"id":"s20-87","number":87,"surah":20,"verses":[85],"references":[{"surah":20,"verses":[85]}],"verseLabel":"طه: 85","question":"ما سر إسناد فتنة قوم موسى إلى الله في قوله: ﴿فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ﴾؟","answer":"أسندت الفتنة إلى الله لأنه مقدر أسباب الاختبار وخالقها، ليتميز الثابت من المستعد للانحراف. أما إضلالهم فأسند إلى السامري لأنه السبب المباشر الذي دعاهم إلى عبادة العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص426، تحت عنوان «سر إسناد فتنتهم إلى الله تعالى»","url":""}]},{"id":"s20-173","number":173,"surah":20,"verses":[85],"references":[{"surah":20,"verses":[85]}],"verseLabel":"طه: 85","question":"ما دلالة استعمال مفردة الفتنة دون الابتلاء في قوله: ﴿فَإِنَّا قَدْ فَتَنَّا قَوْمَكَ﴾؟","answer":"الفتنة أشد من مطلق الاختبار؛ فهي ابتلاء شاق يكشف ما في النفوس ويميز الثابت من الضعيف. وقد ناسب اللفظ عظم اختبار بني إسرائيل بالعجل في غيبة موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص427، تحت عنوان «دلالة استعمال مفردة الفتنة دون الابتلاء»","url":""}]},{"id":"s20-88","number":88,"surah":20,"verses":[86],"references":[{"surah":20,"verses":[86]}],"verseLabel":"طه: 86","question":"ما دلالة الجمع بين ﴿غَضْبَانَ أَسِفًا﴾ في وصف رجوع موسى؟","answer":"جمع الوصفان انفعالين في نفس موسى: غضبًا شديدًا لله على انحراف قومه، وأسفًا وحزنًا على ما انتهوا إليه. فاجتمعت قوة الإنكار وألم الرحمة بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص435، تحت عنوان «سر الجمع بين صيغتي ﴿غَضْبَانَ﴾ و﴿أَسِفًا﴾»","url":""}]},{"id":"s20-89","number":89,"surah":20,"verses":[87],"references":[{"surah":20,"verses":[87]}],"verseLabel":"طه: 87","question":"ما دلالة اختلاف القراءات في قولهم: ﴿حُمِّلْنَا أَوْزَارًا﴾؟","answer":"قراءة التخفيف تفيد أنهم حملوا الأوزار مع أنفسهم، وقراءة التشديد تفيد أن موسى حملهم إياها أو أن الله ألزمهم حكمها. فتعدد القراءات يثري تصوير التبعة التي اعتذروا بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص454، تحت عنوان «توجيه القراءات في قولهم: ﴿حُمِّلْنَا﴾»","url":""}]},{"id":"s20-174","number":174,"surah":20,"verses":[87],"references":[{"surah":20,"verses":[87]}],"verseLabel":"طه: 87","question":"ما سر التعبير بالأوزار دون الأحمال في قولهم: ﴿حُمِّلْنَا أَوْزَارًا﴾؟","answer":"الأوزار توحي بثقل الحلي حسًّا، وبالتبعة والإثم معنى؛ فاختيرت بدل الأحمال لتجمع ثقل ما حملوه وثقل ما ترتب عليه من عذر ومسؤولية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص455–456، تحت عنوان «سر التعبير بالأوزار دون الأحمال»","url":""}]},{"id":"s20-90","number":90,"surah":20,"verses":[88],"references":[{"surah":20,"verses":[88]}],"verseLabel":"طه: 88","question":"ما دلالة وصف العجل بأنه ﴿جَسَدًا لَهُ خُوَارٌ﴾؟","answer":"الجسد أخص من الجسم، ويطلق هنا على صورة العجل الجامدة التي لا روح فيها ولا عقل. ففضح الوصف عبادتهم جسمًا له خوار، لكنه خال من حقيقة الحياة والإدراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص468، تحت عنوان «الجسم والجسد»","url":""}]},{"id":"s20-91","number":91,"surah":20,"verses":[89],"references":[{"surah":20,"verses":[89]}],"verseLabel":"طه: 89","question":"ما سرّ التعبير بـ﴿أَلَّا يَرْجِعُ إِلَيْهِمْ قَوْلًا وَلَا يَمْلِكُ لَهُمْ ضَرًّا وَلَا نَفْعًا﴾؟","answer":"قدم عجز العجل عن إجابة عابديه لأنه أظهر في إبطال ألوهيته وأسبق إلى الحس، ثم نفى عنه ملك الضر والنفع ليبين عجزه التام عن التصرف. فجمع عجز التواصل وعجز التأثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص476–477، تحت عنوان «علة تقديم نفي إرجاع القول على ملك الضر والنفع»","url":""}]},{"id":"s20-92","number":92,"surah":20,"verses":[90],"references":[{"surah":20,"verses":[90]}],"verseLabel":"طه: 90","question":"ما بلاغة القصر في قول هارون: ﴿إِنَّمَا فُتِنْتُمْ بِهِ﴾؟","answer":"قصر هارون أمر العجل على كونه فتنة واختبارًا، لا ربًّا يستحق العبادة. وهو قصر قلب يواجه اعتقادهم الباطل بحقيقة حاله ويدعوهم إلى الرجوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص483، تحت عنوان «بلاغة القصر بـ﴿إِنَّمَا﴾ ونوعه وغرضه»","url":""}]},{"id":"s20-175","number":175,"surah":20,"verses":[90],"references":[{"surah":20,"verses":[90]}],"verseLabel":"طه: 90","question":"ما فائدة إيثار اسم ﴿الرَّحْمَنُ﴾ في قول هارون: ﴿وَإِنَّ رَبَّكُمُ الرَّحْمَنُ﴾؟","answer":"ذكر اسم الرحمن تذكيرًا لبني إسرائيل بسابق رحمة الله وإحسانه إليهم وإنجائه لهم، وترقيقًا لقلوبهم كي يرجعوا إلى ربهم الحق ويتركوا العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص485، تحت عنوان «فائدة إيثار اسم الرحمن»","url":""}]},{"id":"s20-93","number":93,"surah":20,"verses":[91],"references":[{"surah":20,"verses":[91]}],"verseLabel":"طه: 91","question":"ما دلالة النفي بـ﴿لَنْ﴾ في قولهم: ﴿لَنْ نَبْرَحَ عَلَيْهِ عَاكِفِينَ﴾؟","answer":"دل النفي بـ﴿لن﴾ على تأكيد امتناعهم في المستقبل عن مفارقة عبادة العجل، فكشف شدة إصرارهم على الباطل ورفضهم نصح هارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص491، تحت عنوان «دلالة النفي بـ﴿لَنْ﴾»","url":""}]},{"id":"s20-176","number":176,"surah":20,"verses":[91],"references":[{"surah":20,"verses":[91]}],"verseLabel":"طه: 91","question":"ما دلالة ﴿حَتَّى﴾ في قولهم: ﴿حَتَّى يَرْجِعَ إِلَيْنَا مُوسَى﴾؟","answer":"جعلوا رجوع موسى غاية لاستمرار عكوفهم على العجل؛ فسوّفوا ترك الباطل إلى حضوره، وفي ذلك عناد وتهرب من الاستجابة لهارون.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص493، تحت عنوان «دلالة التعبير بحرف الجر ﴿حَتَّى﴾»","url":""}]},{"id":"s20-94","number":94,"surah":20,"verses":[92],"references":[{"surah":20,"verses":[92]}],"verseLabel":"طه: 92","question":"ما دلالة نداء موسى هارون باسمه في مقام العتاب؟","answer":"ناداه باسمه ﴿يا هارون﴾ في مقام التوبيخ والعتاب، لا بوصف الأخوة؛ لأن المقام يقتضي إظهار الجدية واستحضار مسؤوليته عن القوم حين استخلفه موسى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص495–496، تحت عنوان «فائدة النداء لأخيه بـ﴿يا﴾ واسمه»","url":""}]},{"id":"s20-177","number":177,"surah":20,"verses":[92],"references":[{"surah":20,"verses":[92]}],"verseLabel":"طه: 92","question":"ما بلاغة الاستفهام في قول موسى لهارون: ﴿مَا مَنَعَكَ إِذْ رَأَيْتَهُمْ ضَلُّوا﴾؟","answer":"الاستفهام مجازي غرضه الإنكار على هارون وسؤاله عن المانع من المبادرة إلى معالجة ضلال القوم واتباع أمر موسى؛ فهو عتاب يحمل معنى التوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص496، تحت عنوان «بلاغة التعبير بالاستفهام المجازي»","url":""}]},{"id":"s20-178","number":178,"surah":20,"verses":[92],"references":[{"surah":20,"verses":[92]}],"verseLabel":"طه: 92","question":"ما دلالة إضافة الأمر إلى ضمير المتكلم في قول موسى: ﴿أَفَعَصَيْتَ أَمْرِي﴾؟","answer":"أضاف موسى الأمر إلى نفسه لأنه الأمر الذي عهد به إلى هارون بأمر الله عند استخلافه؛ فإضافته تستحضر العهد والمسؤولية وتشدّد الإنكار على مخالفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص500، تحت عنوان «دلالة إضافة الأمر لضمير المتكلم»","url":""}]},{"id":"s20-95","number":95,"surah":20,"verses":[94],"references":[{"surah":20,"verses":[94]}],"verseLabel":"طه: 94","question":"ما سرّ التعبير في قول هارون ﴿يَا ابْنَ أُمَّ﴾؟","answer":"استعطف هارون موسى بندائه ﴿يا ابن أم﴾ بدل ﴿يا أخي﴾؛ لأن ذكر الأم أبلغ في استدعاء الرقة والرحمة، ولا سيما في لحظة الغضب الشديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص504، تحت عنوان «فائدة النداء بـ﴿ابْنَ أُمَّ﴾ دون ﴿يا أخي﴾»","url":""}]},{"id":"s20-96","number":96,"surah":20,"verses":[94],"references":[{"surah":20,"verses":[94]}],"verseLabel":"طه: 94","question":"ما دلالة اعتذار هارون بخشيته أن يقول موسى: ﴿فَرَّقْتَ بَيْنَ بَنِي إِسْرَائِيلَ﴾؟","answer":"جاءت جملة ﴿إني خشيت﴾ تعليلًا لترك هارون قتال عابدي العجل؛ فقد خشي أن يؤدي الاشتباك إلى تفريق بني إسرائيل وتمزيق جماعتهم قبل عودة موسى، مع بقائه منكرًا لشركهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص505، تحت عنوان «نكتة فصل جملة ﴿إِنِّي خَشِيتُ﴾»","url":""}]},{"id":"s20-97","number":97,"surah":20,"verses":[95],"references":[{"surah":20,"verses":[95]}],"verseLabel":"طه: 95","question":"ما دلالة الفاء في انتقال موسى إلى سؤال السامري: ﴿فَمَا خَطْبُكَ يَا سَامِرِيُّ﴾؟","answer":"تفيد الفاء التعقيب والسببية؛ فبعد سؤال القوم وهارون وسماع جوابهما انتقل موسى إلى السامري، لأنه المتسبب المباشر في الفتنة وصناعة العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص512، تحت عنوان «معنى الفاء في ﴿فَمَا﴾»","url":""}]},{"id":"s20-179","number":179,"surah":20,"verses":[95],"references":[{"surah":20,"verses":[95]}],"verseLabel":"طه: 95","question":"ما سر إيثار لفظ ﴿الْخَطْبُ﴾ دون الشأن في سؤال موسى للسامري؟","answer":"اختير ﴿الخطب﴾ لأنه يستعمل في الأمر العظيم المكروه؛ فناسب فظاعة فعل السامري وشناعته، وأشعر من أول السؤال بعظم الجريمة التي سيحاسب عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص513، تحت عنوان «سر إيثار لفظ الخطب دون الشأن»","url":""}]},{"id":"s20-98","number":98,"surah":20,"verses":[96],"references":[{"surah":20,"verses":[96]}],"verseLabel":"طه: 96","question":"ما دلالة ادعاء السامري: ﴿بَصُرْتُ بِمَا لَمْ يَبْصُرُوا بِهِ﴾؟","answer":"ادعى السامري علمًا اختص به دون قومه، وعبر عنه بالبصر مجازًا ليصوره معرفة يقينية كالمشاهدة؛ فكان في كلامه تعظيم لدعواه وإظهار للثقة بما زعمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص519، تحت عنوان «بلاغة المجاز في التعبير عن العلم بلفظ البصر»","url":""}]},{"id":"s20-99","number":99,"surah":20,"verses":[96],"references":[{"surah":20,"verses":[96]}],"verseLabel":"طه: 96","question":"ما دلالة الفاء في قول السامري: ﴿فَنَبَذْتُهَا﴾؟","answer":"عطفت الفاء نبذ القبضة على قبضها، فصورت سرعة إلقائها واستعمالها عقب أخذها، وربطت الفعل بنتيجة ما سبقه في اعتراف السامري.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص521، تحت عنوان «معنى الفاء في قوله: ﴿فَنَبَذْتُهَا﴾»","url":""}]},{"id":"s20-180","number":180,"surah":20,"verses":[96],"references":[{"surah":20,"verses":[96]}],"verseLabel":"طه: 96","question":"ما دلالة إسناد التسويل إلى نفس السامري في قوله: ﴿وَكَذَلِكَ سَوَّلَتْ لِي نَفْسِي﴾؟","answer":"أسند السامري التسويل إلى نفسه اعترافًا بأن هواه زيّن له الفعل القبيح حتى رآه حسنًا؛ فكشفت العبارة أن باعث صنع العجل كان حرص النفس ورغبتها فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص522–523، تحت عنوان «دلالة التعبير بالتسويل مادة وصيغة»","url":""}]},{"id":"s20-100","number":100,"surah":20,"verses":[97],"references":[{"surah":20,"verses":[97]}],"verseLabel":"طه: 97","question":"ما دلالة عقوبة السامري بقوله: ﴿أَنْ تَقُولَ لَا مِسَاسَ﴾؟","answer":"صيغ النهي عن مخالطة السامري في صورة خبر يلازمه: ﴿لا مساس﴾؛ فدل على ثبوت العقوبة ودوامها، وأنه لا يمس أحدًا ولا يمسه أحد، مبالغة في عزله عن الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص530، تحت عنوان «غرض التعبير عن النهي عن المساس بالإخبار عنه»","url":""}]},{"id":"s20-101","number":101,"surah":20,"verses":[97],"references":[{"surah":20,"verses":[97]}],"verseLabel":"طه: 97","question":"ما دلالة إلقاء فتات العجل ﴿فِي الْيَمِّ﴾؟","answer":"جعل البحر ظرفًا لنسف فتات العجل حتى تتفرق أجزاؤه في الماء ولا تبقى منه بقية يمكن جمعها أو تعظيمها؛ فكان ذلك أبلغ في استئصال الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص539، تحت عنوان «دلالة التعبير بالظرفية في شبه الجملة»","url":""}]},{"id":"s20-102","number":102,"surah":20,"verses":[98],"references":[{"surah":20,"verses":[98]}],"verseLabel":"طه: 98","question":"ما نكتة فصل قوله: ﴿وَسِعَ كُلَّ شَيْءٍ عِلْمًا﴾ عما قبله؟","answer":"جاءت الجملة مستقلة جوابًا عن سؤال مقدر: كيف يكون إله الناس واحدًا؟ فقررت أن الإله الحق محيط علمه بكل شيء، وبذلك تم الدليل على وحدانيته وبطلان عبادة العجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص545، تحت عنوان «نكتة فصل قوله: ﴿وَسِعَ كُلَّ شَيْءٍ عِلْمًا﴾»","url":""}]},{"id":"s20-181","number":181,"surah":20,"verses":[98],"references":[{"surah":20,"verses":[98]}],"verseLabel":"طه: 98","question":"ما فائدة لفظ العموم ﴿كُلَّ﴾ في قوله: ﴿وَسِعَ كُلَّ شَيْءٍ عِلْمًا﴾؟","answer":"أفاد لفظ ﴿كل﴾ شمول علم الله لجميع الأشياء بلا استثناء؛ فلا تخفى عليه خافية، وفي هذا كمال يختص به الإله الحق وينفي الألوهية عما سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص546، تحت عنوان «فائدة التعبير بلفظ العموم ﴿كُلّ﴾»","url":""}]},{"id":"s20-103","number":103,"surah":20,"verses":[99],"references":[{"surah":20,"verses":[99]}],"verseLabel":"طه: 99","question":"ما دلالة تقييد الذكر بقوله: ﴿مِنْ لَدُنَّا﴾؟","answer":"دل القيد ﴿من لدنا﴾ على أن القرآن صادر من عند الله خاصة، فزاد الذكر تشريفًا وتعظيمًا ووثّق صدقه وهدايته.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص555، تحت عنوان «فائدة القيد بالجار والمجرور ﴿مِنْ لَدُنَّا﴾»","url":""}]},{"id":"s20-182","number":182,"surah":20,"verses":[99],"references":[{"surah":20,"verses":[99]}],"verseLabel":"طه: 99","question":"ما سر التعبير بـ﴿ذِكْرًا﴾ وتنكيره في قوله: ﴿وَقَدْ آتَيْنَاكَ مِنْ لَدُنَّا ذِكْرًا﴾؟","answer":"سمي القرآن ذكرًا لما فيه من التذكير والعظة والشرف، ونُكّر اللفظ للتعظيم؛ فهو ذكر عظيم القدر كثير النفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص556، تحت عنوان «سر التعبير بـ﴿ذِكْرًا﴾ وفائدة تنكيره وتأخيره عن الجار والمجرور»","url":""}]},{"id":"s20-104","number":104,"surah":20,"verses":[100],"references":[{"surah":20,"verses":[100]}],"verseLabel":"طه: 100","question":"ما بلاغة تصوير عقوبة المعرض بقوله: ﴿يَحْمِلُ يَوْمَ الْقِيَامَةِ وِزْرًا﴾؟","answer":"صوّرت الآية تبعة الإعراض وعقوبته في هيئة حمل ثقيل يلازم صاحبه يوم القيامة، فقرّبت مشقة الجزاء وشدة وطأته بصورة محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص561، تحت عنوان «بلاغة التمثيل في قوله: ﴿يَحْمِلُ﴾»","url":""}]},{"id":"s20-105","number":105,"surah":20,"verses":[102],"references":[{"surah":20,"verses":[102]}],"verseLabel":"طه: 102","question":"ما دلالة وصف المجرمين عند الحشر بأنهم ﴿زُرْقًا﴾؟","answer":"اختير ﴿زرقًا﴾ لتصوير المجرمين يوم الحشر في هيئة مفزعة قبيحة، فقيل بزرقة عيونهم من شدة الهول، وقيل بما يظهر عليهم من أثر الخوف والعطش؛ فالوصف علامة عذابهم وإجرامهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص574، تحت عنوان «نكتة إيثار لفظ ﴿زُرْقًا﴾ على غيره»","url":""}]},{"id":"s20-106","number":106,"surah":20,"verses":[103,104],"references":[{"surah":20,"verses":[103,104]}],"verseLabel":"طه: 103-104","question":"ما نكتة إيثار ﴿يَتَخَافَتُونَ﴾ في وصف كلام المجرمين يوم القيامة؟","answer":"يصوّر التخافت خفض أصواتهم وتسررهم من شدة الهول والخوف؛ فلا يملكون الجهر، ويتبادلون الكلام في صوت خفي يناسب ذلتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص575، تحت عنوان «نكتة إيثار لفظ ﴿يَتَخَافَتُونَ﴾ عما سواه»","url":""}]},{"id":"s20-183","number":183,"surah":20,"verses":[103,104],"references":[{"surah":20,"verses":[103,104]}],"verseLabel":"طه: 103-104","question":"ما بلاغة الإيجاز في قولهم: ﴿إِنْ لَبِثْتُمْ إِلَّا عَشْرًا﴾؟","answer":"حذف المعدود وأبقى العدد ﴿عشرًا﴾ إيجازًا، لأن المقام يدل عليه؛ وفي تقديرهم المدة بعشر تصوير لاستقصار زمن الدنيا أو القبور أمام هول القيامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص576–577، تحت عنوان «بلاغة الإيجاز في ذكر العدد ﴿عَشْرًا﴾»","url":""}]},{"id":"s20-184","number":184,"surah":20,"verses":[103,104],"references":[{"surah":20,"verses":[103,104]}],"verseLabel":"طه: 103-104","question":"ما نكتة إسناد القول ﴿إِنْ لَبِثْتُمْ إِلَّا يَوْمًا﴾ إلى أمثل المجرمين؟","answer":"نسب القول إلى أمثلهم، أي أرجحهم عقلًا وطريقة، لأن تقديره أقرب في نظرهم إلى الصواب؛ ومع ذلك لم يقدّر المدة إلا يومًا، مبالغة في استقصارها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص580–581، تحت عنوان «نكتة إسناد القول إلى أمثلهم»","url":""}]},{"id":"s20-107","number":107,"surah":20,"verses":[105],"references":[{"surah":20,"verses":[105]}],"verseLabel":"طه: 105","question":"ما دلالة توكيد مصير الجبال بقوله: ﴿يَنْسِفُهَا رَبِّي نَسْفًا﴾؟","answer":"جاء ﴿نسفًا﴾ مفعولًا مطلقًا مؤكدًا للفعل، فأفاد تحقق تفتيت الجبال واستئصالها التام حتى لا يبقى من أثبت معالم الأرض شيء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص590، تحت عنوان «دلالة التعبير بالمفعول المطلق ﴿نَسْفًا﴾»","url":""}]},{"id":"s20-108","number":108,"surah":20,"verses":[107],"references":[{"surah":20,"verses":[107]}],"verseLabel":"طه: 107","question":"ما سرّ وصف الأرض بـ﴿لَا تَرَى فِيهَا عِوَجًا وَلَا أَمْتًا﴾؟","answer":"جمع النفي بين ﴿عوجًا﴾ و﴿أمتًا﴾ ليزيل عن الأرض الانخفاض والارتفاع معًا؛ فالطباق بينهما يستوعب طرفي التضاريس ويصور استواءها التام بعد نسف الجبال.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص593، تحت عنوان «بديع الطباق بين ﴿الْعِوَجِ﴾ و﴿الْأَمْتِ﴾»","url":""}]},{"id":"s20-109","number":109,"surah":20,"verses":[108],"references":[{"surah":20,"verses":[108]}],"verseLabel":"طه: 108","question":"ما سر إسناد الخشوع إلى الأصوات في ﴿وَخَشَعَتِ الْأَصْوَاتُ لِلرَّحْمَنِ﴾؟","answer":"أُسند الخشوع إلى الأصوات مجازًا لأن أثر ذل أصحابها ظهر في خفضها وخفوتها؛ فصوّر الخشوع بأبرز مظهر مسموع منه حتى لا يكاد يبقى إلا الهمس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص599، تحت عنوان «بلاغة المجاز في نسبة الخشوع إلى الأصوات»","url":""}]},{"id":"s20-110","number":110,"surah":20,"verses":[109],"references":[{"surah":20,"verses":[109]}],"verseLabel":"طه: 109","question":"ما دلالة تقييد نفع الشفاعة بإذن الرحمن ورضاه؟","answer":"جمع العطف شرطين لنفع الشفاعة: إذن الرحمن للشافع أن يتكلم، ورضاه عن قوله وشفاعته. فلا تنفع الشفاعة بذاتها ولا يستقل بها صاحبها، بل الأمر كله لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص604–605، تحت عنوان «فائدة عطف ﴿رَضِيَ﴾ على ﴿أَذِنَ﴾»","url":""}]},{"id":"s20-112","number":112,"surah":20,"verses":[111],"references":[{"surah":20,"verses":[111]}],"verseLabel":"طه: 111","question":"ما بلاغة إسناد العنت إلى الوجوه في قوله: ﴿وَعَنَتِ الْوُجُوهُ﴾؟","answer":"أُسند الخضوع والذل إلى الوجوه مجازًا لأنها موضع ظهور آثارهما، وعُبّر بها عن أصحابها؛ فصوّر الاستسلام العام لله في هيئة بادية على الوجوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص612، تحت عنوان «بلاغة المجاز في إسناد العنت للوجوه»","url":""}]},{"id":"s20-113","number":113,"surah":20,"verses":[112],"references":[{"surah":20,"verses":[112]}],"verseLabel":"طه: 112","question":"ما دلالة الجمع بين نفي الظلم والهضم في ﴿فَلَا يَخَافُ ظُلْمًا وَلَا هَضْمًا﴾؟","answer":"عُطف الهضم على الظلم لأنهما جانبان مختلفان من الجور: الظلم أن يُحمّل الإنسان سيئة لم يعملها، والهضم أن يُنقص من حسناته؛ فنفت الآية الزيادة عليه والنقص من حقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص618، تحت عنوان «بلاغة عطف ﴿هَضْمًا﴾ على ﴿ظُلْمًا﴾»","url":""}]},{"id":"s20-114","number":114,"surah":20,"verses":[113],"references":[{"surah":20,"verses":[113]}],"verseLabel":"طه: 113","question":"ما سر إيثار الفعل ﴿صَرَّفْنَا﴾ في قوله: ﴿وَكَذَلِكَ أَنْزَلْنَاهُ قُرْآنًا عَرَبِيًّا وَصَرَّفْنَا فِيهِ مِنَ الْوَعِيدِ﴾؟","answer":"دل ﴿صرفنا﴾ على تنويع الوعيد وتكريره في أساليب متعددة، لتقوم الحجة وتفتح للنفوس طرقًا مختلفة تردعها وتورثها التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص623، تحت عنوان «سر إيثار الفعل ﴿صَرَّفْنَا﴾ في السياق»","url":""}]},{"id":"s20-185","number":185,"surah":20,"verses":[113],"references":[{"surah":20,"verses":[113]}],"verseLabel":"طه: 113","question":"ما سر العدول إلى قوله: ﴿أَوْ يُحْدِثُ لَهُمْ ذِكْرًا﴾؟","answer":"عبّر بإحداث الذكر لا بمجرد التذكير لأن آيات الوعيد قد تنشئ في النفس تذكرًا جديدًا وآثارًا متجددة، بعد غفلة أو نسيان، فتحمل صاحبها على الاتعاظ.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص625، تحت عنوان «سر العدول عن ﴿يُذَكِّرُهُمْ﴾ إلى ﴿يُحْدِثُ لَهُمْ ذِكْرًا﴾»","url":""}]},{"id":"s20-115","number":115,"surah":20,"verses":[114],"references":[{"surah":20,"verses":[114]}],"verseLabel":"طه: 114","question":"ما سرّ التعبير بـ﴿وَلَا تَعْجَلْ بِالْقُرْآنِ مِنْ قَبْلِ أَنْ يُقْضَى إِلَيْكَ وَحْيُهُ﴾؟","answer":"نُهي النبي ﷺ عن مبادرة جبريل بتلاوة القرآن قبل تمام الوحي، مع شدة حرصه على حفظه؛ ليكون التلقي أولًا كاملًا مطمئنًا، ثم تأتي القراءة والترديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص634–635، تحت عنوان «النهي في الآية عن التعجل بالقرآن»","url":""}]},{"id":"s20-116","number":116,"surah":20,"verses":[114],"references":[{"surah":20,"verses":[114]}],"verseLabel":"طه: 114","question":"ما دلالة عطف الأمر ﴿وَقُلْ رَبِّ زِدْنِي عِلْمًا﴾ على النهي عن العجلة بالقرآن؟","answer":"وصلت الواو بين النهي والأمر لتدل على أن ترك العجلة لا يعني فتور طلب العلم؛ بل يضبط الشوق بحسن التلقي، ثم يوجهه إلى سؤال الله الزيادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص637، تحت عنوان «دلالة الواو وعطف النهي بالأمر»","url":""}]},{"id":"s20-186","number":186,"surah":20,"verses":[114],"references":[{"surah":20,"verses":[114]}],"verseLabel":"طه: 114","question":"ما سر إيثار طلب الزيادة من العلم في قوله: ﴿رَبِّ زِدْنِي عِلْمًا﴾؟","answer":"أُمر بطلب الزيادة من العلم لأن العلم لا ينتهي إلى حد يستغني معه العبد عن تعليم ربه؛ وفيه تشريف للعلم، وحث على دوام التعلم مع التواضع لله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص638، تحت عنوان «سر إيثار طلب الزيادة من العلم»","url":""}]},{"id":"s20-117","number":117,"surah":20,"verses":[115],"references":[{"surah":20,"verses":[115]}],"verseLabel":"طه: 115","question":"ما بلاغة التعبير بالنسيان في قوله: ﴿فَنَسِيَ﴾ عن آدم؟","answer":"يجوز أن يكون النسيان حقيقيًا، أو مجازًا عن ترك العهد وعدم مراعاته؛ وفي التعبير إظهار لضعف الإنسان من غير أن يكون عذرًا يرفع تبعة المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص648، تحت عنوان «بلاغة التعبير بالنسيان بين الحقيقة والمجاز»","url":""}]},{"id":"s20-187","number":187,"surah":20,"verses":[115],"references":[{"surah":20,"verses":[115]}],"verseLabel":"طه: 115","question":"ما دلالة استعمال لفظ ﴿الْعَزْمِ﴾ في قوله: ﴿وَلَمْ نَجِدْ لَهُ عَزْمًا﴾؟","answer":"العزم قوة الثبات على الأمر؛ فنفيه يصور أن آدم لم يثبت على الوفاء بالعهد عند وسوسة إبليس، لا أنه تعمد الإصرار على المعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص650، تحت عنوان «دلالة استعمال لفظ العزم دون غيره»","url":""}]},{"id":"s20-188","number":188,"surah":20,"verses":[115],"references":[{"surah":20,"verses":[115]}],"verseLabel":"طه: 115","question":"ما دلالة تقديم خاتمة قصة آدم في قوله: ﴿وَلَقَدْ عَهِدْنَا إِلَى آدَمَ مِنْ قَبْلُ فَنَسِيَ﴾؟","answer":"قدمت خلاصة القصة قبل تفصيل أحداثها تمهيدًا للعبرة وإجمالًا لما سيشرح؛ فتهيأ السامع لقصة الضعف والمخالفة ثم الاجتباء والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص651، تحت عنوان «دلالة تقديم ذكر خاتمة قصة آدم على أحداثها»","url":""}]},{"id":"s20-118","number":118,"surah":20,"verses":[116],"references":[{"surah":20,"verses":[116]}],"verseLabel":"طه: 116","question":"ما سرّ التعبير بـ﴿أَبَى﴾ في موقف إبليس؟","answer":"اختير ﴿أبى﴾ لأن الإباء امتناع عن قبول الأمر مع رفض واستكبار، لا مجرد ترك للسجود ولا نسيان له؛ ففضح موقف إبليس النفسي من الأمر الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص660، تحت عنوان «سر التعبير بالإباء دون غيره من مرادفاته»","url":""}]},{"id":"s20-119","number":119,"surah":20,"verses":[117],"references":[{"surah":20,"verses":[117]}],"verseLabel":"طه: 117","question":"ما سرّ تسمية إبليس ﴿عَدُوٌّ لَكَ وَلِزَوْجِكَ﴾ قبل الوسوسة؟","answer":"أُخبر آدم وزوجه بعداوة إبليس قبل وسوسته ليعرفا حقيقة الناصح المزيف ويحذرا إغراءه؛ فإذا أتاهما قامت عليهما الحجة بالتحذير السابق من عدوهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص668، تحت عنوان «علة الإخبار عن إبليس بأنه عدو لآدم وزوجه ابتداء»","url":""}]},{"id":"s20-120","number":120,"surah":20,"verses":[117],"references":[{"surah":20,"verses":[117]}],"verseLabel":"طه: 117","question":"ما سرّ التعبير بـ﴿فَلَا يُخْرِجَنَّكُمَا مِنَ الْجَنَّةِ فَتَشْقَى﴾ فأفرد الشقاء؟","answer":"أفرد ﴿فتشقى﴾ بعد تثنية ﴿يخرجنكما﴾ لأن آدم هو المخاطب الأول، ولأن تعب تحصيل المعاش بعد الخروج يبرز في حقه؛ كما أن شقاء أحد الزوجين يمتد أثره إلى الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص671، تحت عنوان «سر إسناد ﴿فَتَشْقَى﴾ إلى الضمير المفرد العائد على آدم»","url":""}]},{"id":"s20-121","number":121,"surah":20,"verses":[118,119],"references":[{"surah":20,"verses":[118,119]}],"verseLabel":"طه: 118-119","question":"ما نكتة العدول عن التصريح بنعيم الجنة إلى نفي نقائضه؟","answer":"وُصف نعيم الجنة بنفي الجوع والعري والظمأ والضحى لأن زوال هذه الآفات أبلغ في إشعار آدم بالأمن وكمال الكفاية، ويزيد التحذير من فقدانها بالخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص677، تحت عنوان «نكتة العدول عن التصريح بالنعم إلى نفي نقائضها»","url":""}]},{"id":"s20-189","number":189,"surah":20,"verses":[118,119],"references":[{"surah":20,"verses":[118,119]}],"verseLabel":"طه: 118-119","question":"ما سر تخصيص الجوع والعري والظمأ والضحى بالذكر في نعيم الجنة؟","answer":"جمعت المذكورات أصول الحاجة البدنية: الطعام بنفي الجوع، والكسوة بنفي العري، والشراب بنفي الظمأ، والكن أو الظل بنفي الضحى.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص681، تحت عنوان «سر تخصيص المذكورات الأربع»","url":""}]},{"id":"s20-122","number":122,"surah":20,"verses":[120],"references":[{"surah":20,"verses":[120]}],"verseLabel":"طه: 120","question":"ما دلالة إضافة الشجرة إلى الخلد في قول إبليس: ﴿شَجَرَةِ الْخُلْدِ﴾؟","answer":"أضاف الشجرة إلى الخلد زعمًا أنها سبب البقاء الدائم؛ فزيّن المعصية لآدم بإثارة رغبته في دوام الحياة وعدم الفناء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص690، تحت عنوان «دلالة إضافة الشجرة إلى الخلد»","url":""}]},{"id":"s20-190","number":190,"surah":20,"verses":[120],"references":[{"surah":20,"verses":[120]}],"verseLabel":"طه: 120","question":"ما فائدة عطف ﴿وَمُلْكٍ لَا يَبْلَى﴾ على ﴿شَجَرَةِ الْخُلْدِ﴾؟","answer":"جمع إبليس في إغرائه بين رغبتين: الخلود في الحياة، ودوام السلطان والنعيم؛ فزاد بالعطف بابًا آخر من الترغيب في المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص691، تحت عنوان «فائدة عطف ﴿وَمُلْكٍ لَا يَبْلَى﴾ على ما قبله»","url":""}]},{"id":"s20-191","number":191,"surah":20,"verses":[120],"references":[{"surah":20,"verses":[120]}],"verseLabel":"طه: 120","question":"ما بلاغة إطلاق البِلى على الملك في قوله: ﴿وَمُلْكٍ لَا يَبْلَى﴾؟","answer":"استعير البِلى، وهو تآكل الثوب، للملك الذي يضعف ويزول؛ فنفيه صوّر الملك المزعوم ثابتًا لا ينقص ولا يفنى، وهو من تزيين إبليس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص691، تحت عنوان «بلاغة المجاز في إطلاق البلى على الملك»","url":""}]},{"id":"s20-123","number":123,"surah":20,"verses":[121],"references":[{"surah":20,"verses":[121]}],"verseLabel":"طه: 121","question":"ما دلالة الفاء في قوله: ﴿فَبَدَتْ لَهُمَا سَوْآتُهُمَا﴾؟","answer":"ربطت الفاء ظهور سوآتهما بالأكل من الشجرة، فصورت سرعة تعاقب أثر المخالفة على فعلها وانكشاف ما كان مستورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص698، تحت عنوان «معنى الفاء في ﴿فَبَدَتْ﴾»","url":""}]},{"id":"s20-192","number":192,"surah":20,"verses":[121],"references":[{"surah":20,"verses":[121]}],"verseLabel":"طه: 121","question":"ما سر إيثار لفظ ﴿سَوْآتُهُمَا﴾ في قصة آدم وزوجه؟","answer":"اختيرت السوأة لأنها ما يسوء الإنسان انكشافه ويحرص على ستره؛ فناسب اللفظ شعورهما بالخجل ومسارعتهما إلى تغطية ما ظهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص699، تحت عنوان «سر إيثار التعبير بلفظ ﴿سَوْآتُهُمَا﴾»","url":""}]},{"id":"s20-124","number":124,"surah":20,"verses":[121],"references":[{"surah":20,"verses":[121]}],"verseLabel":"طه: 121","question":"ما نكتة التعبير بـ﴿طَفِقَا﴾ في ستر آدم وزوجه سوآتهما؟","answer":"دل ﴿طفقا﴾ على الشروع السريع والاستمرار في الفعل، فصوّر مبادرتهما إلى الستر فور انكشاف سوآتهما وشدة حرصهما عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص699، تحت عنوان «نكتة التعبير بالفعل ﴿طَفِقَا﴾»","url":""}]},{"id":"s20-125","number":125,"surah":20,"verses":[122],"references":[{"surah":20,"verses":[122]}],"verseLabel":"طه: 122","question":"ما سر التعبير باجتباء آدم في قوله: ﴿ثُمَّ اجْتَبَاهُ رَبُّهُ﴾؟","answer":"الاجتباء اصطفاء واختيار مع تقريب؛ فدل على أن الله أعاد آدم إلى مقام القرب بعد زلته، وفتح له باب الرحمة والإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص703، تحت عنوان «سر التعبير بالفعل ﴿اجْتَبَاهُ﴾»","url":""}]},{"id":"s20-193","number":193,"surah":20,"verses":[122],"references":[{"surah":20,"verses":[122]}],"verseLabel":"طه: 122","question":"ما فائدة تكرار لفظ ﴿رَبُّهُ﴾ عند اجتباء آدم؟","answer":"أُظهر وصف الربوبية في مقام الاجتباء لإبراز رعاية الله لعبده وتربيته ورحمته بعد الزلة؛ فالمقام مقام إصلاح وقبول لا يأس.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص704، تحت عنوان «فائدة تكرار لفظ ﴿رَبُّهُ﴾ في الاجتباء»","url":""}]},{"id":"s20-194","number":194,"surah":20,"verses":[122],"references":[{"surah":20,"verses":[122]}],"verseLabel":"طه: 122","question":"ما سر الجمع بين التوبة والهداية في قوله: ﴿فَتَابَ عَلَيْهِ وَهَدَى﴾؟","answer":"جمع له بين قبول رجوعه ومحو أثر زلته بالتوبة، وبين توفيقه إلى طريق الخير والثبات عليه بالهداية؛ فتمت له الرحمة والإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص704، تحت عنوان «سر الجمع بين التوبة والهداية»","url":""}]},{"id":"s20-126","number":126,"surah":20,"verses":[123],"references":[{"surah":20,"verses":[123]}],"verseLabel":"طه: 123","question":"ما دلالة الجملة الحالية: ﴿بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ﴾؟","answer":"بيّنت الجملة أن الهبوط إلى الأرض يقع مصحوبًا بالعداوة، ولا سيما عداوة الشيطان للإنسان وما ينشأ عنها من صراع وضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص711، تحت عنوان «دلالة التقييد بالجملة الحالية بعد التقييد بالحال الصريحة»","url":""}]},{"id":"s20-127","number":127,"surah":20,"verses":[123],"references":[{"surah":20,"verses":[123]}],"verseLabel":"طه: 123","question":"ما سرّ التعبير بـ﴿فَمَنِ اتَّبَعَ هُدَايَ فَلَا يَضِلُّ وَلَا يَشْقَى﴾؟","answer":"جمع الوعد بين نفي الضلال ونفي الشقاء؛ فمن اتبع هدى الله سلم من الانحراف في طريقه، ونجا من سوء العاقبة المترتب عليه، فاجتمع له الهدى والسعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص714، تحت عنوان «دلالة الجمع بين نفي الضلال ونفي الشقاء»","url":""}]},{"id":"s20-128","number":128,"surah":20,"verses":[124],"references":[{"surah":20,"verses":[124]}],"verseLabel":"طه: 124","question":"ما دلالة وصف معيشة المعرض عن الذكر بأنها ﴿ضَنْكًا﴾؟","answer":"جاء ﴿ضنكًا﴾ مصدرًا يوصف به للمبالغة، فصوّر معيشة المعرض شديدة الضيق ملازمة له؛ ويدخل فيها ضيق القلب ولو اتسع ظاهر رزقه، كما تشمل وجوهًا من عذاب الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص722، تحت عنوان «بلاغة المصدر ﴿ضَنْكًا﴾ باعتباره لفظًا فريدًا»","url":""}]},{"id":"s20-129","number":129,"surah":20,"verses":[125,126],"references":[{"surah":20,"verses":[125,126]}],"verseLabel":"طه: 125-126","question":"ما دلالة استفهام الأعمى يوم القيامة: ﴿لِمَ حَشَرْتَنِي أَعْمَى وَقَدْ كُنْتُ بَصِيرًا﴾؟","answer":"استفهم متعجبًا مستنكرًا ما آل إليه، وجعل بصره السابق موضع احتجاج؛ فكشف السؤال جهله بسبب الجزاء وعجزه عن الدفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص723، تحت عنوان «دلالة الاستفهام في الآية»","url":""}]},{"id":"s20-130","number":130,"surah":20,"verses":[127],"references":[{"surah":20,"verses":[127]}],"verseLabel":"طه: 127","question":"ما نكتة التعبير بـ﴿أَسْرَفَ﴾ في قوله: ﴿وَكَذَلِكَ نَجْزِي مَنْ أَسْرَفَ﴾؟","answer":"اختير الإسراف لأنه مجاوزة الحد، فجمع ما وقعوا فيه من إفراط في الكفر والتكذيب والإعراض، وبيّن أن الجزاء ناشئ عن تجاوزهم حدود الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص735، تحت عنوان «نكتة التعبير بـ﴿أَسْرَفَ﴾ مادة وصيغة»","url":""}]},{"id":"s20-195","number":195,"surah":20,"verses":[127],"references":[{"surah":20,"verses":[127]}],"verseLabel":"طه: 127","question":"ما نكتة التعبير بـ﴿أَشَدُّ﴾ في قوله: ﴿وَلَعَذَابُ الْآخِرَةِ أَشَدُّ﴾؟","answer":"جاء اسم التفضيل ﴿أشد﴾ ليقارن عذاب الآخرة بما يعاينه المكذبون من عقوبات الدنيا، فيقرر أن عذابها أعظم قوة وأبلغ إيلامًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص739، تحت عنوان «نكتة التعبير بـ﴿أَشَدُّ﴾ دون شديد»","url":""}]},{"id":"s20-196","number":196,"surah":20,"verses":[127],"references":[{"surah":20,"verses":[127]}],"verseLabel":"طه: 127","question":"ما بلاغة وصف عذاب الآخرة بأنه ﴿أَبْقَى﴾؟","answer":"وصفه بأنه ﴿أبقى﴾ ليبين دوام عذاب الآخرة وعدم انقطاعه، فيجتمع فيه مع شدة الألم طول المكث بخلاف عقوبة الدنيا الزائلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص740، تحت عنوان «بلاغة وصف العذاب بقوله: ﴿وَأَبْقَى﴾»","url":""}]},{"id":"s20-131","number":131,"surah":20,"verses":[128],"references":[{"surah":20,"verses":[128]}],"verseLabel":"طه: 128","question":"ما دلالة تخصيص ﴿أُولِي النُّهَى﴾ بالانتفاع بآيات هلاك القرون؟","answer":"وصفهم بأولي النهى لأن عقولهم تنهاهم عن الباطل وتردعهم عن سلوك طريق المكذبين؛ فهم الذين يتجاوزون مجرد المرور بمساكن الهالكين إلى الاتعاظ بعاقبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص759، تحت عنوان «سر التعبير بـ﴿أُولِي النُّهَى﴾ دون أولي الألباب»","url":""}]},{"id":"s20-132","number":132,"surah":20,"verses":[129],"references":[{"surah":20,"verses":[129]}],"verseLabel":"طه: 129","question":"ما نكتة التعبير بـ﴿لِزَامًا﴾ في قوله: ﴿لَكَانَ لِزَامًا﴾؟","answer":"دل ﴿لزامًا﴾ على عذاب لازم لا يفارق المكذبين، وجاء بالمصدر للمبالغة في تحقق اللزوم؛ ولولا كلمة الإمهال السابقة لعاجلهم هذا الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص768، تحت عنوان «نكتة التعبير بـ﴿لِزَامًا﴾ مادة وصيغة»","url":""}]},{"id":"s20-133","number":133,"surah":20,"verses":[130],"references":[{"surah":20,"verses":[130]}],"verseLabel":"طه: 130","question":"ما فائدة عطف التسبيح على الأمر بالصبر في قوله: ﴿فَاصْبِرْ عَلَى مَا يَقُولُونَ وَسَبِّحْ بِحَمْدِ رَبِّكَ﴾؟","answer":"عطف التسبيح على الصبر لأن ذكر الله والصلاة زاد يعين الرسول على احتمال أذى المكذبين، وينقل القلب من الانشغال بأقوالهم إلى الثناء على ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص776، تحت عنوان «فائدة عطف التسبيح على الأمر بالصبر»","url":""}]},{"id":"s20-197","number":197,"surah":20,"verses":[130],"references":[{"surah":20,"verses":[130]}],"verseLabel":"طه: 130","question":"ما بلاغة التعبير عن الصلاة بالتسبيح في قوله: ﴿وَسَبِّحْ بِحَمْدِ رَبِّكَ﴾؟","answer":"عُبّر عن الصلاة بالتسبيح لأنها مشتملة عليه، ولأن تنزيه الله وحمده روح عبادتها؛ فذكر أبرز مقاصدها وأشرف أجزائها وأراد العبادة كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص778، تحت عنوان «بلاغة المجاز في التعبير عن الصلاة بالتسبيح»","url":""}]},{"id":"s20-198","number":198,"surah":20,"verses":[130],"references":[{"surah":20,"verses":[130]}],"verseLabel":"طه: 130","question":"ما فائدة عطف ﴿وَأَطْرَافَ النَّهَارِ﴾ بعد ذكر أوقات التسبيح؟","answer":"أكمل العطف استيعاب أوقات الصلاة والذكر في جوانب النهار، فضم إلى ما قبل طلوع الشمس وقبل غروبها سائر الأطراف المناسبة للعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص784، تحت عنوان «فائدة عطف ﴿وَأَطْرَافَ النَّهَارِ﴾»","url":""}]},{"id":"s20-134","number":134,"surah":20,"verses":[131],"references":[{"surah":20,"verses":[131]}],"verseLabel":"طه: 131","question":"ما بلاغة النهي عن مد العينين في قوله: ﴿لَا تَمُدَّنَّ عَيْنَيْكَ﴾؟","answer":"صوّر مد العينين إطالة النظر المصحوب بالإعجاب والتطلع إلى ما في أيدي المترفين، فنهى عن تعلق القلب بزينة لا تدوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص793، تحت عنوان «بلاغة المجاز في قوله: ﴿لَا تَمُدَّنَّ عَيْنَيْكَ﴾»","url":""}]},{"id":"s20-199","number":199,"surah":20,"verses":[131],"references":[{"surah":20,"verses":[131]}],"verseLabel":"طه: 131","question":"ما بلاغة وصف متاع الدنيا بأنه ﴿زَهْرَةَ الْحَيَاةِ الدُّنْيَا﴾؟","answer":"شبّه زينة الدنيا بزهرة حسنة المنظر سريعة الذبول؛ فهي تفتن عند إقبالها، لكن جمالها عارض وعمرها قصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص798، تحت عنوان «بلاغة التشبيه في قوله: ﴿زَهْرَةَ الْحَيَاةِ الدُّنْيَا﴾»","url":""}]},{"id":"s20-200","number":200,"surah":20,"verses":[131],"references":[{"surah":20,"verses":[131]}],"verseLabel":"طه: 131","question":"ما سر التعبير بالفتنة في قوله: ﴿لِنَفْتِنَهُمْ فِيهِ﴾؟","answer":"سمّى ما مُتعوا به فتنة لأنه اختبار يكشف موقفهم: أيشكرون المنعم ويستعملون النعمة في طاعته، أم يغترون بها ويعرضون؟","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص800، تحت عنوان «سر التعبير بالفتنة في قوله: ﴿لِنَفْتِنَهُمْ فِيهِ﴾»","url":""}]},{"id":"s20-135","number":135,"surah":20,"verses":[131],"references":[{"surah":20,"verses":[131]}],"verseLabel":"طه: 131","question":"ما سر التعبير بـ﴿رِزْقُ رَبِّكَ﴾ بعد النهي عن التطلع إلى زهرة الدنيا؟","answer":"قابل زهرة الدنيا الزائلة برزق منسوب إلى الرب، ليطمئن الرسول والمؤمن إلى أن ما يمنحه الله من هداية وقناعة وثواب خير من متاع المفتونين وأدوم أثرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج32، ص801، تحت عنوان «سر التعبير بالرزق دون غيره»","url":""}]},{"id":"s20-136","number":136,"surah":20,"verses":[132],"references":[{"surah":20,"verses":[132]}],"verseLabel":"طه: 132","question":"ما دلالة تخصيص الأهل بالأمر في قوله: ﴿وَأْمُرْ أَهْلَكَ بِالصَّلَاةِ﴾؟","answer":"خُص الأهل لأنهم أولى الناس بالرعاية والتعليم، ولأن إصلاح البيت بالصلاة يجعل الدعوة سلوكًا معاشًا يبدأ من أقرب الدوائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص12، تحت عنوان «دلالة الإتيان بلفظ ﴿أَهْلَكَ﴾»","url":""}]},{"id":"s20-201","number":201,"surah":20,"verses":[132],"references":[{"surah":20,"verses":[132]}],"verseLabel":"طه: 132","question":"ما دلالة صيغة ﴿وَاصْطَبِرْ عَلَيْهَا﴾ في الأمر بالصلاة؟","answer":"صيغة الاصطبار أقوى من مطلق الصبر؛ فهي تدل على معالجة النفس ومداومة احتمال مشقة المحافظة على الصلاة وأمر الأهل بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص13، تحت عنوان «دلالة صيغة ﴿وَاصْطَبِرْ﴾»","url":""}]},{"id":"s20-137","number":137,"surah":20,"verses":[132],"references":[{"surah":20,"verses":[132]}],"verseLabel":"طه: 132","question":"ما نكتة تنكير ﴿رِزْقًا﴾ في قوله: ﴿لَا نَسْأَلُكَ رِزْقًا﴾؟","answer":"نُكّر الرزق في سياق النفي ليفيد العموم: لا يطلب الله من عبده شيئًا من الرزق، وإنما يطلب منه العبادة والطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص15، تحت عنوان «نكتة تنكير ﴿رِزْقًا﴾»","url":""}]},{"id":"s20-202","number":202,"surah":20,"verses":[132],"references":[{"surah":20,"verses":[132]}],"verseLabel":"طه: 132","question":"ما نكتة تقديم ﴿نَحْنُ﴾ في قوله: ﴿نَحْنُ نَرْزُقُكَ﴾؟","answer":"قُدّم الضمير لتقوية الحكم وإبراز أن الله هو المتكفل بالرزق، فيزول وهم أن الاشتغال بالصلاة يضيّع المعاش.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص17، تحت عنوان «نكتة تقديم المسند في قوله: ﴿نَحْنُ نَرْزُقُكَ﴾»","url":""}]},{"id":"s20-138","number":138,"surah":20,"verses":[133],"references":[{"surah":20,"verses":[133]}],"verseLabel":"طه: 133","question":"ما نكتة العدول من قولهم: ﴿بِآيَةٍ مِنْ رَبِّهِ﴾ إلى وصف القرآن بأنه ﴿الْبَيِّنَةُ﴾؟","answer":"طلبوا آية مقترحة تعنتًا، فواجههم القرآن بوصفه البينة: حجة ظاهرة جامعة لما في الصحف الأولى، لا مجرد علامة حسية عابرة؛ فظهر أن اعتراضهم ليس لنقص الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص27، تحت عنوان «نكتة اختيار البينة بدل آية»","url":""}]},{"id":"s20-139","number":139,"surah":20,"verses":[134],"references":[{"surah":20,"verses":[134]}],"verseLabel":"طه: 134","question":"ما بلاغة التعبير بالشرط في قولهم: ﴿لَوْلَا أَرْسَلْتَ إِلَيْنَا رَسُولًا فَنَتَّبِعَ آيَاتِكَ﴾؟","answer":"صيغ كلامهم في صورة شرط ليصور العذر الذي كانوا سيتعللون به لو عوجلوا بالعذاب قبل الرسالة، وقد قطع إرسال الرسول هذا الاعتذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص31، تحت عنوان «بلاغة التعبير بالجملة الشرطية»","url":""}]},{"id":"s20-203","number":203,"surah":20,"verses":[134],"references":[{"surah":20,"verses":[134]}],"verseLabel":"طه: 134","question":"ما سر الجمع بين الذل والخزي في قوله: ﴿مِنْ قَبْلِ أَنْ نَذِلَّ وَنَخْزَى﴾؟","answer":"جمعوا بين الذل، وهو الهوان والقهر، والخزي، وهو الفضيحة والعار؛ فاستوعب التعبير سوء حالهم ظاهرًا وباطنًا لو نزل بهم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص38، تحت عنوان «سر التعبير بالذل والخزي عن الهلاك»","url":""}]},{"id":"s20-140","number":140,"surah":20,"verses":[135],"references":[{"surah":20,"verses":[135]}],"verseLabel":"طه: 135","question":"ما بلاغة ربط ختام سورة طه بمطلعها؟","answer":"افتتحت السورة ببيان أن القرآن تذكرة لا سبب شقاء، وختمت بأن العاقبة ستكشف أهل الصراط السوي والمهتدين؛ فجمع الطرفان بين وظيفة الوحي وظهور ثمرة اتباعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص49، تحت عنوان «بلاغة ربط ختام السورة بمطلعها»","url":""}]},{"id":"s21-1","number":1,"surah":21,"verses":[1],"references":[{"surah":21,"verses":[1]}],"verseLabel":"الأنبياء: 1","question":"ما دلالة التعبير بالاقتراب في قوله: ﴿اقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ﴾؟","answer":"دل الاقتراب على قرب الحساب وتحقق وقوعه، وحث على الاستعداد له؛ فكل آت قريب وإن استبعده الغافلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص65، تحت عنوان «دلالة التعبير بالاقتراب»","url":""}]},{"id":"s21-106","number":106,"surah":21,"verses":[1],"references":[{"surah":21,"verses":[1]}],"verseLabel":"الأنبياء: 1","question":"ما بلاغة إسناد الاقتراب إلى الحساب في قوله: ﴿اقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ﴾؟","answer":"جُعل الحساب نفسه مقبلًا يقترب من الناس، فحوّل المعنى الزمني إلى مشهد متحرك يداهم الغافلين ويزيد الإحساس بسرعة مجيئه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص65، تحت عنوان «بلاغة إسناد الاقتراب إلى الحساب»","url":""}]},{"id":"s21-2","number":2,"surah":21,"verses":[1],"references":[{"surah":21,"verses":[1]}],"verseLabel":"الأنبياء: 1","question":"ما نكتة التعبير بحرف الظرفية في قوله: ﴿فِي غَفْلَةٍ﴾؟","answer":"جعلتهم ﴿في﴾ الغفلة كأنها ظرف يحيط بهم، فصوّر تمكنها منهم واستغراقهم فيها مع اقتراب الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص68–69، تحت عنوان «نكتة التعبير بحرف الظرفية»","url":""}]},{"id":"s21-107","number":107,"surah":21,"verses":[1],"references":[{"surah":21,"verses":[1]}],"verseLabel":"الأنبياء: 1","question":"ما غرض تقديم ﴿فِي غَفْلَةٍ﴾ على قوله: ﴿مُعْرِضُونَ﴾؟","answer":"قدّم شبه الجملة لإبراز إحاطة الغفلة بهم، ثم جاء الإعراض فعلًا ناشئًا عنها؛ فجمع بين فساد الداخل وصدود الظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص69، تحت عنوان «غرض تقديم شبه الجملة»","url":""}]},{"id":"s21-3","number":3,"surah":21,"verses":[2],"references":[{"surah":21,"verses":[2]}],"verseLabel":"الأنبياء: 2","question":"ما فائدة إضافة الذكر إلى ربهم في قوله: ﴿مِنْ ذِكْرٍ مِنْ رَبِّهِمْ مُحْدَثٍ﴾؟","answer":"إضافة الذكر إلى ﴿ربهم﴾ تذكّرهم بأن المنزل هو الذي خلقهم وربّاهم ويتولى إصلاحهم؛ فكان الأولى أن يتلقوا ذكره بالطاعة لا باللعب والإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص72، تحت عنوان «فائدة إضافة الذكر إلى الضمير»","url":""}]},{"id":"s21-4","number":4,"surah":21,"verses":[2],"references":[{"surah":21,"verses":[2]}],"verseLabel":"الأنبياء: 2","question":"ما دلالة اجتماع الاستماع واللعب في قوله تعالى: ﴿اسْتَمَعُوهُ وَهُمْ يَلْعَبُونَ﴾؟","answer":"الواو للحال؛ فكانوا يستمعون القرآن في حال لعب ولهو، فجمع المشهد بين حضور الصوت وغياب الانتفاع، وكشف أن استماعهم لم يكن طلبًا للهدى بل استهانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص74، تحت عنوان «نوع الواو ودلالتها في قوله: ﴿وَهُمْ يَلْعَبُونَ﴾»","url":""}]},{"id":"s21-5","number":5,"surah":21,"verses":[3],"references":[{"surah":21,"verses":[3]}],"verseLabel":"الأنبياء: 3","question":"ما بلاغة إسناد اللهو إلى القلوب في قوله: ﴿لَاهِيَةً قُلُوبُهُمْ﴾؟","answer":"أُسند اللهو إلى القلوب لأنها محل القصد والفهم، فدل على أن انصرافهم لم يكن حركة ظاهرة فحسب، بل غفلة استولت على باطنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص81، تحت عنوان «بلاغة المجاز المرسل»","url":""}]},{"id":"s21-108","number":108,"surah":21,"verses":[3],"references":[{"surah":21,"verses":[3]}],"verseLabel":"الأنبياء: 3","question":"ما نكتة تقديم اللعب على لهو القلوب في قوله: ﴿وَهُمْ يَلْعَبُونَ لَاهِيَةً قُلُوبُهُمْ﴾؟","answer":"ذُكر اللعب الظاهر أولًا لأنه المشاهد، ثم كشف النص سببه الأعمق وهو لهو القلوب؛ فانتقل من السلوك إلى الدافع الباطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص81، تحت عنوان «نكتة تقديم اللعب على اللهو»","url":""}]},{"id":"s21-6","number":6,"surah":21,"verses":[3],"references":[{"surah":21,"verses":[3]}],"verseLabel":"الأنبياء: 3","question":"ما بلاغة الكناية في قوله: ﴿وَأَسَرُّوا النَّجْوَى﴾؟","answer":"كَنَى إسرار النجوى عن شدة حرصهم على كتمان تدبيرهم وعداوتهم، لكن القرآن كشف حديثهم الخفي، فظهر إحاطة علم الله بما يسرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص82، تحت عنوان «بلاغة الكناية في اختيار فعل ﴿وَأَسَرُّوا﴾»","url":""}]},{"id":"s21-7","number":7,"surah":21,"verses":[3],"references":[{"surah":21,"verses":[3]}],"verseLabel":"الأنبياء: 3","question":"ما غرض الاستفهام في قولهم: ﴿هَلْ هَذَا إِلَّا بَشَرٌ مِثْلُكُمْ﴾؟","answer":"الاستفهام إنكاري قصدوا به نفي النبوة عن الرسول لمجرد بشريته، وفيه تعجيب أتباعهم منه وتنفيرهم من قبول دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص85، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s21-109","number":109,"surah":21,"verses":[3],"references":[{"surah":21,"verses":[3]}],"verseLabel":"الأنبياء: 3","question":"كيف ردت السورة شبهة امتناع إرسال رسول من البشر؟","answer":"ردت بأن سنة الله في الرسل السابقين أنهم رجال يوحى إليهم؛ فالبشرية ليست مناقضة للرسالة، بل هي الأصل الذي يتيح للناس الاقتداء بالرسول وفهم خطابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص112، تحت عنوان «معنى الواو ودلالتها في قوله: ﴿وَمَا أَرْسَلْنَا﴾»","url":""}]},{"id":"s21-8","number":8,"surah":21,"verses":[4],"references":[{"surah":21,"verses":[4]}],"verseLabel":"الأنبياء: 4","question":"ما سر العدول من ﴿النجوى﴾ إلى ﴿القول﴾ في قوله تعالى: ﴿رَبِّي يَعْلَمُ الْقَوْلَ فِي السَّمَاءِ وَالْأَرْضِ﴾؟","answer":"القول أعم من النجوى، فيشمل ما يجهرون به وما يسرونه. فالعدول إليه يدخل نجواهم في علم الله الشامل، وينبه إلى أنه يعلم السر والجهر على السواء، ويحذرهم مما سيقولونه أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص93–94، تحت عنوان «فائدة العدول عن ﴿النجوى﴾ إلى لفظ ﴿القول﴾»","url":""}]},{"id":"s21-9","number":9,"surah":21,"verses":[5],"references":[{"surah":21,"verses":[5]}],"verseLabel":"الأنبياء: 5","question":"ما دلالة تنقلهم بين ﴿أَضْغَاثُ أَحْلَامٍ﴾ و﴿افْتَرَاهُ﴾ و﴿شَاعِرٌ﴾؟","answer":"تكرار ﴿بل﴾ يحكي انتقالهم بين أقوال متضاربة في القرآن، ويكشف اضطرابهم وترددهم في الاعتراض عليه. ويذكر المبحث احتمال صدور هذه الأوصاف من فريق واحد أو من فرق مختلفة؛ فلا يلزم أن يكون كل قائل قد قالها جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص99–100، تحت عنوان «نوع ﴿بل﴾ ونكتة تكرارها في سياق واحد»","url":""}]},{"id":"s21-10","number":10,"surah":21,"verses":[6],"references":[{"surah":21,"verses":[6]}],"verseLabel":"الأنبياء: 6","question":"ما دلالة الاستفهام في قوله تعالى: ﴿مَا آمَنَتْ قَبْلَهُمْ مِنْ قَرْيَةٍ أَهْلَكْنَاهَا أَفَهُمْ يُؤْمِنُونَ﴾؟","answer":"الاستفهام ينكر ظن أنهم سيؤمنون إذا أُعطوا الآية التي اقترحوها؛ فالأمم المهلكة قبلهم لم تؤمن بما اقترحت. وبذلك يكشف تعنت الطلب، لا نقص الدليل القائم عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص107، تحت عنوان «بلاغة الاستفهام ونوعه وغرضه»","url":""}]},{"id":"s21-11","number":11,"surah":21,"verses":[7,25],"references":[{"surah":21,"verses":[7,25]}],"verseLabel":"الأنبياء: 7، 25","question":"ما سر مجيء ﴿وَمَا أَرْسَلْنَا قَبْلَكَ﴾ بلا «من» في الآية 7، ومجيء ﴿وَمَا أَرْسَلْنَا مِنْ قَبْلِكَ مِنْ رَسُولٍ﴾ في الآية 25؟","answer":"حُذفت ﴿من﴾ في الآية السابعة لأن السياق متصل بذكر القرى والرسل السابقين من غير حاجة إلى مزيد استغراق، وأُثبتت في الآية الخامسة والعشرين لتؤكد ابتداء الامتداد من الزمن السابق وعموم كل رسول أرسل قبل محمد ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص113، تحت عنوان «توجيه المتشابه اللفظي بالحذف والذكر»","url":""}]},{"id":"s21-13","number":13,"surah":21,"verses":[8],"references":[{"surah":21,"verses":[8]}],"verseLabel":"الأنبياء: 8","question":"ما فائدة تقييد الجسد بقوله: ﴿لَا يَأْكُلُونَ الطَّعَامَ﴾؟","answer":"النفي لم يتجه إلى كون الرسل أجسادًا، وإنما نفى أن يكونوا أجسادًا لا تأكل؛ فالقيد يقرر بشريتهم وحاجتهم إلى الطعام ويرد توهم الملكية.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص123، تحت عنوان «فائدة التقييد بالوصف»","url":""}]},{"id":"s21-110","number":110,"surah":21,"verses":[8],"references":[{"surah":21,"verses":[8]}],"verseLabel":"الأنبياء: 8","question":"ما فائدة عطف قوله: ﴿وَمَا كَانُوا خَالِدِينَ﴾ على بشرية الرسل؟","answer":"أضاف العطف نفيًا آخر: فكما أن الرسل يأكلون الطعام فهم أيضًا يموتون؛ وبذلك رد على من استبعد الرسالة لبشرية الرسول أو انتظر خلوده.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص124، تحت عنوان «معنى الواو وفائدة العطف بين الجمل»","url":""}]},{"id":"s21-14","number":14,"surah":21,"verses":[9],"references":[{"surah":21,"verses":[9]}],"verseLabel":"الأنبياء: 9","question":"ما دلالة ﴿ثُمَّ﴾ في قوله تعالى: ﴿ثُمَّ صَدَقْنَاهُمُ الْوَعْدَ﴾؟","answer":"يحتمل أن تكون ﴿ثم﴾ للتراخي الرتبي، لإبراز شأن إنجاز الوعد ونجاة الرسل وهلاك مكذبيهم؛ ويحتمل أن تكون للتراخي الزمني، إذ طال تكذيب الأقوام وصبر الرسل قبل تحقق الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص124، تحت عنوان «نوع ﴿ثم﴾ ودلالتها في السياق»","url":""}]},{"id":"s21-15","number":15,"surah":21,"verses":[10],"references":[{"surah":21,"verses":[10]}],"verseLabel":"الأنبياء: 10","question":"ما فائدة تقديم ﴿فِيهِ﴾ في قوله: ﴿فِيهِ ذِكْرُكُمْ﴾؟","answer":"قُدّم شبه الجملة للاهتمام بالكتاب والتنبيه إلى أن موضع شرفهم وموعظتهم وخبرهم الحق هو هذا القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص132، تحت عنوان «فائدة تقديم شبه الجملة»","url":""}]},{"id":"s21-111","number":111,"surah":21,"verses":[10],"references":[{"surah":21,"verses":[10]}],"verseLabel":"الأنبياء: 10","question":"ما نكتة إضافة الذكر إلى ضمير المخاطبين في قوله: ﴿ذِكْرُكُمْ﴾؟","answer":"أضيف الذكر إليهم لاستمالتهم إلى القرآن؛ فهو يتضمن شرفهم ورفعة شأنهم إن آمنوا به، كما يتضمن ما يوقظهم ويعظهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص132، تحت عنوان «نكتة إضافة الذكر إلى ضميرهم»","url":""}]},{"id":"s21-16","number":16,"surah":21,"verses":[11],"references":[{"surah":21,"verses":[11]}],"verseLabel":"الأنبياء: 11","question":"ما دلالة الصورة في قوله تعالى: ﴿وَكَمْ قَصَمْنَا مِنْ قَرْيَةٍ﴾؟","answer":"أصل القصم كسر الشيء الصلب، واستعير لإهلاك أهل القرى الجبارين الذين كانوا في قوة ومنعة. فالصورة لا تكتفي بالإخبار عن هلاكهم، بل تجسد شدة الإهلاك واستئصال قوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص138، تحت عنوان «بلاغة الاستعارة في لفظ القصم»","url":""}]},{"id":"s21-17","number":17,"surah":21,"verses":[12],"references":[{"surah":21,"verses":[12]}],"verseLabel":"الأنبياء: 12","question":"ما دلالة ﴿إِذَا﴾ في قوله تعالى: ﴿إِذَا هُمْ مِنْهَا يَرْكُضُونَ﴾؟","answer":"هي للمفاجأة؛ فبمجرد إحساسهم بالبأس بادروا إلى الهرب من غير توقف. وبهذا تصور الآية انقلاب حالهم بغتة وشدة الفزع الذي حملهم على الفرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص143، تحت عنوان «معنى ﴿إذا﴾ في: ﴿إذا هم منها يركضون﴾»","url":""}]},{"id":"s21-18","number":18,"surah":21,"verses":[13],"references":[{"surah":21,"verses":[13]}],"verseLabel":"الأنبياء: 13","question":"ما دلالة الأمر بالرجوع في قوله تعالى: ﴿لَا تَرْكُضُوا وَارْجِعُوا إِلَى مَا أُتْرِفْتُمْ فِيهِ﴾؟","answer":"أُمروا بالرجوع إلى ترفهم السابق على سبيل التهكم والتقريع، بعدما دفعهم العذاب إلى الفرار؛ فصار تذكيرهم بعزهم ونعيمهم السابق إظهارًا لما انتهوا إليه من ذلة وهوان.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص146–147، تحت عنوان «إيثار التعبير بفعل الرجوع أمرًا: ﴿وارجعوا﴾»","url":""}]},{"id":"s21-19","number":19,"surah":21,"verses":[15],"references":[{"surah":21,"verses":[15]}],"verseLabel":"الأنبياء: 15","question":"ما سر تسمية قولهم ﴿يَا وَيْلَنَا إِنَّا كُنَّا ظَالِمِينَ﴾ بـ﴿دَعْوَاهُمْ﴾؟","answer":"سمي دعوى لأنهم يدعون بالويل والثبور على أنفسهم، مقرّين بأنهم ظلموا في حياتهم السابقة. ولفظ الدعوى هنا يجمع نداءهم بالهلاك واعترافهم بالظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص158، تحت عنوان «إيثار التعبير بلفظ الدعوى، ومرجع ضميرها»","url":""}]},{"id":"s21-20","number":20,"surah":21,"verses":[15],"references":[{"surah":21,"verses":[15]}],"verseLabel":"الأنبياء: 15","question":"ما دلالة الصورة في قوله تعالى: ﴿حَصِيدًا خَامِدِينَ﴾؟","answer":"شُبّهوا بزرع استُؤصل بالحصاد، وبنار انطفأت ولم يبق منها إلا الجمر المنطفئ؛ فجمعت الصورة بين استئصالهم وسكونهم بعد الحياة والحركة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص160، تحت عنوان «بلاغة التعبير بقوله: ﴿حصيدًا خامدين﴾»","url":""}]},{"id":"s21-21","number":21,"surah":21,"verses":[16],"references":[{"surah":21,"verses":[16]}],"verseLabel":"الأنبياء: 16","question":"ما دلالة نفي اللعب في قوله تعالى: ﴿وَمَا خَلَقْنَا السَّمَاءَ وَالْأَرْضَ وَمَا بَيْنَهُمَا لَاعِبِينَ﴾؟","answer":"اللعب فعل لا يقصد به مقصد صحيح ولا تراعى فيه الحكمة، فنفيه ينزه الخلق عن العبث. فالسماوات والأرض خُلقتا بحكمة، وجُعلتا مجالًا لمعاش الإنسان ودليلًا يقوده إلى معرفة خالقه وعبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص166، تحت عنوان «التعبير بلفظ (اللعب) ودلالته»","url":""}]},{"id":"s21-22","number":22,"surah":21,"verses":[17],"references":[{"surah":21,"verses":[17]}],"verseLabel":"الأنبياء: 17","question":"ما دلالة ﴿لَوْ﴾ في قوله: ﴿لَوْ أَرَدْنَا أَنْ نَتَّخِذَ لَهْوًا﴾؟","answer":"جاءت ﴿لو﴾ لامتناع الجواب لامتناع الشرط؛ فنفت أصل إرادة اتخاذ اللهو، وتنزه الله عن العبث الذي توهمه المبطلون.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص168، تحت عنوان «دلالة ﴿لَوْ﴾ في قوله: ﴿لَوْ أَرَدْنَا﴾»","url":""}]},{"id":"s21-112","number":112,"surah":21,"verses":[17],"references":[{"surah":21,"verses":[17]}],"verseLabel":"الأنبياء: 17","question":"ما دلالة قوله: ﴿لَاتَّخَذْنَاهُ مِنْ لَدُنَّا﴾؟","answer":"يفيد ﴿من لدنا﴾ أنه ـ على الفرض الممتنع ـ يكون من جهة غيب الله واختصاصه، لا مما يزعمونه من الصاحبة والولد من خلقه؛ وفي ذلك إبطال لمقالتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص172، تحت عنوان «معنى ﴿مِنْ﴾ في قوله: ﴿مِنْ لَدُنَّا﴾»","url":""}]},{"id":"s21-23","number":23,"surah":21,"verses":[18],"references":[{"surah":21,"verses":[18]}],"verseLabel":"الأنبياء: 18","question":"ما دلالة الصورة في قوله تعالى: ﴿بَلْ نَقْذِفُ بِالْحَقِّ عَلَى الْبَاطِلِ﴾؟","answer":"صُوّر الحق والباطل، وهما معنيان، في صورة محسوسة يتجلى فيها القذف والدمغ؛ لتجسيد غلبة الحق وإبطاله للباطل إبطالًا تامًّا، كإصابة جسم قوي شيئًا ضعيفًا فيحطمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص179، تحت عنوان «بلاغة الاستعارة في فعل القذف والدمغ»","url":""}]},{"id":"s21-24","number":24,"surah":21,"verses":[18],"references":[{"surah":21,"verses":[18]}],"verseLabel":"الأنبياء: 18","question":"ما بلاغة التعبير بالدمغ في قوله: ﴿فَيَدْمَغُهُ﴾؟","answer":"صوّر إصابة الحق للباطل بضربة تبلغ الدماغ فتقضي عليه، فدل على قوة الحجة واستئصال الباطل لا مجرد إضعافه.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص181، تحت عنوان «بلاغة التعبير بفعل الدمغ واختياره هنا»","url":""}]},{"id":"s21-113","number":113,"surah":21,"verses":[18],"references":[{"surah":21,"verses":[18]}],"verseLabel":"الأنبياء: 18","question":"ما دلالة ﴿إِذَا﴾ في قوله: ﴿فَإِذَا هُوَ زَاهِقٌ﴾؟","answer":"جاءت ﴿إذا﴾ الفجائية لتصوّر سرعة زوال الباطل عند صدمة الحق؛ فما إن يصيبه حتى يظهر هالكًا مضمحلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص182، تحت عنوان «معنى ﴿إِذَا﴾ في قوله: ﴿فَإِذَا هُوَ زَاهِقٌ﴾»","url":""}]},{"id":"s21-25","number":25,"surah":21,"verses":[19],"references":[{"surah":21,"verses":[19]}],"verseLabel":"الأنبياء: 19","question":"ما دلالة عطف ﴿وَلَا يَسْتَحْسِرُونَ﴾ على قوله: ﴿لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِ﴾؟","answer":"جمع العطف نفي مانعين من العبادة: فلا يترفع الملائكة عنها استكبارًا، ولا ينقطعون عنها تعبًا وعجزًا؛ فعبادتهم طوعية دائمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص191، تحت عنوان «دلالة العطف في قوله: ﴿وَلَا يَسْتَحْسِرُونَ﴾ ومعناها»","url":""}]},{"id":"s21-114","number":114,"surah":21,"verses":[19],"references":[{"surah":21,"verses":[19]}],"verseLabel":"الأنبياء: 19","question":"ما بلاغة صيغة الاستفعال في قوله: ﴿يَسْتَحْسِرُونَ﴾؟","answer":"تفيد صيغة الاستفعال بلوغ غاية الإعياء وطلب الراحة بعد شدة التعب؛ فنفيها أبلغ في بيان دوام نشاط الملائكة في العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص191–192، تحت عنوان «بلاغة التعبير بـ﴿يَسْتَحْسِرُونَ﴾ على صيغة الاستفعال»","url":""}]},{"id":"s21-26","number":26,"surah":21,"verses":[20],"references":[{"surah":21,"verses":[20]}],"verseLabel":"الأنبياء: 20","question":"ما سر تخصيص الليل والنهار بالذكر في قوله: ﴿يُسَبِّحُونَ اللَّيْلَ وَالنَّهَارَ﴾؟","answer":"ذُكر الليل والنهار لاستيعاب الزمن كله، أي إن تسبيح الملائكة متصل في جميع الأوقات لا يختص بساعة دون أخرى.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص193، تحت عنوان «سر تخصيص الليل والنهار بالذكر»","url":""}]},{"id":"s21-115","number":115,"surah":21,"verses":[20],"references":[{"surah":21,"verses":[20]}],"verseLabel":"الأنبياء: 20","question":"ما دلالة المضارع في قوله: ﴿لَا يَفْتُرُونَ﴾؟","answer":"دل المضارع على تجدد نفي الفتور واستمراره؛ فهم يواصلون التسبيح من غير ضعف ولا انقطاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص193، تحت عنوان «إيثار التعبير بالمضارع ﴿يَفْتُرُونَ﴾»","url":""}]},{"id":"s21-27","number":27,"surah":21,"verses":[21],"references":[{"surah":21,"verses":[21]}],"verseLabel":"الأنبياء: 21","question":"ما سر تقييد الآلهة بكونها ﴿مِنَ الْأَرْضِ﴾؟","answer":"ذكّر القيد بحقيقة الأصنام؛ فهي مصنوعة من مواد أرضية وموضوعة في الأرض، وفي ذلك تحقير لها وتوبيخ لمن رفعها إلى مقام الألوهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص201، تحت عنوان «سر تقييد وصف الآلهة بكونها ﴿مِنَ الْأَرْضِ﴾»","url":""}]},{"id":"s21-116","number":116,"surah":21,"verses":[21],"references":[{"surah":21,"verses":[21]}],"verseLabel":"الأنبياء: 21","question":"ما سر إيثار ﴿يُنْشِرُونَ﴾ في وصف الآلهة المزعومة؟","answer":"الإنشار إحياء الموتى وبعثهم، فاختير لاستحضار أعظم آثار القدرة الإلهية على سبيل التهكم بعجز الأصنام؛ فهي لا تملك بعث ميت فكيف تكون آلهة؟","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص202، تحت عنوان «إيثار التعبير بالفعل ﴿يُنْشِرُونَ﴾ دون غيره»","url":""}]},{"id":"s21-28","number":28,"surah":21,"verses":[22],"references":[{"surah":21,"verses":[22]}],"verseLabel":"الأنبياء: 22","question":"ما دلالة التعبير بـ﴿لَفَسَدَتَا﴾ في قوله تعالى: ﴿لَوْ كَانَ فِيهِمَا آلِهَةٌ إِلَّا اللَّهُ لَفَسَدَتَا﴾؟","answer":"الفساد خروج الشيء عن الصلاح والاعتدال؛ فتعدد الآلهة يقتضي اختلال تدبير السماوات والأرض. ولما استقام الكون على نظام محكم دل انتظامه على وحدانية مدبره.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص207، تحت عنوان «دلالة التعبير بلفظ الفساد دون غيره»","url":""}]},{"id":"s21-29","number":29,"surah":21,"verses":[23],"references":[{"surah":21,"verses":[23]}],"verseLabel":"الأنبياء: 23","question":"ما بلاغة نفي السؤال عن الله وإثباته للمخلوقين في قوله: ﴿لَا يُسْأَلُ عَمَّا يَفْعَلُ وَهُمْ يُسْأَلُونَ﴾؟","answer":"نفي سؤال المحاسبة والاعتراض عن الله كناية عن كمال حكمته وملكه، وإثباته للمخلوقين يقرر عبوديتهم ومسؤوليتهم؛ فبرز الفرق بين الخالق والمخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص214، تحت عنوان «بلاغة الكناية في فعل السؤال»","url":""}]},{"id":"s21-30","number":30,"surah":21,"verses":[24],"references":[{"surah":21,"verses":[24]}],"verseLabel":"الأنبياء: 24","question":"ما دلالة الأمر في قوله تعالى: ﴿هَاتُوا بُرْهَانَكُمْ﴾؟","answer":"الأمر للتعجيز وإلزام الحجة؛ فقد طُلب منهم أن يقدموا دليلًا على استحقاق آلهتهم العبادة، وهم عاجزون عن ذلك، فظهر بطلان دعواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص221، تحت عنوان «سر التعبير بفعل الأمر وبيانه»","url":""}]},{"id":"s21-31","number":31,"surah":21,"verses":[25],"references":[{"surah":21,"verses":[25]}],"verseLabel":"الأنبياء: 25","question":"ما فائدة التعبير بالمصدر المؤول في قوله: ﴿أَنَّهُ لَا إِلَهَ إِلَّا أَنَا﴾؟","answer":"جعل مضمون الوحي حقيقة ثابتة جامعة لدعوة جميع الرسل: لا معبود بحق إلا الله؛ فاختلاف الشرائع لا يغير أصل التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص238، تحت عنوان «فائدة التعبير بالمصدر المؤول»","url":""}]},{"id":"s21-117","number":117,"surah":21,"verses":[25],"references":[{"surah":21,"verses":[25]}],"verseLabel":"الأنبياء: 25","question":"ما دلالة الفاء في قوله: ﴿فَاعْبُدُونِ﴾ بعد تقرير التوحيد؟","answer":"فرّعت الفاء الأمر بالعبادة على انفراد الله بالألوهية؛ فما دام هو الإله وحده فهو المستحق وحده للطاعة والعبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص239–240، تحت عنوان «معنى الفاء ودلالتها في ﴿فَاعْبُدُونِ﴾»","url":""}]},{"id":"s21-32","number":32,"surah":21,"verses":[26],"references":[{"surah":21,"verses":[26]}],"verseLabel":"الأنبياء: 26","question":"ما سر الاعتراض بـ﴿سُبْحَانَهُ﴾ بعد قولهم: ﴿اتَّخَذَ الرَّحْمَنُ وَلَدًا﴾؟","answer":"جاء التنزيه اعتراضًا فوريًا يرد الدعوى قبل تفصيل إبطالها؛ لأن اتخاذ الولد يقتضي الحاجة والمشابهة، والله منزه عنهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص245، تحت عنوان «سر التعبير بجملة الاعتراض ﴿سُبْحَانَهُ﴾»","url":""}]},{"id":"s21-118","number":118,"surah":21,"verses":[26],"references":[{"surah":21,"verses":[26]}],"verseLabel":"الأنبياء: 26","question":"ما بلاغة الإضراب بـ﴿بَلْ﴾ في قوله: ﴿بَلْ عِبَادٌ مُكْرَمُونَ﴾؟","answer":"أبطلت ﴿بل﴾ دعوى البنوة وانتقلت إلى الحقيقة المقابلة: الملائكة عباد أكرمهم الله، وعبوديتهم تنافي أن يكونوا أولادًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص245، تحت عنوان «بلاغة الإضراب بـ﴿بَلْ﴾»","url":""}]},{"id":"s21-33","number":33,"surah":21,"verses":[27],"references":[{"surah":21,"verses":[27]}],"verseLabel":"الأنبياء: 27","question":"ما فائدة الجملة الخبرية: ﴿لَا يَسْبِقُونَهُ بِالْقَوْلِ﴾؟","answer":"قررت الجملة ثبات أدب الملائكة وطاعتهم؛ فلا يقولون شيئًا قبل أمر الله أو إذنه، بل يتبع قولهم قوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص251، تحت عنوان «فائدة الجملة الخبرية»","url":""}]},{"id":"s21-119","number":119,"surah":21,"verses":[27],"references":[{"surah":21,"verses":[27]}],"verseLabel":"الأنبياء: 27","question":"لماذا خُص نفي سبق الملائكة بالقول دون العمل؟","answer":"خُص القول لأنه أسرع صدورًا وأخف مؤونة من العمل؛ فإذا لم يسبقوه به كانوا عن سبقه بالفعل أبعد، فكان النفي أبلغ في الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص251، تحت عنوان «نكتة تخصيص نفي السبق بالقول دون العمل»","url":""}]},{"id":"s21-34","number":34,"surah":21,"verses":[28],"references":[{"surah":21,"verses":[28]}],"verseLabel":"الأنبياء: 28","question":"ما بلاغة الطباق في قوله: ﴿يَعْلَمُ مَا بَيْنَ أَيْدِيهِمْ وَمَا خَلْفَهُمْ﴾؟","answer":"جمع الطرفان أحوال الملائكة كلها في علم الله، ماضيها ومستقبلها أو ظاهرها وخفيها، فدل الطباق على الإحاطة التامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص258، تحت عنوان «بديع الطباق»","url":""}]},{"id":"s21-120","number":120,"surah":21,"verses":[28],"references":[{"surah":21,"verses":[28]}],"verseLabel":"الأنبياء: 28","question":"ما فائدة عطف قوله: ﴿وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَى﴾؟","answer":"أضاف العطف أن شفاعة الملائكة ليست مستقلة؛ فهي مقصورة على من رضي الله عنه، فبطل تعلق المشركين بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص258–259، تحت عنوان «فائدة عطف جملة القصر في قوله: ﴿وَلَا يَشْفَعُونَ إِلَّا لِمَنِ ارْتَضَى﴾»","url":""}]},{"id":"s21-35","number":35,"surah":21,"verses":[30],"references":[{"surah":21,"verses":[30]}],"verseLabel":"الأنبياء: 30","question":"ما دلالة التعبير بـ﴿كَانَتَا رَتْقًا فَفَتَقْنَاهُمَا﴾؟","answer":"الرتق هو الالتئام دون فرجة، والتعبير بالمصدر يصوّر السماوات والأرض كشيء واحد ملتصق، مبالغةً في اتحادهما قبل الفتق. وذكر المبحث أيضًا تفسير الرتق بانحباس المطر والنبات، والفتق بنزول المطر وخروج النبات؛ فلا يُحصر المعنى في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص278–279، تحت عنوان «سر التعبير بلفظ ﴿رتقًا﴾»","url":""}]},{"id":"s21-36","number":36,"surah":21,"verses":[30],"references":[{"surah":21,"verses":[30]}],"verseLabel":"الأنبياء: 30","question":"ما دلالة ﴿مِنَ الْمَاءِ﴾ في قوله ﴿وَجَعَلْنَا مِنَ الْمَاءِ كُلَّ شَيْءٍ حَيٍّ﴾؟","answer":"تحتمل ﴿من﴾ السببية، أي جعلنا بسبب الماء كل شيء حيًّا، وتحتمل ابتداء الغاية، أي جعلنا مبدأ خلق كل شيء حي من الماء. يجمع الوجهان الدلالة على ارتباط الحياة بالماء، من جهة نشأتها أو قيامها به.","sources":[{"label":"موسوعة التفسير البلاغي، ج33، ص283، تحت عنوان «معنى ﴿من﴾ ودلالتها»","url":""}]}]);
